declare
  payload jsonb := $hebrew_payload$[{"chunk_code":"HC1-A1","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"א","chunk_title":"סקירת הזמן ומצוות התלויות בארץ","chunk_summary":"הקדמה ללימוד הלכות הפרשת חלה ותרומות ומעשרות, שמקורן בקדושת ארץ ישראל אך יש להן השלכות מעשיות גם בחוץ לארץ.","content_markdown":"### א. *הקדמה למצוות הפרשת חלה*\n\nבעז\"ה ב'זמן' הזה נלמד את המצוות התלויות בארץ, בפרט את מצוות הפרשת חלה ותרומות ומעשרות. מצוות אלו אמנם נובעות מקדושת ארץ ישראל ולכן הן נקראות מצוות התלויות בארץ, אבל נראה להלן שהפרשת חלה שייכת גם בחוץ לארץ, ויש מקרים רבים למעשה בהם גם תרומות ומעשרות שייכים בחוץ לארץ. ניתן ללמוד על חשיבות מצוות אלו מדברי חז\"ל. ה**גמרא סוטה** (יד, א) מסבירה שמשה רבינו השתוקק להיכנס לארץ ישראל כדי שתהיה לו ההזדמנות לקיים את המצוות התלויות בארץ. בימינו, התברכנו במיליוני יהודים שגרים ומבקרים בארץ ישראל, ואנו מאמינים בביאת המשיח במהרה בימינו. לכן, הלכות אלו רלוונטיות מאוד, בין למי שגר בארץ ישראל ובין למי שבחו\"ל.\n\nרוב ה'זמן' יוקדש ללימוד הלכות הפרשת חלה, מצוה ששייכת בכל העולם ולגביה נאמר במדרש **בראשית רבה** (פ\"א, א) שהעולם נברא בזכות מצוה זו. בהקדמה זו, נבאר האם מצות הפרשת חלה היא דאורייתא או דרבנן.","content_document":{"version":1,"language":"he","blocks":[{"kind":"heading","paragraph":2,"xmlIndex":2,"text":"הקדמה למצוות הפרשת חלה","spans":[{"text":"הקדמה למצוות הפרשת חלה","italic":true,"color":"#2F5496"}],"marker":"א.","level":0,"indent":56,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"rightIndent":43.2,"hanging":18,"tabStops":[{"position":150.45,"alignment":"left","leader":"none"},{"position":234,"alignment":"center","leader":"none"},{"position":279,"alignment":"left","leader":"none"}]},{"kind":"paragraph","paragraph":3,"xmlIndex":4,"text":"בעז\"ה ב'זמן' הזה נלמד את המצוות התלויות בארץ, בפרט את מצוות הפרשת חלה ותרומות ומעשרות. מצוות אלו אמנם נובעות מקדושת ארץ ישראל ולכן הן נקראות מצוות התלויות בארץ, אבל נראה להלן שהפרשת חלה שייכת גם בחוץ לארץ, ויש מקרים רבים למעשה בהם גם תרומות ומעשרות שייכים בחוץ לארץ. ניתן ללמוד על חשיבות מצוות אלו מדברי חז\"ל. הגמרא סוטה (יד, א) מסבירה שמשה רבינו השתוקק להיכנס לארץ ישראל כדי שתהיה לו ההזדמנות לקיים את המצוות התלויות בארץ. בימינו, התברכנו במיליוני יהודים שגרים ומבקרים בארץ ישראל, ואנו מאמינים בביאת המשיח במהרה בימינו. לכן, הלכות אלו רלוונטיות מאוד, בין למי שגר בארץ ישראל ובין למי שבחו\"ל.","spans":[{"text":"בעז\"ה ב'זמן' הזה נלמד את המצוות התלויות בארץ, בפרט את מצוות הפרשת חלה ותרומות ומעשרות. מצוות אלו אמנם נובעות מקדושת ארץ ישראל ולכן הן נקראות מצוות התלויות בארץ, אבל נראה להלן שהפרשת חלה שייכת גם בחוץ לארץ, ויש מקרים רבים למעשה בהם גם תרומות ומעשרות שייכים בחוץ לארץ. ניתן ללמוד על חשיבות מצוות אלו מדברי חז\"ל. ה"},{"text":"גמרא סוטה","bold":true},{"text":" (יד, א) מסבירה שמשה רבינו השתוקק להיכנס לארץ ישראל כדי שתהיה לו ההזדמנות לקיים את המצוות התלויות בארץ. בימינו, התברכנו במיליוני יהודים שגרים ומבקרים בארץ ישראל, ואנו מאמינים בביאת המשיח במהרה בימינו. לכן, הלכות אלו רלוונטיות מאוד, בין למי שגר בארץ ישראל ובין למי שבחו\"ל."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":4,"xmlIndex":5,"text":"רוב ה'זמן' יוקדש ללימוד הלכות הפרשת חלה, מצוה ששייכת בכל העולם ולגביה נאמר במדרש בראשית רבה (פ\"א, א) שהעולם נברא בזכות מצוה זו. בהקדמה זו, נבאר האם מצות הפרשת חלה היא דאורייתא או דרבנן.","spans":[{"text":"רוב ה'זמן' יוקדש ללימוד הלכות הפרשת חלה, מצוה ששייכת בכל העולם ולגביה נאמר במדרש "},{"text":"בראשית רבה","bold":true},{"text":" (פ\"א, א) שהעולם נברא בזכות מצוה זו. בהקדמה זו, נבאר האם מצות הפרשת חלה היא דאורייתא או דרבנן."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"def85f5240b153ad5217d84666849453bfe93fd29b0dda5806b2c51e99ad7191"},{"chunk_code":"HC1-A2","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"א","chunk_title":"מקור מצוות חלה בתורה ודין טבל","chunk_summary":"התורה מצווה לתת לכהן את ראשית העיסה ומכנה את החלה ״תרומה״; העיסה אסורה באכילה כדין טבל עד להפרשת החלה.","content_markdown":"התורה ב**במדבר** (טו, יז-כא) (1) מלמדת שכאשר עם ישראל ייכנסו לארץ ישראל עליהם לתת את החלק הראשון של העיסה לכהן. התורה מתייחסת להפרשת חלה כ\"תרומה\", ונלמד להלן שיש נוהגים שהמילה \"תרומה\" כלולה בברכה על הפרשת חלה.[1] אם כן, כשאדם מכין בצק (בכמות שתבואר להלן), יש לבצק מעמד של \"טבל\" (כמו יבול שעדיין לא הפרישו ממנו תרומות ומעשרות). רק אחרי שהופרשה חלה הבצק נעשה מותר באכילה.[2]\n\nSource Notes\n\n[1]:  ועוד, כאשר הכהן היה אוכל חלה, הוא היה מברך \"אשר קדשנו בקדשו של אהרן וצוונו לאכול תרומה\"; ראה רמ\"א שכב, ה.\n\n[2]:  ראה רמב\"ם ביכורים פ\"ח, ה, שפסק שמי שאוכל טבל של חלה חייב מיתה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":5,"xmlIndex":6,"text":"התורה בבמדבר (טו, יז-כא) (1) מלמדת שכאשר עם ישראל ייכנסו לארץ ישראל עליהם לתת את החלק הראשון של העיסה לכהן. התורה מתייחסת להפרשת חלה כ\"תרומה\", ונלמד להלן שיש נוהגים שהמילה \"תרומה\" כלולה בברכה על הפרשת חלה.[1] אם כן, כשאדם מכין בצק (בכמות שתבואר להלן), יש לבצק מעמד של \"טבל\" (כמו יבול שעדיין לא הפרישו ממנו תרומות ומעשרות). רק אחרי שהופרשה חלה הבצק נעשה מותר באכילה.[2]","spans":[{"text":"התורה ב"},{"text":"במדבר","bold":true},{"text":" (טו, יז-כא) (1) מלמדת שכאשר עם ישראל ייכנסו לארץ ישראל עליהם לתת את החלק הראשון של העיסה לכהן. התורה מתייחסת להפרשת חלה כ\"תרומה\", ונלמד להלן שיש נוהגים שהמילה \"תרומה\" כלולה בברכה על הפרשת חלה."},{"text":"[1]","footnote":1},{"text":" אם כן, כשאדם מכין בצק (בכמות שתבואר להלן), יש לבצק מעמד של \"טבל\" (כמו יבול שעדיין לא הפרישו ממנו תרומות ומעשרות). רק אחרי שהופרשה חלה הבצק נעשה מותר באכילה."},{"text":"[2]","footnote":2}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[1,2],"defaultTabWidth":36}],"footnotes":[{"id":1,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" ועוד, כאשר הכהן היה אוכל חלה, הוא היה מברך \"אשר קדשנו בקדשו של אהרן וצוונו לאכול תרומה\"; ראה רמ\"א שכב, ה.","spans":[{"text":" ועוד, כאשר הכהן היה אוכל חלה, הוא היה מברך \"אשר קדשנו בקדשו של אהרן וצוונו לאכול תרומה\"; ראה רמ\"א שכב, ה."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":2,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" ראה רמב\"ם ביכורים פ\"ח, ה, שפסק שמי שאוכל טבל של חלה חייב מיתה.","spans":[{"text":" ראה רמב\"ם ביכורים פ\"ח, ה, שפסק שמי שאוכל טבל של חלה חייב מיתה."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[1],"approved_hash":"fe2f3687d14128a9f1f9de3cb90c1055844ffdb7463efee0753abd73431daf42"},{"chunk_code":"HC1-A3","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"א","chunk_title":"״בבואכם״ — מתי מתחיל חיוב חלה","chunk_summary":"לפי רש״י בשם הספרי, בניגוד לשאר המצוות התלויות בארץ, מצוות חלה חלה מיד בכניסת ישראל לארץ, עוד לפני הכיבוש והחלוקה.","content_markdown":"**רש\"י** מביא ספרי, שמלמד שלגבי שאר המצוות התלויות בארץ, התורה משתמשת בלשון \"כי תבוא\" או \"כי תבואו\", שמלמדת שהמצווה מתחילה רק אחרי כיבוש וישוב הארץ, תהליך שלמעשה ארך 14 שנה מאז שעם ישראל חצו את הירדן. לעומת זאת, לגבי חלה, התורה משתמשת בלשון \"בבואכם\", ומשמע שהמצווה נכנסת לתוקף מיד כשעם ישראל נכנסים לארץ, אפילו לפני שסיימו לכבוש וליישב אותה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":6,"xmlIndex":7,"text":"רש\"י מביא ספרי, שמלמד שלגבי שאר המצוות התלויות בארץ, התורה משתמשת בלשון \"כי תבוא\" או \"כי תבואו\", שמלמדת שהמצווה מתחילה רק אחרי כיבוש וישוב הארץ, תהליך שלמעשה ארך 14 שנה מאז שעם ישראל חצו את הירדן. לעומת זאת, לגבי חלה, התורה משתמשת בלשון \"בבואכם\", ומשמע שהמצווה נכנסת לתוקף מיד כשעם ישראל נכנסים לארץ, אפילו לפני שסיימו לכבוש וליישב אותה.","spans":[{"text":"רש\"י","bold":true},{"text":" מביא ספרי, שמלמד שלגבי שאר המצוות התלויות בארץ, התורה משתמשת בלשון \"כי תבוא\" או \"כי תבואו\", שמלמדת שהמצווה מתחילה רק אחרי כיבוש וישוב הארץ, תהליך שלמעשה ארך 14 שנה מאז שעם ישראל חצו את הירדן. לעומת זאת, לגבי חלה, התורה משתמשת בלשון \"בבואכם\", ומשמע שהמצווה נכנסת לתוקף מיד כשעם ישראל נכנסים לארץ, אפילו לפני שסיימו לכבוש וליישב אותה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"a5a4c67d1d2b31676c46ef95fdf205b3e38b805421d5f823c1a8cf15b90df911"},{"chunk_code":"HC1-A4","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"א","chunk_title":"מחלוקת הגמרא בכתובות: חיוב חלה בזמן הזה","chunk_summary":"מחלוקת בגמרא אם חיוב חלה בזמן הזה מן התורה או מדרבנן; הרמב״ם פוסק שכיום החיוב בארץ ישראל מדרבנן, ובחוץ לארץ תיקנו חכמים הפרשת חלה כדי שלא תשתכח.","content_markdown":"ה**גמרא כתובות** (כה, א) (2) מביאה מחלוקת האם מצות הפרשת חלה בימינו היא דאורייתא או דרבנן. תלמידי רב סברו שאפילו אלו שסוברים שתרומה בימינו היא רק דרבנן מודים שמצות חלה היא דאורייתא, משום שכפי שהתבאר היא חלה ברגע שעם ישראל נכנסו לארץ ישראל ואיננה תלויה בכיבוש הארץ. רב הונא חולק וסובר שאפילו לפי אלו שסוברים שתרומה בזמן הזה היא דאורייתא, מצות הפרשת חלה היא רק מדרבנן. הואיל והתורה כתבה \"בבואכם\" – משמע ש**כולם** צריכים לבוא ולהיכנס לארץ, ולכן כאשר רוב היהודים כבר לא גרים בארץ מצות חלה היא דרבנן. זה היה נכון כבר בזמן עזרא, שלמרות חזרת היהודים באותה תקופה לארץ, **רוב** היהודים נשארו מאחור (ראה רש\"י).\n\nה**רמב\"ם** (ספר המצוות קלג) מונה את מצות הפרשת חלה כמצוה ה-133 במנין המצוות שלו. ב**הלכות ביכורים** (פ\"ה, ה) (3), הרמב\"ם פסק כמו רב הונא שחיוב התורה להפריש חלה בארץ ישראל חל רק כאשר **כל****[3]** עם ישראל חיים שם. הוא מביא את דברי רב הונא מהגמרא הנ\"ל שאפילו בזמן עזרא מצות הפרשת חלה הייתה רק מדרבנן מפני שרוב היהודים נשארו בבבל. בהלכה ז' הרמב\"ם מוסיף שחז\"ל תיקנו את מצות הפרשת חלה בחוץ לארץ כדי לוודא שמצוות הפרשת חלה לא תישכח.[4]\n\nSource Notes\n\n[3]:  להלן נדון אם הכוונה לכל היהודים ממש או לרוב היהודים.\n\n[4]:  מדוע חז\"ל לא תיקנו מצוה מדרבנן דומה לגבי תרומה מפירות וירקות בחו\"ל כדי שהמצווה לא תישכח? הרמב\"ן (הוספות בסוף יבמות) ביאר שתרומה שייכת רק בחקלאים, ולכן אין חשש שהיא תישכח, אבל הואיל וכולם מכינים לחם בבית, אם לא הייתה מצוה של הפרשת חלה, היה חשש שהיא תישכח. היראים (קמח) ביאר שהואיל וקמח מחו\"ל שהובא לארץ ונעשה שם לבצק חייב בחלה, חז\"ל חייבו להפריש חלה מכל בצק שהוא.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":7,"xmlIndex":8,"text":"הגמרא כתובות (כה, א) (2) מביאה מחלוקת האם מצות הפרשת חלה בימינו היא דאורייתא או דרבנן. תלמידי רב סברו שאפילו אלו שסוברים שתרומה בימינו היא רק דרבנן מודים שמצות חלה היא דאורייתא, משום שכפי שהתבאר היא חלה ברגע שעם ישראל נכנסו לארץ ישראל ואיננה תלויה בכיבוש הארץ. רב הונא חולק וסובר שאפילו לפי אלו שסוברים שתרומה בזמן הזה היא דאורייתא, מצות הפרשת חלה היא רק מדרבנן. הואיל והתורה כתבה \"בבואכם\" – משמע שכולם צריכים לבוא ולהיכנס לארץ, ולכן כאשר רוב היהודים כבר לא גרים בארץ מצות חלה היא דרבנן. זה היה נכון כבר בזמן עזרא, שלמרות חזרת היהודים באותה תקופה לארץ, רוב היהודים נשארו מאחור (ראה רש\"י).","spans":[{"text":"ה"},{"text":"גמרא כתובות","bold":true},{"text":" (כה, א) (2) מביאה מחלוקת האם מצות הפרשת חלה בימינו היא דאורייתא או דרבנן. תלמידי רב סברו שאפילו אלו שסוברים שתרומה בימינו היא רק דרבנן מודים שמצות חלה היא דאורייתא, משום שכפי שהתבאר היא חלה ברגע שעם ישראל נכנסו לארץ ישראל ואיננה תלויה בכיבוש הארץ. רב הונא חולק וסובר שאפילו לפי אלו שסוברים שתרומה בזמן הזה היא דאורייתא, מצות הפרשת חלה היא רק מדרבנן. הואיל והתורה כתבה \"בבואכם\" – משמע ש"},{"text":"כולם ","bold":true},{"text":"צריכים לבוא ולהיכנס לארץ, ולכן כאשר רוב היהודים כבר לא גרים בארץ מצות חלה היא דרבנן. זה היה נכון כבר בזמן עזרא, שלמרות חזרת היהודים באותה תקופה לארץ, "},{"text":"רוב","bold":true},{"text":" היהודים נשארו מאחור (ראה רש\"י)."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":8,"xmlIndex":9,"text":"הרמב\"ם (ספר המצוות קלג) מונה את מצות הפרשת חלה כמצוה ה-133 במנין המצוות שלו. בהלכות ביכורים (פ\"ה, ה) (3), הרמב\"ם פסק כמו רב הונא שחיוב התורה להפריש חלה בארץ ישראל חל רק כאשר כל[3] עם ישראל חיים שם. הוא מביא את דברי רב הונא מהגמרא הנ\"ל שאפילו בזמן עזרא מצות הפרשת חלה הייתה רק מדרבנן מפני שרוב היהודים נשארו בבבל. בהלכה ז' הרמב\"ם מוסיף שחז\"ל תיקנו את מצות הפרשת חלה בחוץ לארץ כדי לוודא שמצוות הפרשת חלה לא תישכח.[4]","spans":[{"text":"ה"},{"text":"רמב\"ם","bold":true},{"text":" (ספר המצוות קלג) מונה את מצות הפרשת חלה כמצוה ה-133 במנין המצוות שלו. ב"},{"text":"הלכות ביכורים","bold":true},{"text":" (פ\"ה, ה) (3), הרמב\"ם פסק כמו רב הונא שחיוב התורה להפריש חלה בארץ ישראל חל רק כאשר "},{"text":"כל","bold":true},{"text":"[3]","bold":true,"footnote":3},{"text":" עם ישראל חיים שם. הוא מביא את דברי רב הונא מהגמרא הנ\"ל שאפילו בזמן עזרא מצות הפרשת חלה הייתה רק מדרבנן מפני שרוב היהודים נשארו בבבל. בהלכה ז' הרמב\"ם מוסיף שחז\"ל תיקנו את מצות הפרשת חלה בחוץ לארץ כדי לוודא שמצוות הפרשת חלה לא תישכח."},{"text":"[4]","footnote":4}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[3,4],"defaultTabWidth":36}],"footnotes":[{"id":3,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" להלן נדון אם הכוונה לכל היהודים ממש או לרוב היהודים.","spans":[{"text":" להלן נדון אם הכוונה לכל היהודים ממש או לרוב היהודים."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":4,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" מדוע חז\"ל לא תיקנו מצוה מדרבנן דומה לגבי תרומה מפירות וירקות בחו\"ל כדי שהמצווה לא תישכח? הרמב\"ן (הוספות בסוף יבמות) ביאר שתרומה שייכת רק בחקלאים, ולכן אין חשש שהיא תישכח, אבל הואיל וכולם מכינים לחם בבית, אם לא הייתה מצוה של הפרשת חלה, היה חשש שהיא תישכח. היראים (קמח) ביאר שהואיל וקמח מחו\"ל שהובא לארץ ונעשה שם לבצק חייב בחלה, חז\"ל חייבו להפריש חלה מכל בצק שהוא.","spans":[{"text":" מדוע חז\"ל לא תיקנו מצוה מדרבנן דומה לגבי תרומה מפירות וירקות בחו\"ל כדי שהמצווה לא תישכח? הרמב\"ן (הוספות בסוף יבמות) ביאר שתרומה שייכת רק בחקלאים, ולכן אין חשש שהיא תישכח, אבל הואיל וכולם מכינים לחם בבית, אם לא הייתה מצוה של הפרשת חלה, היה חשש שהיא תישכח. היראים (קמח) ביאר שהואיל וקמח מחו\"ל שהובא לארץ ונעשה שם לבצק חייב בחלה, חז\"ל חייבו להפריש חלה מכל בצק שהוא."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[2,3],"approved_hash":"8e3db39c8d077a0e83e3989de9e3dc53030de8eb5376c056a9640df721260e55"},{"chunk_code":"HC1-B1","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ב","chunk_title":"נתוני האוכלוסייה והשאלה ההלכתית בימינו","chunk_summary":"דיון באפשרות שרוב יהודי העולם כבר מתגוררים בארץ ישראל, ובשאלה אם הדבר משנה את מעמדן של מצוות חלה, שמיטה ותרומה.","content_markdown":"### ב. *מעמד הפרשת חלה בימינו*\n\nעל פי מה שלמדנו בחלק הקודם, השאלה הבאה שעלינו לשאול היא מה המעמד ההלכתי בימינו של הפרשת חלה בארץ ישראל? כפי שהוזכר לעיל, מרש\"י בכתובות (2) משמע שכאשר רוב היהודים גרים בארץ ישראל, מצות הפרשת חלה היא דאורייתא, ולנקודה זו יש גם נפק\"מ למעשה, כגון שבמקרים של ספק נצטרך להכריע לחומרא. נכון לשנת 2026 מתגוררים בארץ 7.3 מיליון יהודים בקירוב, ובערך 8.5 מיליון יהודים גרים מחוץ לארץ ישראל.[5] מתוך 8.5 מיליון היהודים שגרים בחו\"ל, 37% בארה\"ב הם רפורמים, שרבים מהם התגיירו או נולדו לאמא שהתגיירה בגיור רפורמי, ועל פי דין תורה הם נחשבים כגויים. לכן, יתכן שאפילו בימינו רוב היהודים של העולם כבר גרים בארץ ישראל. אפילו אם נתונים אלו אינם מדויקים, מסתבר שבשנים הקרובות רוב היהודים יתגוררו בארץ ישראל לראשונה מאז תקופת בית המקדש הראשון.\n\nועוד, אם נניח שרוב היהודים בימינו מתגוררים בארץ ישראל (או אם זה יקרה בשנים הקרובות), עלינו לבחון האם מלבד לגבי הפרשת חלה יש לזה השפעה על דיני שמיטה ותרו\"מ. אחת הקולות הגדולות שהרבנות בישראל סומכת עליה בשמיטה כדי להתיר עבודה באדמה היא \"היתר מכירה\" – מכירת הקרקע לגוי. בעז\"ה, ב'זמן' עתידי של 'סמיכת חבר' נלמד את פרטי הקולא והאם ניתן לסמוך עליה, אבל אלו שסומכים על הקולא במידה מסוימת עושים כן משום ששמיטה בזמן הזה היא דרבנן. אולם, אם בשנת השמיטה הבאה רוב יהודי העולם יגורו בארץ ישראל, האם עובדה זו תערער את התוקף של היתר המכירה?\n\nנתחיל בדיון האם מצות שמיטה נעשית דאורייתא במקרה שרוב היהודים גרים בארץ ישראל. לאחר מכן נבחן את המעמד של חלה ותרומה בימינו.\n\nSource Notes\n\n[5]:  על פי הלשכה המרכזית לסטטיסטיקה של ישראל (הלמ\"ס). לכן, 46% מיהודים גרים בארץ.","content_document":{"version":1,"language":"he","blocks":[{"kind":"heading","paragraph":9,"xmlIndex":10,"text":"מעמד הפרשת חלה בימינו","spans":[{"text":"מעמד הפרשת חלה בימינו","italic":true,"color":"#2F5496"}],"marker":"ב.","level":0,"indent":56,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"rightIndent":43.2,"hanging":18,"tabStops":[{"position":150.45,"alignment":"left","leader":"none"},{"position":234,"alignment":"center","leader":"none"},{"position":279,"alignment":"left","leader":"none"}]},{"kind":"paragraph","paragraph":10,"xmlIndex":12,"text":"על פי מה שלמדנו בחלק הקודם, השאלה הבאה שעלינו לשאול היא מה המעמד ההלכתי בימינו של הפרשת חלה בארץ ישראל? כפי שהוזכר לעיל, מרש\"י בכתובות (2) משמע שכאשר רוב היהודים גרים בארץ ישראל, מצות הפרשת חלה היא דאורייתא, ולנקודה זו יש גם נפק\"מ למעשה, כגון שבמקרים של ספק נצטרך להכריע לחומרא. נכון לשנת 2026 מתגוררים בארץ 7.3 מיליון יהודים בקירוב, ובערך 8.5 מיליון יהודים גרים מחוץ לארץ ישראל.[5] מתוך 8.5 מיליון היהודים שגרים בחו\"ל, 37% בארה\"ב הם רפורמים, שרבים מהם התגיירו או נולדו לאמא שהתגיירה בגיור רפורמי, ועל פי דין תורה הם נחשבים כגויים. לכן, יתכן שאפילו בימינו רוב היהודים של העולם כבר גרים בארץ ישראל. אפילו אם נתונים אלו אינם מדויקים, מסתבר שבשנים הקרובות רוב היהודים יתגוררו בארץ ישראל לראשונה מאז תקופת בית המקדש הראשון.","spans":[{"text":"על פי מה שלמדנו בחלק הקודם, השאלה הבאה שעלינו לשאול היא מה המעמד ההלכתי בימינו של הפרשת חלה בארץ ישראל? כפי שהוזכר לעיל, מרש\"י בכתובות (2) משמע שכאשר רוב היהודים גרים בארץ ישראל, מצות הפרשת חלה היא דאורייתא, ולנקודה זו יש גם נפק\"מ למעשה, כגון שבמקרים של ספק נצטרך להכריע לחומרא. נכון לשנת 2026 מתגוררים בארץ 7.3 מיליון יהודים בקירוב, ובערך 8.5 מיליון יהודים גרים מחוץ לארץ ישראל."},{"text":"[5]","footnote":5},{"text":" מתוך 8.5 מיליון היהודים שגרים בחו\"ל, 37% בארה\"ב הם רפורמים, שרבים מהם התגיירו או נולדו לאמא שהתגיירה בגיור רפורמי, ועל פי דין תורה הם נחשבים כגויים. לכן, יתכן שאפילו בימינו רוב היהודים של העולם כבר גרים בארץ ישראל. אפילו אם נתונים אלו אינם מדויקים, מסתבר שבשנים הקרובות רוב היהודים יתגוררו בארץ ישראל לראשונה מאז תקופת בית המקדש הראשון."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[5],"defaultTabWidth":36},{"kind":"paragraph","paragraph":11,"xmlIndex":13,"text":"ועוד, אם נניח שרוב היהודים בימינו מתגוררים בארץ ישראל (או אם זה יקרה בשנים הקרובות), עלינו לבחון האם מלבד לגבי הפרשת חלה יש לזה השפעה על דיני שמיטה ותרו\"מ. אחת הקולות הגדולות שהרבנות בישראל סומכת עליה בשמיטה כדי להתיר עבודה באדמה היא \"היתר מכירה\" – מכירת הקרקע לגוי. בעז\"ה, ב'זמן' עתידי של 'סמיכת חבר' נלמד את פרטי הקולא והאם ניתן לסמוך עליה, אבל אלו שסומכים על הקולא במידה מסוימת עושים כן משום ששמיטה בזמן הזה היא דרבנן. אולם, אם בשנת השמיטה הבאה רוב יהודי העולם יגורו בארץ ישראל, האם עובדה זו תערער את התוקף של היתר המכירה?","spans":[{"text":"ועוד, אם נניח שרוב היהודים בימינו מתגוררים בארץ ישראל (או אם זה יקרה בשנים הקרובות), עלינו לבחון האם מלבד לגבי הפרשת חלה יש לזה השפעה על דיני שמיטה ותרו\"מ. אחת הקולות הגדולות שהרבנות בישראל סומכת עליה בשמיטה כדי להתיר עבודה באדמה היא \"היתר מכירה\" – מכירת הקרקע לגוי. בעז\"ה, ב'זמן' עתידי של 'סמיכת חבר' נלמד את פרטי הקולא והאם ניתן לסמוך עליה, אבל אלו שסומכים על הקולא במידה מסוימת עושים כן משום ששמיטה בזמן הזה היא דרבנן. אולם, אם בשנת השמיטה הבאה רוב יהודי העולם יגורו בארץ ישראל, האם עובדה זו תערער את התוקף של היתר המכירה?"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":12,"xmlIndex":14,"text":"נתחיל בדיון האם מצות שמיטה נעשית דאורייתא במקרה שרוב היהודים גרים בארץ ישראל. לאחר מכן נבחן את המעמד של חלה ותרומה בימינו.","spans":[{"text":"נתחיל בדיון האם מצות שמיטה נעשית דאורייתא במקרה שרוב היהודים גרים בארץ ישראל. לאחר מכן נבחן את המעמד של חלה ותרומה בימינו."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":5,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" על פי הלשכה המרכזית לסטטיסטיקה של ישראל (הלמ\"ס). לכן, 46% מיהודים גרים בארץ.","spans":[{"text":" על פי הלשכה המרכזית לסטטיסטיקה של ישראל (הלמ\"ס). לכן, 46% מיהודים גרים בארץ."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[2],"approved_hash":"2fb20252dd31a2f9fd534f0a47d808f563176cfddb38c21708aa4638742d8901"},{"chunk_code":"HC1-B2","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ב","chunk_title":"שמיטה בזמן הזה והקשר ליובל","chunk_summary":"לדעת הרמב״ם, שמיטה מן התורה תלויה בחיוב יובל, המחייב את ישיבת השבטים בנחלותיהם; לפיכך החיוב כיום מדרבנן, לפי שיטתו, עד לביאת המשיח.","content_markdown":"<u>1. שמיטה בימינו</u>\n\nלגבי שמיטה, ה**רמב\"ם** (הלכות שמיטה ויובל פ\"י, ח) (4) פסק ששמיטה היא דאורייתא רק כאשר חלה מצות יובל (השנה ה-50, בה בתים ואחוזות שנמכרו חוזרים לבעלים המקוריים ועבדים עבריים משתחררים). אולם, יובל שייך רק כאשר כל (או לכל הפחות רוב) עם ישראל יושבים בנחלת אבותיהם לפי השבט שלהם. בימינו, כשרוב היהודים לא יודעים לאיזה שבט הם שייכים ובוודאי לא יושבים בחלקת הקרקע שמיועדת להם, אין את מצות יובל. כתוצאה מכך שמיטה נשארת רק כמצווה דרבנן. לכן, אפילו אם כל היהודים יחזרו לגור בארץ ישראל, שמיטה עדיין תישאר כמצווה דרבנן עד שיבוא המשיח, שיזהה את השבט של כל אחד ויחזיר כל שבט לחלק המיועד לו.[6]\n\nSource Notes\n\n[6]:  אולם, ציץ אליעזר (ח\"י א, כ) פסק כמו הראשונים שחולקים על הרמב\"ם וסוברים שחלוקת ארץ ישראל לשבטים נצרכת רק כדי להחזיר את מצות יובל. אולם, לגבי שמיטה, ברגע שרוב ישראל חיים בארץ ישראל, מצות שמיטה נעשית דאורייתא.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":13,"xmlIndex":15,"text":"1. שמיטה בימינו","spans":[{"text":"1. שמיטה בימינו","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":14,"xmlIndex":16,"text":"לגבי שמיטה, הרמב\"ם (הלכות שמיטה ויובל פ\"י, ח) (4) פסק ששמיטה היא דאורייתא רק כאשר חלה מצות יובל (השנה ה-50, בה בתים ואחוזות שנמכרו חוזרים לבעלים המקוריים ועבדים עבריים משתחררים). אולם, יובל שייך רק כאשר כל (או לכל הפחות רוב) עם ישראל יושבים בנחלת אבותיהם לפי השבט שלהם. בימינו, כשרוב היהודים לא יודעים לאיזה שבט הם שייכים ובוודאי לא יושבים בחלקת הקרקע שמיועדת להם, אין את מצות יובל. כתוצאה מכך שמיטה נשארת רק כמצווה דרבנן. לכן, אפילו אם כל היהודים יחזרו לגור בארץ ישראל, שמיטה עדיין תישאר כמצווה דרבנן עד שיבוא המשיח, שיזהה את השבט של כל אחד ויחזיר כל שבט לחלק המיועד לו.[6]","spans":[{"text":"לגבי שמיטה, ה"},{"text":"רמב\"ם","bold":true},{"text":" (הלכות שמיטה ויובל פ\"י, ח) (4) פסק ששמיטה היא דאורייתא רק כאשר חלה מצות יובל (השנה ה-50, בה בתים ואחוזות שנמכרו חוזרים לבעלים המקוריים ועבדים עבריים משתחררים). אולם, יובל שייך רק כאשר כל (או לכל הפחות רוב) עם ישראל יושבים בנחלת אבותיהם לפי השבט שלהם. בימינו, כשרוב היהודים לא יודעים לאיזה שבט הם שייכים ובוודאי לא יושבים בחלקת הקרקע שמיועדת להם, אין את מצות יובל. כתוצאה מכך שמיטה נשארת רק כמצווה דרבנן. לכן, אפילו אם כל היהודים יחזרו לגור בארץ ישראל, שמיטה עדיין תישאר כמצווה דרבנן עד שיבוא המשיח, שיזהה את השבט של כל אחד ויחזיר כל שבט לחלק המיועד לו."},{"text":"[6]","footnote":6}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[6],"defaultTabWidth":36}],"footnotes":[{"id":6,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" אולם, ציץ אליעזר (ח\"י א, כ) פסק כמו הראשונים שחולקים על הרמב\"ם וסוברים שחלוקת ארץ ישראל לשבטים נצרכת רק כדי להחזיר את מצות יובל. אולם, לגבי שמיטה, ברגע שרוב ישראל חיים בארץ ישראל, מצות שמיטה נעשית דאורייתא.","spans":[{"text":" אולם, ציץ אליעזר (ח\"י א, כ) פסק כמו הראשונים שחולקים על הרמב\"ם וסוברים שחלוקת ארץ ישראל לשבטים נצרכת רק כדי להחזיר את מצות יובל. אולם, לגבי שמיטה, ברגע שרוב ישראל חיים בארץ ישראל, מצות שמיטה נעשית דאורייתא."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[4],"approved_hash":"056f12438527d9279698c046779e00ef91ce96bd55ab3ac50947be4fab19660e"},{"chunk_code":"HC1-B3","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ב","chunk_title":"חלה בזמן הזה — רוב ישראל בארץ","chunk_summary":"הריטב״א והבאר בשדה סוברים שדי ברוב ישראל בארץ לחיוב חלה מן התורה; החזון איש מעלה אפשרות שדרושה גם כניסה לארץ בהכוונת מלך או נביא.","content_markdown":"<u>2. חלה בימינו</u>\n\nלגבי חלה, יש מחלוקת האם המצווה נעשית דאורייתא כאשר רוב עם ישראל חוזרים לארץ ישראל. בניגוד לשמיטה, חלה איננה קשורה ליובל. אלא, היא נכנסה לתוקף מיד אחרי שעם ישראל נכנסו לארץ ישראל, אפילו לפני שכבשו וחילקו את הארץ. לכן נראה, שברגע שרוב היהודים נכנסים לארץ, אפילו אם הארץ עדיין לא נכבשה רשמית, המצווה תחזור להיות דאורייתא. למעשה, ה**ריטב\"א** (כתובות כה, א ד\"ה בבואכם) (5) פסק שברגע שרוב היהודים גרים בארץ ישראל, מצות חלה בארץ ישראל נעשית שוב מצוה דאורייתא.\n\nועוד, למרות שהרמב\"ם ושו\"ע כתבו ש\"**כל**\" היהודים צריכים לחזור לארץ כדי שהמצווה תחזור להיות דאורייתא, ה**באר בשדה** (פ\"א הע' ג) (6) סובר שגם הרמב\"ם יסכים שמספיק רוב היהודים. הוא מבאר שכאשר עם ישראל כבשו בתחילה את הארץ בזמן יהושע, לא כל היהודים נכנסו לארץ, שכן השבטים גד, ראובן וחצי שבט מנשה נשארו מעבר לירדן. אכן, הגברים נכנסו לארץ כדי להילחם, אבל זה היה רק הגברים בגילאים 20-60 שיכולים להילחם, ואפילו בקבוצת גיל זו חלק נשארו מאחור להגן על הנשים והילדים שלא נכנסו. אם כן, אפילו כאשר מצות חלה נכנסה לתוקף לראשונה, רק רוב היהודים היו בארץ ישראל, וכולם מודים שבאותו זמן המצווה הייתה דאורייתא, ואם כן גם בימינו, המצווה תהיה דאורייתא ברגע שרוב היהודים יגורו ארץ ישראל.\n\nאולם, ה**חזון איש** (שביעית כא, ה) (7) חולק וסובר שאפילו אם רוב היהודים באים לארץ ישראל, מצות חלה תישאר דרבנן, מפני שהחיוב מדאורייתא חל רק כאשר מתקיימים 2 תנאים: 1) עם ישראל נכנסים לארץ ישראל תחת הנהגת מלך או נביא, בדומה לכניסה לארץ עם יהושע. **חלת לחם**[7] (ס\"א שירי ברכה, ה) מציע שהואיל ובציווי התורה לגבי חלה נאמר \"אשר **אני** מביא אתכם שמה\", משמע שהמצווה מן התורה חלה רק כאשר עם ישראל נכנסים לארץ בהכוונה ישירה של ה' (דהיינו, באמצעות נביא או מלך). 2) רוב עם ישראל מתגוררים בארץ. בימינו, מתקיים רק התנאי השני, ולכן המצווה נשארת מדרבנן. החזון איש דן באפשרות שהמצווה נעשית דאורייתא אפילו בלי מלך או נביא, אבל לבסוף דוחה צד זה.\n\nלסיכום, מהריטב\"א ובאר בשדה נראה שמצוות הפרשת חלה נעשית דאורייתא משעה שרוב עם ישראל יושבים בארץ ישראל (מציאות שיתכן וכבר קיימת כיום). אולם החזון איש טוען שהמצווה נשארת דרבנן עד שניכנס לארץ בהכוונת מלך או נביא.\n\nSource Notes\n\n[7]:  נכתב על ידי הרב שמחה יואל רובינשטיין (נפטר בשנת 1863), היה רב ודיין בעיר בוברקה, אוקראינה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":15,"xmlIndex":17,"text":"2. חלה בימינו","spans":[{"text":"2. חלה בימינו","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":16,"xmlIndex":18,"text":"לגבי חלה, יש מחלוקת האם המצווה נעשית דאורייתא כאשר רוב עם ישראל חוזרים לארץ ישראל. בניגוד לשמיטה, חלה איננה קשורה ליובל. אלא, היא נכנסה לתוקף מיד אחרי שעם ישראל נכנסו לארץ ישראל, אפילו לפני שכבשו וחילקו את הארץ. לכן נראה, שברגע שרוב היהודים נכנסים לארץ, אפילו אם הארץ עדיין לא נכבשה רשמית, המצווה תחזור להיות דאורייתא. למעשה, הריטב\"א (כתובות כה, א ד\"ה בבואכם) (5) פסק שברגע שרוב היהודים גרים בארץ ישראל, מצות חלה בארץ ישראל נעשית שוב מצוה דאורייתא.","spans":[{"text":"לגבי חלה, יש מחלוקת האם המצווה נעשית דאורייתא כאשר רוב עם ישראל חוזרים לארץ ישראל. בניגוד לשמיטה, חלה איננה קשורה ליובל. אלא, היא נכנסה לתוקף מיד אחרי שעם ישראל נכנסו לארץ ישראל, אפילו לפני שכבשו וחילקו את הארץ. לכן נראה, שברגע שרוב היהודים נכנסים לארץ, אפילו אם הארץ עדיין לא נכבשה רשמית, המצווה תחזור להיות דאורייתא. למעשה, ה"},{"text":"ריטב\"א","bold":true},{"text":" (כתובות כה, א ד\"ה בבואכם) (5) פסק שברגע שרוב היהודים גרים בארץ ישראל, מצות חלה בארץ ישראל נעשית שוב מצוה דאורייתא."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":17,"xmlIndex":19,"text":"ועוד, למרות שהרמב\"ם ושו\"ע כתבו ש\"כל\" היהודים צריכים לחזור לארץ כדי שהמצווה תחזור להיות דאורייתא, הבאר בשדה (פ\"א הע' ג) (6) סובר שגם הרמב\"ם יסכים שמספיק רוב היהודים. הוא מבאר שכאשר עם ישראל כבשו בתחילה את הארץ בזמן יהושע, לא כל היהודים נכנסו לארץ, שכן השבטים גד, ראובן וחצי שבט מנשה נשארו מעבר לירדן. אכן, הגברים נכנסו לארץ כדי להילחם, אבל זה היה רק הגברים בגילאים 20-60 שיכולים להילחם, ואפילו בקבוצת גיל זו חלק נשארו מאחור להגן על הנשים והילדים שלא נכנסו. אם כן, אפילו כאשר מצות חלה נכנסה לתוקף לראשונה, רק רוב היהודים היו בארץ ישראל, וכולם מודים שבאותו זמן המצווה הייתה דאורייתא, ואם כן גם בימינו, המצווה תהיה דאורייתא ברגע שרוב היהודים יגורו ארץ ישראל.","spans":[{"text":"ועוד, למרות שהרמב\"ם ושו\"ע כתבו ש\""},{"text":"כל","bold":true},{"text":"\" היהודים צריכים לחזור לארץ כדי שהמצווה תחזור להיות דאורייתא, ה"},{"text":"באר בשדה","bold":true},{"text":" (פ\"א הע' ג) (6) סובר שגם הרמב\"ם יסכים שמספיק רוב היהודים. הוא מבאר שכאשר עם ישראל כבשו בתחילה את הארץ בזמן יהושע, לא כל היהודים נכנסו לארץ, שכן השבטים גד, ראובן וחצי שבט מנשה נשארו מעבר לירדן. אכן, הגברים נכנסו לארץ כדי להילחם, אבל זה היה רק הגברים בגילאים 20-60 שיכולים להילחם, ואפילו בקבוצת גיל זו חלק נשארו מאחור להגן על הנשים והילדים שלא נכנסו. אם כן, אפילו כאשר מצות חלה נכנסה לתוקף לראשונה, רק רוב היהודים היו בארץ ישראל, וכולם מודים שבאותו זמן המצווה הייתה דאורייתא, ואם כן גם בימינו, המצווה תהיה דאורייתא ברגע שרוב היהודים יגורו ארץ ישראל."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":18,"xmlIndex":20,"text":"אולם, החזון איש (שביעית כא, ה) (7) חולק וסובר שאפילו אם רוב היהודים באים לארץ ישראל, מצות חלה תישאר דרבנן, מפני שהחיוב מדאורייתא חל רק כאשר מתקיימים 2 תנאים: 1) עם ישראל נכנסים לארץ ישראל תחת הנהגת מלך או נביא, בדומה לכניסה לארץ עם יהושע. חלת לחם[7] (ס\"א שירי ברכה, ה) מציע שהואיל ובציווי התורה לגבי חלה נאמר \"אשר אני מביא אתכם שמה\", משמע שהמצווה מן התורה חלה רק כאשר עם ישראל נכנסים לארץ בהכוונה ישירה של ה' (דהיינו, באמצעות נביא או מלך). 2) רוב עם ישראל מתגוררים בארץ. בימינו, מתקיים רק התנאי השני, ולכן המצווה נשארת מדרבנן. החזון איש דן באפשרות שהמצווה נעשית דאורייתא אפילו בלי מלך או נביא, אבל לבסוף דוחה צד זה.","spans":[{"text":"אולם, ה"},{"text":"חזון איש","bold":true},{"text":" (שביעית כא, ה) (7) חולק וסובר שאפילו אם רוב היהודים באים לארץ ישראל, מצות חלה תישאר דרבנן, מפני שהחיוב מדאורייתא חל רק כאשר מתקיימים 2 תנאים: 1) עם ישראל נכנסים לארץ ישראל תחת הנהגת מלך או נביא, בדומה לכניסה לארץ עם יהושע. "},{"text":"חלת לחם","bold":true},{"text":"[7]","footnote":7},{"text":" (ס\"א שירי ברכה, ה) מציע שהואיל ובציווי התורה לגבי חלה נאמר \"אשר "},{"text":"אני","bold":true},{"text":" מביא אתכם שמה\", משמע שהמצווה מן התורה חלה רק כאשר עם ישראל נכנסים לארץ בהכוונה ישירה של ה' (דהיינו, באמצעות נביא או מלך). 2) רוב עם ישראל מתגוררים בארץ. בימינו, מתקיים רק התנאי השני, ולכן המצווה נשארת מדרבנן. החזון איש דן באפשרות שהמצווה נעשית דאורייתא אפילו בלי מלך או נביא, אבל לבסוף דוחה צד זה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[7],"defaultTabWidth":36},{"kind":"paragraph","paragraph":19,"xmlIndex":21,"text":"לסיכום, מהריטב\"א ובאר בשדה נראה שמצוות הפרשת חלה נעשית דאורייתא משעה שרוב עם ישראל יושבים בארץ ישראל (מציאות שיתכן וכבר קיימת כיום). אולם החזון איש טוען שהמצווה נשארת דרבנן עד שניכנס לארץ בהכוונת מלך או נביא.","spans":[{"text":"לסיכום, מהריטב\"א ובאר בשדה נראה שמצוות הפרשת חלה נעשית דאורייתא משעה שרוב עם ישראל יושבים בארץ ישראל (מציאות שיתכן וכבר קיימת כיום). אולם החזון איש טוען שהמצווה נשארת דרבנן עד שניכנס לארץ בהכוונת מלך או נביא."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":7,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" נכתב על ידי הרב שמחה יואל רובינשטיין (נפטר בשנת 1863), היה רב ודיין בעיר בוברקה, אוקראינה.","spans":[{"text":" נכתב על ידי הרב שמחה יואל רובינשטיין (נפטר בשנת 1863), היה רב ודיין בעיר בוברקה, אוקראינה."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[5,6,7],"approved_hash":"42fb6428154e64b48589a7711f8f52ec3e6b03c4982a801aff3df2fa54aec884"},{"chunk_code":"HC1-B4","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ב","chunk_title":"מעמד תרומה בזמן הזה","chunk_summary":"מחלוקת הרמב״ם והראב״ד לגבי חיוב תרומה בזמן הזה; החזון איש מבחין בין תרומה לחלה, ור׳ חיים קנייבסקי דן בהשלכת עשרת השבטים האבודים.","content_markdown":"<u>3. תרומה בימינו</u>\n\nלגבי תרומה, ה**רמב\"ם** (תרומות פ\"א, כו) (8) משווה את המעמד שלה למעמד של חלה, כך שהפרשת תרומה תהיה דאורייתא רק כאשר רוב עם ישראל יתגוררו בארץ ישראל. ה**ראב\"ד** חולק, וסובר שתרומה אינה דומה לחלה והמצווה בימינו היא מן התורה למרות שרוב עם ישראל לא גרים בארץ ישראל. השו\"ע ב**סימן שלא, ב** פסק כמו הרמב\"ם. למרות שהרמ\"א הביא את הראב\"ד, הוא מסכים למעשה לפסק השו\"ע שבימינו תרומה היא רק מדרבנן. על פי מה שלמדנו לגבי חלה ניתן היה לשער שלפי הריטב\"א ובאר בשדה גם מצוות תרומה תיעשה דאורייתא משעה שרוב עם ישראל יושבים בארץ, ואילו החזון איש יחלוק ויסבור שזה יישאר דרבנן. אולם, למעשה, ה**חזון איש** (שביעית כא, ה) (9) מחלק בין חלה לתרומה, ומציע שהרמב\"ם יודה שאם רוב עם ישראל חזרו לארץ ישראל, מצוות תרומה נעשית דאורייתא.\n\nהחזון איש מסביר שלמרות שיתכן ולגבי חלה צריך את התנאי שהעם ייכנסו לארץ ישראל בהכוונת מלך או נביא, לגבי תרומה אין את התנאי הזה. אמנם, עדיין צריך שיתקיימו 2 תנאים כדי שהתרומה תיעשה דאורייתא: 1) הארץ קדושה, 2) רוב עם ישראל יושבים בארץ ישראל. כשעזרא חזר לארץ לפני בניין בית המקדש השני, הוא קידש את הארץ פעם שניה, כך שהתנאי הראשון כבר התקיים.[8] הלכך, ברגע שרוב היהודים גרים בארץ ישראל, תרומה נעשית מצוה דאורייתא, אפילו אם המשיח עדיין לא הגיע.\n\nנמצא שמשעה שרוב עם ישראל נמצא בארץ ישראל, אבן דרך שיתכן וכבר הגענו אליה או שאנחנו קרובים אליה מאוד בעתיד הקרוב, כולם יודו שמצוות תרומה תהיה דאורייתא. זה יגביר משמעותית את חומר המצווה ואת החשיבות לוודא שההפרשה נעשתה כראוי. לפיכך, כאשר קונים פירות וירקות בארץ ישראל, יש לוודא שקונים ממקום עם הכשר טוב, או לדעת איך להפריש לבד תרומות ומעשרות כראוי.\n\nאף על פי כן, עדיין יתכן שתרומה תישאר דרבנן בעתיד הנראה לעין. **הרב חיים קנייבסקי** בדרך אמונה (תרומות פ\"א, כו ב\"ה ד\"ה וכן) (10) מציע שהואיל ועשרת השבטים עדיין אבודים, יתכן שרוב עם ישראל אינו יושב בארץ ישראל. ועוד אפשר להוסיף שאפילו בלי להחשיב את עשרת השבטים, קשה מאוד לקבוע בצורה מדויקת את מנין היהודים בעולם, מפני שאם יש יהודייה שאיננה שומרת תו\"מ, הילדים שלה והצאצאים הלאה מצד בנותיה נשארים יהודים, אבל לא מונים אותם כשסוקרים את האוכלוסיה. בדומה לזה, כשעושים מפקד עולמי, יש הרבה שנספרים כיהודים למרות שרק אבא שלהם יהודי, ועל פי הלכה הם גויים.\n\nSource Notes\n\n[8]:  יש מחלוקת בגמרא ביבמות (פב, ב) האם קדושה זו התבטלה בחורבן בית המקדש השני (קדושה שניה קידשה לשעתה או גם לעתיד לבוא), והרמב\"ם פסק כמו הדעה שקדושת ארץ ישראל מזמן עזרא היא קדושה נצחית.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":20,"xmlIndex":22,"text":"3. תרומה בימינו","spans":[{"text":"3. תרומה בימינו","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":21,"xmlIndex":23,"text":"לגבי תרומה, הרמב\"ם (תרומות פ\"א, כו) (8) משווה את המעמד שלה למעמד של חלה, כך שהפרשת תרומה תהיה דאורייתא רק כאשר רוב עם ישראל יתגוררו בארץ ישראל. הראב\"ד חולק, וסובר שתרומה אינה דומה לחלה והמצווה בימינו היא מן התורה למרות שרוב עם ישראל לא גרים בארץ ישראל. השו\"ע בסימן שלא, ב פסק כמו הרמב\"ם. למרות שהרמ\"א הביא את הראב\"ד, הוא מסכים למעשה לפסק השו\"ע שבימינו תרומה היא רק מדרבנן. על פי מה שלמדנו לגבי חלה ניתן היה לשער שלפי הריטב\"א ובאר בשדה גם מצוות תרומה תיעשה דאורייתא משעה שרוב עם ישראל יושבים בארץ, ואילו החזון איש יחלוק ויסבור שזה יישאר דרבנן. אולם, למעשה, החזון איש (שביעית כא, ה) (9) מחלק בין חלה לתרומה, ומציע שהרמב\"ם יודה שאם רוב עם ישראל חזרו לארץ ישראל, מצוות תרומה נעשית דאורייתא.","spans":[{"text":"לגבי תרומה, ה"},{"text":"רמב\"ם ","bold":true},{"text":"(תרומות פ\"א, כו) (8) משווה את המעמד שלה למעמד של חלה, כך שהפרשת תרומה תהיה דאורייתא רק כאשר רוב עם ישראל יתגוררו בארץ ישראל. ה"},{"text":"ראב\"ד","bold":true},{"text":" חולק, וסובר שתרומה אינה דומה לחלה והמצווה בימינו היא מן התורה למרות שרוב עם ישראל לא גרים בארץ ישראל. השו\"ע ב"},{"text":"סימן שלא, ב","bold":true},{"text":" פסק כמו הרמב\"ם. למרות שהרמ\"א הביא את הראב\"ד, הוא מסכים למעשה לפסק השו\"ע שבימינו תרומה היא רק מדרבנן. על פי מה שלמדנו לגבי חלה ניתן היה לשער שלפי הריטב\"א ובאר בשדה גם מצוות תרומה תיעשה דאורייתא משעה שרוב עם ישראל יושבים בארץ, ואילו החזון איש יחלוק ויסבור שזה יישאר דרבנן. אולם, למעשה, ה"},{"text":"חזון איש","bold":true},{"text":" (שביעית כא, ה) (9) מחלק בין חלה לתרומה, ומציע שהרמב\"ם יודה שאם רוב עם ישראל חזרו לארץ ישראל, מצוות תרומה נעשית דאורייתא."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":22,"xmlIndex":24,"text":"החזון איש מסביר שלמרות שיתכן ולגבי חלה צריך את התנאי שהעם ייכנסו לארץ ישראל בהכוונת מלך או נביא, לגבי תרומה אין את התנאי הזה. אמנם, עדיין צריך שיתקיימו 2 תנאים כדי שהתרומה תיעשה דאורייתא: 1) הארץ קדושה, 2) רוב עם ישראל יושבים בארץ ישראל. כשעזרא חזר לארץ לפני בניין בית המקדש השני, הוא קידש את הארץ פעם שניה, כך שהתנאי הראשון כבר התקיים.[8] הלכך, ברגע שרוב היהודים גרים בארץ ישראל, תרומה נעשית מצוה דאורייתא, אפילו אם המשיח עדיין לא הגיע.","spans":[{"text":"החזון איש מסביר שלמרות שיתכן ולגבי חלה צריך את התנאי שהעם ייכנסו לארץ ישראל בהכוונת מלך או נביא, לגבי תרומה אין את התנאי הזה. אמנם, עדיין צריך שיתקיימו 2 תנאים כדי שהתרומה תיעשה דאורייתא: 1) הארץ קדושה, 2) רוב עם ישראל יושבים בארץ ישראל. כשעזרא חזר לארץ לפני בניין בית המקדש השני, הוא קידש את הארץ פעם שניה, כך שהתנאי הראשון כבר התקיים."},{"text":"[8]","footnote":8},{"text":" הלכך, ברגע שרוב היהודים גרים בארץ ישראל, תרומה נעשית מצוה דאורייתא, אפילו אם המשיח עדיין לא הגיע."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[8],"defaultTabWidth":36},{"kind":"paragraph","paragraph":23,"xmlIndex":25,"text":"נמצא שמשעה שרוב עם ישראל נמצא בארץ ישראל, אבן דרך שיתכן וכבר הגענו אליה או שאנחנו קרובים אליה מאוד בעתיד הקרוב, כולם יודו שמצוות תרומה תהיה דאורייתא. זה יגביר משמעותית את חומר המצווה ואת החשיבות לוודא שההפרשה נעשתה כראוי. לפיכך, כאשר קונים פירות וירקות בארץ ישראל, יש לוודא שקונים ממקום עם הכשר טוב, או לדעת איך להפריש לבד תרומות ומעשרות כראוי.","spans":[{"text":"נמצא שמשעה שרוב עם ישראל נמצא בארץ ישראל, אבן דרך שיתכן וכבר הגענו אליה או שאנחנו קרובים אליה מאוד בעתיד הקרוב, כולם יודו שמצוות תרומה תהיה דאורייתא. זה יגביר משמעותית את חומר המצווה ואת החשיבות לוודא שההפרשה נעשתה כראוי. לפיכך, כאשר קונים פירות וירקות בארץ ישראל, יש לוודא שקונים ממקום עם הכשר טוב, או לדעת איך להפריש לבד תרומות ומעשרות כראוי."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":24,"xmlIndex":26,"text":"אף על פי כן, עדיין יתכן שתרומה תישאר דרבנן בעתיד הנראה לעין. הרב חיים קנייבסקי בדרך אמונה (תרומות פ\"א, כו ב\"ה ד\"ה וכן) (10) מציע שהואיל ועשרת השבטים עדיין אבודים, יתכן שרוב עם ישראל אינו יושב בארץ ישראל. ועוד אפשר להוסיף שאפילו בלי להחשיב את עשרת השבטים, קשה מאוד לקבוע בצורה מדויקת את מנין היהודים בעולם, מפני שאם יש יהודייה שאיננה שומרת תו\"מ, הילדים שלה והצאצאים הלאה מצד בנותיה נשארים יהודים, אבל לא מונים אותם כשסוקרים את האוכלוסיה. בדומה לזה, כשעושים מפקד עולמי, יש הרבה שנספרים כיהודים למרות שרק אבא שלהם יהודי, ועל פי הלכה הם גויים.","spans":[{"text":"אף על פי כן, עדיין יתכן שתרומה תישאר דרבנן בעתיד הנראה לעין. "},{"text":"הרב חיים קנייבסקי","bold":true},{"text":" בדרך אמונה (תרומות פ\"א, כו ב\"ה ד\"ה וכן) (10) מציע שהואיל ועשרת השבטים עדיין אבודים, יתכן שרוב עם ישראל אינו יושב בארץ ישראל. ועוד אפשר להוסיף שאפילו בלי להחשיב את עשרת השבטים, קשה מאוד לקבוע בצורה מדויקת את מנין היהודים בעולם, מפני שאם יש יהודייה שאיננה שומרת תו\"מ, הילדים שלה והצאצאים הלאה מצד בנותיה נשארים יהודים, אבל לא מונים אותם כשסוקרים את האוכלוסיה. בדומה לזה, כשעושים מפקד עולמי, יש הרבה שנספרים כיהודים למרות שרק אבא שלהם יהודי, ועל פי הלכה הם גויים."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":8,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" יש מחלוקת בגמרא ביבמות (פב, ב) האם קדושה זו התבטלה בחורבן בית המקדש השני (קדושה שניה קידשה לשעתה או גם לעתיד לבוא), והרמב\"ם פסק כמו הדעה שקדושת ארץ ישראל מזמן עזרא היא קדושה נצחית.","spans":[{"text":" יש מחלוקת בגמרא ביבמות (פב, ב) האם קדושה זו התבטלה בחורבן בית המקדש השני (קדושה שניה קידשה לשעתה או גם לעתיד לבוא), והרמב\"ם פסק כמו הדעה שקדושת ארץ ישראל מזמן עזרא היא קדושה נצחית."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[8,9,10],"approved_hash":"0894d3b45d6cf654b342997157a467aee83e5b9f4e870cf5252171f11b720499"},{"chunk_code":"HC1-B5","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ב","chunk_title":"סיכום דיני החיוב בזמן הזה","chunk_summary":"סיכום עיקרי הדינים: יסוד מצוות חלה מן התורה, חיובה מדרבנן בזמן הזה, משמעות רוב ישראל בארץ, דיני שמיטה ותרומה ושאלת עשרת השבטים.","content_markdown":"לסיכום:\n\n- יש מצוה דאורייתא לתת חלק מהעיסה לכהן.\n\n- המצווה מן התורה תקפה רק בארץ ישראל, ורק כאשר רוב היהודים גרים שם; אחרת, החיוב הוא רק מדרבנן.\n\n- בימינו, אם רוב היהודים כבר גרים בארץ ישראל (או אם זה יקרה בעתיד הקרוב), יש אומרים שהמצווה נעשית דאורייתא. אבל החזו\"א סובר שיתכן והיא תישאר דרבנן מפני שיתכן שצריך שהכניסה לארץ תיעשה בהנחיית ה', דהיינו על ידי מלך או נביא.\n\n- מצוות הפרשת חלה שייכת בחוץ לארץ מדרבנן כדי שהיא לא תשתכח.\n\n- מצוות שמיטה דאורייתא תחול רק כאשר הארץ תתיישב לפי השבטים ויחול שוב היובל.\n\n- לפי ראשונים רבים (הראב\"ד וטור), מצוות תרומה בימינו היא דאורייתא, אמנם השו\"ע פסק כמו הרמב\"ם שהיא מדרבנן.\n\n- החזון איש מודה לגבי תרומה שאם רוב היהודים בארץ ישראל המצווה חוזרת להיות דאורייתא.\n\n- ר' חיים קנייבסקי מציע שהמעמד של \"רוב ישראל יושבים בארץ ישראל\" יהיה תלוי בחזרת 10 השבטים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":25,"xmlIndex":27,"text":"לסיכום:","spans":[{"text":"לסיכום:"}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"list","paragraph":26,"xmlIndex":28,"text":"יש מצוה דאורייתא לתת חלק מהעיסה לכהן.","spans":[{"text":"יש מצוה דאורייתא לתת חלק מהעיסה לכהן."}],"marker":"•","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":27,"xmlIndex":29,"text":"המצווה מן התורה תקפה רק בארץ ישראל, ורק כאשר רוב היהודים גרים שם; אחרת, החיוב הוא רק מדרבנן.","spans":[{"text":"המצווה מן התורה תקפה רק בארץ ישראל, ורק כאשר רוב היהודים גרים שם; אחרת, החיוב הוא רק מדרבנן."}],"marker":"•","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":28,"xmlIndex":30,"text":"בימינו, אם רוב היהודים כבר גרים בארץ ישראל (או אם זה יקרה בעתיד הקרוב), יש אומרים שהמצווה נעשית דאורייתא. אבל החזו\"א סובר שיתכן והיא תישאר דרבנן מפני שיתכן שצריך שהכניסה לארץ תיעשה בהנחיית ה', דהיינו על ידי מלך או נביא.","spans":[{"text":"בימינו, אם רוב היהודים כבר גרים בארץ ישראל (או אם זה יקרה בעתיד הקרוב), יש אומרים שהמצווה נעשית דאורייתא. אבל החזו\"א סובר שיתכן והיא תישאר דרבנן מפני שיתכן שצריך שהכניסה לארץ תיעשה בהנחיית ה', דהיינו על ידי מלך או נביא."}],"marker":"•","level":0,"indent":72,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":29,"xmlIndex":31,"text":"מצוות הפרשת חלה שייכת בחוץ לארץ מדרבנן כדי שהיא לא תשתכח.","spans":[{"text":"מצוות הפרשת חלה שייכת בחוץ לארץ מדרבנן כדי שהיא לא תשתכח."}],"marker":"•","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":30,"xmlIndex":32,"text":"מצוות שמיטה דאורייתא תחול רק כאשר הארץ תתיישב לפי השבטים ויחול שוב היובל.","spans":[{"text":"מצוות שמיטה דאורייתא תחול רק כאשר הארץ תתיישב לפי השבטים ויחול שוב היובל."}],"marker":"•","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":31,"xmlIndex":33,"text":"לפי ראשונים רבים (הראב\"ד וטור), מצוות תרומה בימינו היא דאורייתא, אמנם השו\"ע פסק כמו הרמב\"ם שהיא מדרבנן.","spans":[{"text":"לפי ראשונים רבים (הראב\"ד וטור), מצוות תרומה בימינו היא דאורייתא, אמנם השו\"ע פסק כמו הרמב\"ם שהיא מדרבנן."}],"marker":"•","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":32,"xmlIndex":34,"text":"החזון איש מודה לגבי תרומה שאם רוב היהודים בארץ ישראל המצווה חוזרת להיות דאורייתא.","spans":[{"text":"החזון איש מודה לגבי תרומה שאם רוב היהודים בארץ ישראל המצווה חוזרת להיות דאורייתא."}],"marker":"•","level":0,"indent":72,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":33,"xmlIndex":35,"text":"ר' חיים קנייבסקי מציע שהמעמד של \"רוב ישראל יושבים בארץ ישראל\" יהיה תלוי בחזרת 10 השבטים.","spans":[{"text":"ר' חיים קנייבסקי מציע שהמעמד של \"רוב ישראל יושבים בארץ ישראל\" יהיה תלוי בחזרת 10 השבטים."}],"marker":"•","level":0,"indent":72,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"ad5ffc79000f84e112f3d2ed6c1ff5b111938d3188324f7e297e0cdecd037e99"},{"chunk_code":"HC1-C1","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שלושה הבדלים בין חלת ארץ ישראל לחלת חוץ לארץ","chunk_summary":"הצגת שלוש חומרות בחלת ארץ ישראל לעומת חלת חוץ לארץ: ביטול בתערובת, אכילה לפני הפרשה והצורך בהפרשה מן המוקף.","content_markdown":"*ג. הבדלים בין חלת ארץ ישראל לחלת חוץ לארץ*\n\nלמדנו לעיל שרוב הפוסקים סוברים שבימינו מצות הפרשת *חלה*, בין בארץ ישראל ובין בחוץ לארץ, היא רק מדרבנן. אף על פי כן, יש מקרים מסוימים בהם הפוסקים מחמירים יותר ב*חלת* ארץ ישראל מאשר ב*חלת* חו\"ל. סיבת החילוק היא שמצות הפרשת *חלה* בארץ ישראל היא בעיקרון מדאורייתא, ובימינו היא מדרבנן רק מפני שרוב היהודים אינם מתגוררים בארץ ישראל. לעומת זאת, מצות הפרשת *חלה* בחו\"ל מדרבנן נתקנה רק כדי שמצוה זו לא תישכח. נמנה שלש הבחנות למעשה בין *חלת* א\"י ל*חלת* חו\"ל ולאחר מכן ניישם עקרונות אלו בכמה מקרים מעשיים.\n\n1) השו\"ע ב**סימן שכג** (11) פסק שאם *חלה* שהופרשה בחו\"ל התערבבה בבצק היתר, התערובת מותרת אפילו כאשר היחס הוא רק 50-50. ועוד, מותר לאדם לבטל לכתחילה *חלת* חו\"ל. הרמ\"א חולק על שתי הנקודות הללו ופוסק שאם *חלה* התערבבה בבצק היתר, צריך יחס של 100:1 כדי להתיר את התערובת. אם היא התערבבה בסוג מאכל אחר (דהיינו, מין בשאינו מינו), צריך ביטול בשישים. ועוד, אסור לאדם לבטל לכתחילה איסור דרבנן (ראה רמ\"א סימן צט, ו). נמצא שלפי השו\"ע ניתן להקל ב*חלת* חו\"ל הרבה יותר מאשר *חלת* א\"י.\n\n2) נלמד להלן שלכתחילה יש להפריש *חלה* מהעיסה לפני האפיה. אולם, אם אדם שכח, הוא רשאי להפריש *חלה* אחרי אפית הלחם. השו\"ע (סוף **סימן שכג, א**) פסק על פי ה**גמרא ביצה** (ט, א), שאם אדם אפה לחם בחו\"ל בלי להפריש *חלה*, הוא רשאי לאכול את הלחם, בתנאי שהוא משאיר כמות קטנה ל*חלה*. הרמ\"א ביאר שצריך להשאיר כמות לחם שאחרי הפרשת *חלה* יישאר עדיין מעט מהלחם. כלומר, אין להפריש את כל החתיכה הנשארת ל*חלה*; אלא, חלק ממנה מופרש ל*חלה*. לעומת זאת, בארץ ישראל אין לאכול תחילה ולהפריש *חלה* לאחר מכן.\n\n3) בחו\"ל, אם הבצק מחולק למספר כיכרות ורק חלק מהן נמצאות במקום, ניתן להפריש *חלה* מהכיכרות הנמצאות ולפטור אפילו את הכיכרות שלא נמצאות במקום. אולם, בארץ ישראל יש להפריש *חלה* רק על לחם שנמצא במקום. ענין זה נקרא \"הפרשה שלא מן המוקף\". כפי שנלמד להלן, אם אדם מפריש שלא מן המוקף בארץ ישראל, ההפרשה מועילה בדיעבד. הרמ\"א מבהיר שאפילו בחו\"ל הפרשה מכיכר שנמצאת על כיכר שאיננה במקום מועילה רק אם שתי הכיכרות באו מאותה עיסה. אם הן נעשו משתי עיסות שונות, שכל אחת מהן בפני עצמה חייבת בהפרשת *חלה*, אזי אפילו בחו\"ל אין להפריש מכיכר על חברתה אם הן בשני מקומות שונים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":34,"xmlIndex":36,"text":"ג. הבדלים בין חלת ארץ ישראל לחלת חוץ לארץ","spans":[{"text":"ג. הבדלים בין חלת ארץ ישראל לחלת חוץ לארץ","italic":true,"color":"#2F5496"}],"marker":"","level":0,"indent":56,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"rightIndent":43.2,"hanging":18,"tabStops":[{"position":150.45,"alignment":"left","leader":"none"},{"position":234,"alignment":"center","leader":"none"},{"position":279,"alignment":"left","leader":"none"}]},{"kind":"paragraph","paragraph":35,"xmlIndex":38,"text":"למדנו לעיל שרוב הפוסקים סוברים שבימינו מצות הפרשת חלה, בין בארץ ישראל ובין בחוץ לארץ, היא רק מדרבנן. אף על פי כן, יש מקרים מסוימים בהם הפוסקים מחמירים יותר בחלת ארץ ישראל מאשר בחלת חו\"ל. סיבת החילוק היא שמצות הפרשת חלה בארץ ישראל היא בעיקרון מדאורייתא, ובימינו היא מדרבנן רק מפני שרוב היהודים אינם מתגוררים בארץ ישראל. לעומת זאת, מצות הפרשת חלה בחו\"ל מדרבנן נתקנה רק כדי שמצוה זו לא תישכח. נמנה שלש הבחנות למעשה בין חלת א\"י לחלת חו\"ל ולאחר מכן ניישם עקרונות אלו בכמה מקרים מעשיים.","spans":[{"text":"למדנו לעיל שרוב הפוסקים סוברים שבימינו מצות הפרשת "},{"text":"חלה","italic":true},{"text":", בין בארץ ישראל ובין בחוץ לארץ, היא רק מדרבנן. אף על פי כן, יש מקרים מסוימים בהם הפוסקים מחמירים יותר ב"},{"text":"חלת","italic":true},{"text":" ארץ ישראל מאשר ב"},{"text":"חלת","italic":true},{"text":" חו\"ל. סיבת החילוק היא שמצות הפרשת "},{"text":"חלה","italic":true},{"text":" בארץ ישראל היא בעיקרון מדאורייתא, ובימינו היא מדרבנן רק מפני שרוב היהודים אינם מתגוררים בארץ ישראל. לעומת זאת, מצות הפרשת "},{"text":"חלה","italic":true},{"text":" בחו\"ל מדרבנן נתקנה רק כדי שמצוה זו לא תישכח. נמנה שלש הבחנות למעשה בין "},{"text":"חלת","italic":true},{"text":" א\"י ל"},{"text":"חלת","italic":true},{"text":" חו\"ל ולאחר מכן ניישם עקרונות אלו בכמה מקרים מעשיים."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"list","paragraph":36,"xmlIndex":39,"text":"השו\"ע בסימן שכג (11) פסק שאם חלה שהופרשה בחו\"ל התערבבה בבצק היתר, התערובת מותרת אפילו כאשר היחס הוא רק 50-50. ועוד, מותר לאדם לבטל לכתחילה חלת חו\"ל. הרמ\"א חולק על שתי הנקודות הללו ופוסק שאם חלה התערבבה בבצק היתר, צריך יחס של 100:1 כדי להתיר את התערובת. אם היא התערבבה בסוג מאכל אחר (דהיינו, מין בשאינו מינו), צריך ביטול בשישים. ועוד, אסור לאדם לבטל לכתחילה איסור דרבנן (ראה רמ\"א סימן צט, ו). נמצא שלפי השו\"ע ניתן להקל בחלת חו\"ל הרבה יותר מאשר חלת א\"י.","spans":[{"text":"השו\"ע ב"},{"text":"סימן שכג","bold":true},{"text":" (11) פסק שאם "},{"text":"חלה","italic":true},{"text":" שהופרשה בחו\"ל התערבבה בבצק היתר, התערובת מותרת אפילו כאשר היחס הוא רק 50-50. ועוד, מותר לאדם לבטל לכתחילה "},{"text":"חלת","italic":true},{"text":" חו\"ל. הרמ\"א חולק על שתי הנקודות הללו ופוסק שאם "},{"text":"חלה","italic":true},{"text":" התערבבה בבצק היתר, צריך יחס של 100:1 כדי להתיר את התערובת. אם היא התערבבה בסוג מאכל אחר (דהיינו, מין בשאינו מינו), צריך ביטול בשישים. ועוד, אסור לאדם לבטל לכתחילה איסור דרבנן (ראה רמ\"א סימן צט, ו). נמצא שלפי השו\"ע ניתן להקל ב"},{"text":"חלת","italic":true},{"text":" חו\"ל הרבה יותר מאשר "},{"text":"חלת","italic":true},{"text":" א\"י."}],"marker":"1)","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":37,"xmlIndex":40,"text":"נלמד להלן שלכתחילה יש להפריש חלה מהעיסה לפני האפיה. אולם, אם אדם שכח, הוא רשאי להפריש חלה אחרי אפית הלחם. השו\"ע (סוף סימן שכג, א) פסק על פי הגמרא ביצה (ט, א), שאם אדם אפה לחם בחו\"ל בלי להפריש חלה, הוא רשאי לאכול את הלחם, בתנאי שהוא משאיר כמות קטנה לחלה. הרמ\"א ביאר שצריך להשאיר כמות לחם שאחרי הפרשת חלה יישאר עדיין מעט מהלחם. כלומר, אין להפריש את כל החתיכה הנשארת לחלה; אלא, חלק ממנה מופרש לחלה. לעומת זאת, בארץ ישראל אין לאכול תחילה ולהפריש חלה לאחר מכן.","spans":[{"text":"נלמד להלן שלכתחילה יש להפריש "},{"text":"חלה","italic":true},{"text":" מהעיסה לפני האפיה. אולם, אם אדם שכח, הוא רשאי להפריש "},{"text":"חלה","italic":true},{"text":" אחרי אפית הלחם. השו\"ע (סוף "},{"text":"סימן שכג, א","bold":true},{"text":") פסק על פי ה"},{"text":"גמרא ביצה","bold":true},{"text":" (ט, א), שאם אדם אפה לחם בחו\"ל בלי להפריש "},{"text":"חלה","italic":true},{"text":", הוא רשאי לאכול את הלחם, בתנאי שהוא משאיר כמות קטנה ל"},{"text":"חלה","italic":true},{"text":". הרמ\"א ביאר שצריך להשאיר כמות לחם שאחרי הפרשת "},{"text":"חלה","italic":true},{"text":" יישאר עדיין מעט מהלחם. כלומר, אין להפריש את כל החתיכה הנשארת ל"},{"text":"חלה","italic":true},{"text":"; אלא, חלק ממנה מופרש ל"},{"text":"חלה","italic":true},{"text":". לעומת זאת, בארץ ישראל אין לאכול תחילה ולהפריש "},{"text":"חלה","italic":true},{"text":" לאחר מכן."}],"marker":"2)","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":38,"xmlIndex":41,"text":"בחו\"ל, אם הבצק מחולק למספר כיכרות ורק חלק מהן נמצאות במקום, ניתן להפריש חלה מהכיכרות הנמצאות ולפטור אפילו את הכיכרות שלא נמצאות במקום. אולם, בארץ ישראל יש להפריש חלה רק על לחם שנמצא במקום. ענין זה נקרא \"הפרשה שלא מן המוקף\". כפי שנלמד להלן, אם אדם מפריש שלא מן המוקף בארץ ישראל, ההפרשה מועילה בדיעבד. הרמ\"א מבהיר שאפילו בחו\"ל הפרשה מכיכר שנמצאת על כיכר שאיננה במקום מועילה רק אם שתי הכיכרות באו מאותה עיסה. אם הן נעשו משתי עיסות שונות, שכל אחת מהן בפני עצמה חייבת בהפרשת חלה, אזי אפילו בחו\"ל אין להפריש מכיכר על חברתה אם הן בשני מקומות שונים.","spans":[{"text":"בחו\"ל, אם הבצק מחולק למספר כיכרות ורק חלק מהן נמצאות במקום, ניתן להפריש "},{"text":"חלה","italic":true},{"text":" מהכיכרות הנמצאות ולפטור אפילו את הכיכרות שלא נמצאות במקום. אולם, בארץ ישראל יש להפריש "},{"text":"חלה","italic":true},{"text":" רק על לחם שנמצא במקום. ענין זה נקרא \"הפרשה שלא מן המוקף\". כפי שנלמד להלן, אם אדם מפריש שלא מן המוקף בארץ ישראל, ההפרשה מועילה בדיעבד. הרמ\"א מבהיר שאפילו בחו\"ל הפרשה מכיכר שנמצאת על כיכר שאיננה במקום מועילה רק אם שתי הכיכרות באו מאותה עיסה. אם הן נעשו משתי עיסות שונות, שכל אחת מהן בפני עצמה חייבת בהפרשת "},{"text":"חלה","italic":true},{"text":", אזי אפילו בחו\"ל אין להפריש מכיכר על חברתה אם הן בשני מקומות שונים."}],"marker":"3)","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[11],"approved_hash":"386428d68a1fad666692a4ac05bc5a4a2aa55be737640f7133d12757415c7982"},{"chunk_code":"HC1-C2","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שכח להפריש חלה לפני שבת","chunk_summary":"בחוץ לארץ ניתן לאכול בשבת ולהשאיר לצורך הפרשה לאחריה; בארץ ישראל אין לאכול לפני הפרשה, אך בבין השמשות יש מקום להקל לצורך מצווה.","content_markdown":"**נפק\"מ למעשה:**\n\n<u>שכח להפריש</u> *<u>חלה</u>* <u>על החלות של שבת</u>\n\nמה לעשות אם בליל שבת לפני הסעודה אשתך אומרת לך שהיא שכחה להפריש *חלה* מהחלות[9] שהיא אפתה? השו\"ע ב**או\"ח סימן רסא, א** (12) פסק שאסור לאדם להפריש תרומה בשבת, או אפילו בבין השמשות. ה**משנ\"ב** סק\"ד ביאר שהפרשת *חלה* אסורה משום \"מתקן\", התרת החלה באכילה דומה לתיקון. על פי זה, אם אתה גר בחו\"ל ונזכר במהלך השבת שלא הפרשת *חלה*, אתה רשאי לאכול את החלה ולהשאיר כמות קטנה שגדולה מספיק כדי להפריש ממנה אחרי שבת. אולם, בארץ ישראל יהיה אסור לאכול מהחלה בשבת וצריך להמתין עד אחרי שבת כדי להפריש *חלה*. במקרה כזה צריך לבקש חלה מהשכנים.\n\nהמשנ\"ב מוסיף שאם אתה זוכר במהלך בין השמשות[10] ששכחת להפריש, אם אתה בארץ ישראל, מותר להפריש בכל זמן זה, אבל לא בחוץ לארץ. הוא מסביר שהואיל ובחו\"ל יש פתרון אפשרי בשבת להשאיר כמות לחם קטנה ולהפריש אחרי שבת, אסור להפריש בבין השמשות. אולם, בארץ ישראל שאין תקנה בשבת, מותר להפריש במהלך בין השמשות מפני שחז\"ל לא אסרו איסור דרבנן (כגון הפרשה בשבת) במהלך בין השמשות כאשר הדבר הוא צורך מצוה (כגון לחם משנה ועונג שבת).\n\nSource Notes\n\n[9]:  בסיכום זה, המילה \"*חלה*\" תהיה מוטית כאשר היא מתייחסת לחלק שמפרישים למצוה של הפרשת *חלה.* כאשר מתייחסים ללחם שאופים לכבוד שבת, היא תיכתב כרגיל. \n\n[10]:  בארץ ישראל, שיעור זה הוא עד בערך 13 דקות אחרי השקיעה, אבל במקומות אחרים בעולם, זה יכול להיות עד 20 דק'.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":39,"xmlIndex":42,"text":"נפק\"מ למעשה:","spans":[{"text":"נפק\"מ למעשה:","bold":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":40,"xmlIndex":43,"text":"שכח להפריש חלה על החלות של שבת","spans":[{"text":"שכח להפריש ","underline":true},{"text":"חלה","italic":true,"underline":true},{"text":" על החלות של שבת","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":41,"xmlIndex":44,"text":"מה לעשות אם בליל שבת לפני הסעודה אשתך אומרת לך שהיא שכחה להפריש חלה מהחלות[9] שהיא אפתה? השו\"ע באו\"ח סימן רסא, א (12) פסק שאסור לאדם להפריש תרומה בשבת, או אפילו בבין השמשות. המשנ\"ב סק\"ד ביאר שהפרשת חלה אסורה משום \"מתקן\", התרת החלה באכילה דומה לתיקון. על פי זה, אם אתה גר בחו\"ל ונזכר במהלך השבת שלא הפרשת חלה, אתה רשאי לאכול את החלה ולהשאיר כמות קטנה שגדולה מספיק כדי להפריש ממנה אחרי שבת. אולם, בארץ ישראל יהיה אסור לאכול מהחלה בשבת וצריך להמתין עד אחרי שבת כדי להפריש חלה. במקרה כזה צריך לבקש חלה מהשכנים.","spans":[{"text":"מה לעשות אם בליל שבת לפני הסעודה אשתך אומרת לך שהיא שכחה להפריש "},{"text":"חלה","italic":true},{"text":" מהחלות"},{"text":"[9]","footnote":9},{"text":" שהיא אפתה? השו\"ע ב"},{"text":"או\"ח סימן רסא, א","bold":true},{"text":" (12) פסק שאסור לאדם להפריש תרומה בשבת, או אפילו בבין השמשות. ה"},{"text":"משנ\"ב","bold":true},{"text":" סק\"ד ביאר שהפרשת "},{"text":"חלה","italic":true},{"text":" אסורה משום \"מתקן\", התרת החלה באכילה דומה לתיקון. על פי זה, אם אתה גר בחו\"ל ונזכר במהלך השבת שלא הפרשת "},{"text":"חלה","italic":true},{"text":", אתה רשאי לאכול את החלה ולהשאיר כמות קטנה שגדולה מספיק כדי להפריש ממנה אחרי שבת. אולם, בארץ ישראל יהיה אסור לאכול מהחלה בשבת וצריך להמתין עד אחרי שבת כדי להפריש "},{"text":"חלה","italic":true},{"text":". במקרה כזה צריך לבקש חלה מהשכנים."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[9],"defaultTabWidth":36},{"kind":"paragraph","paragraph":42,"xmlIndex":45,"text":"המשנ\"ב מוסיף שאם אתה זוכר במהלך בין השמשות[10] ששכחת להפריש, אם אתה בארץ ישראל, מותר להפריש בכל זמן זה, אבל לא בחוץ לארץ. הוא מסביר שהואיל ובחו\"ל יש פתרון אפשרי בשבת להשאיר כמות לחם קטנה ולהפריש אחרי שבת, אסור להפריש בבין השמשות. אולם, בארץ ישראל שאין תקנה בשבת, מותר להפריש במהלך בין השמשות מפני שחז\"ל לא אסרו איסור דרבנן (כגון הפרשה בשבת) במהלך בין השמשות כאשר הדבר הוא צורך מצוה (כגון לחם משנה ועונג שבת).","spans":[{"text":"המשנ\"ב מוסיף שאם אתה זוכר במהלך בין השמשות"},{"text":"[10]","footnote":10},{"text":" ששכחת להפריש, אם אתה בארץ ישראל, מותר להפריש בכל זמן זה, אבל לא בחוץ לארץ. הוא מסביר שהואיל ובחו\"ל יש פתרון אפשרי בשבת להשאיר כמות לחם קטנה ולהפריש אחרי שבת, אסור להפריש בבין השמשות. אולם, בארץ ישראל שאין תקנה בשבת, מותר להפריש במהלך בין השמשות מפני שחז\"ל לא אסרו איסור דרבנן (כגון הפרשה בשבת) במהלך בין השמשות כאשר הדבר הוא צורך מצוה (כגון לחם משנה ועונג שבת)."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[10],"defaultTabWidth":36}],"footnotes":[{"id":9,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" בסיכום זה, המילה \"חלה\" תהיה מוטית כאשר היא מתייחסת לחלק שמפרישים למצוה של הפרשת חלה. כאשר מתייחסים ללחם שאופים לכבוד שבת, היא תיכתב כרגיל. ","spans":[{"text":" בסיכום זה, המילה \""},{"text":"חלה","italic":true},{"text":"\" תהיה מוטית כאשר היא מתייחסת לחלק שמפרישים למצוה של הפרשת "},{"text":"חלה. ","italic":true},{"text":"כאשר מתייחסים ללחם שאופים לכבוד שבת, היא תיכתב כרגיל. "}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":10,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" בארץ ישראל, שיעור זה הוא עד בערך 13 דקות אחרי השקיעה, אבל במקומות אחרים בעולם, זה יכול להיות עד 20 דק'.","spans":[{"text":" בארץ ישראל, שיעור זה הוא עד בערך 13 דקות אחרי השקיעה, אבל במקומות אחרים בעולם, זה יכול להיות עד 20 דק'."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[12],"approved_hash":"fc6389dc28401f38a86aa17e8f8818fc32ed9907ac784f76969661979e5078a6"},{"chunk_code":"HC1-C3","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"נזכר שלא הפריש לאחר שהתחיל לאכול","chunk_summary":"ביום חול, בחוץ לארץ אפשר להמשיך לאכול ולהשאיר מהלחם; בארץ ישראל יש להפסיק, להפריש מן הנותר ולכוון גם על מה שכבר נאכל.","content_markdown":"<u>אכילת לחם בלי הפרשה</u>\n\nמה לעשות אם אתה מתחיל לאכול לחם ביום חול ואז נזכר שעדיין לא הפרשת *חלה*? בחו\"ל הפתרון פשוט – אתה יכול להמשיך לאכול כל עוד אתה משאיר חתיכת לחם קטנה ואחר כך להפריש *חלה* מהלחם שנשאר.\n\nמה יש לעשות בארץ ישראל, כשאסור להמשיך לאכול? ה**חיד\"א** בברכי יוסף (שכג, ד) (13) פסק שצריך להפריש *חלה* מיד מהלחם הנותר ולכוון שההפרשה תפטור גם את מה שכבר אכלת. הוא מסביר שלמרות שהלחם שנאכל כבר לא נמצא כאן, ובדרך כלל אסור להפריש בארץ ישראל על דבר שאיננו בפנינו, בדיעבד הפרשת ה*חלה* מועילה, ויש לעשות כל מה שאפשר כדי לתקן את המצב. עיקרון זה, שהפרשה שנעשית עבור אוכל שלא נמצא מועילה בדיעבד, כתוב בפירוש בשו\"ע **סימן שלא, כה**. השו\"ע פסק שלמרות שאסור לאדם להפריש תרומה על פירות שאינם לפניו, אם הוא עשה כן, ההפרשה חלה. ברכי יוסף מרחיב עיקרון זה גם למקרה שהאוכל כבר נאכל.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":43,"xmlIndex":46,"text":"אכילת לחם בלי הפרשה","spans":[{"text":"אכילת לחם בלי הפרשה","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":44,"xmlIndex":47,"text":"מה לעשות אם אתה מתחיל לאכול לחם ביום חול ואז נזכר שעדיין לא הפרשת חלה? בחו\"ל הפתרון פשוט – אתה יכול להמשיך לאכול כל עוד אתה משאיר חתיכת לחם קטנה ואחר כך להפריש חלה מהלחם שנשאר.","spans":[{"text":"מה לעשות אם אתה מתחיל לאכול לחם ביום חול ואז נזכר שעדיין לא הפרשת "},{"text":"חלה","italic":true},{"text":"? בחו\"ל הפתרון פשוט – אתה יכול להמשיך לאכול כל עוד אתה משאיר חתיכת לחם קטנה ואחר כך להפריש "},{"text":"חלה","italic":true},{"text":" מהלחם שנשאר."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":45,"xmlIndex":48,"text":"מה יש לעשות בארץ ישראל, כשאסור להמשיך לאכול? החיד\"א בברכי יוסף (שכג, ד) (13) פסק שצריך להפריש חלה מיד מהלחם הנותר ולכוון שההפרשה תפטור גם את מה שכבר אכלת. הוא מסביר שלמרות שהלחם שנאכל כבר לא נמצא כאן, ובדרך כלל אסור להפריש בארץ ישראל על דבר שאיננו בפנינו, בדיעבד הפרשת החלה מועילה, ויש לעשות כל מה שאפשר כדי לתקן את המצב. עיקרון זה, שהפרשה שנעשית עבור אוכל שלא נמצא מועילה בדיעבד, כתוב בפירוש בשו\"ע סימן שלא, כה. השו\"ע פסק שלמרות שאסור לאדם להפריש תרומה על פירות שאינם לפניו, אם הוא עשה כן, ההפרשה חלה. ברכי יוסף מרחיב עיקרון זה גם למקרה שהאוכל כבר נאכל.","spans":[{"text":"מה יש לעשות בארץ ישראל, כשאסור להמשיך לאכול? ה"},{"text":"חיד\"א","bold":true},{"text":" בברכי יוסף (שכג, ד) (13) פסק שצריך להפריש "},{"text":"חלה","italic":true},{"text":" מיד מהלחם הנותר ולכוון שההפרשה תפטור גם את מה שכבר אכלת. הוא מסביר שלמרות שהלחם שנאכל כבר לא נמצא כאן, ובדרך כלל אסור להפריש בארץ ישראל על דבר שאיננו בפנינו, בדיעבד הפרשת ה"},{"text":"חלה","italic":true},{"text":" מועילה, ויש לעשות כל מה שאפשר כדי לתקן את המצב. עיקרון זה, שהפרשה שנעשית עבור אוכל שלא נמצא מועילה בדיעבד, כתוב בפירוש בשו\"ע "},{"text":"סימן שלא, כה","bold":true},{"text":". השו\"ע פסק שלמרות שאסור לאדם להפריש תרומה על פירות שאינם לפניו, אם הוא עשה כן, ההפרשה חלה. ברכי יוסף מרחיב עיקרון זה גם למקרה שהאוכל כבר נאכל."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[13],"approved_hash":"a80f5021c7d858f6e586391f2bca6d06fc99a1393169ec49fe67d90a44f0f057"},{"chunk_code":"HC1-C4","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שליחת חלות ללא הפרשה — עיקר הבעיה","chunk_summary":"אישה בארץ ישראל שלחה חלות לאחרים ונזכרה בשבת שלא הפרישה; מתעוררות בעיות של הפרשה בשבת ושל הפרשה שלא מן המוקף.","content_markdown":"<u>נתינת חלה בלי להפריש</u>\n\nהייתה אישה בארץ ישראל[11] שאפתה חלות לשבת ושלחה אותן לילדים הנשואים שלה שגרו בעיר אחרת. בליל שבת היא נזכרה שהיא שכחה להפריש *חלה* ורצתה לדעת אם היא יכולה להפריש מהחלה שנשארה בבית שלה ולפטור את החלות שהיא שלחה לילדים שלה. במקרה כזה, צריך להתייחס לשתי בעיות. ראשית, הפרשה בשבת אסורה מדרבנן משום מתקן, ושנית, בארץ ישראל אסור להפריש על לחם שלא נמצא במקום. אף על פי כן, הזכרנו בקטע הקודם שלפי החיד\"א, במצבים של בדיעבד, מועילה הפרשה במקום אחד על לחם שנמצא במקום אחר. השאלה היא: האם מותר לאמא לעבור על שני איסורים דרבנן, תיקון והפרשה על לחם שלא נמצא במקום, כדי למנוע מהילדים שלה לעבור על איסור אכילת החלות בלי הפרשת *חלה*?\n\nSource Notes\n\n[11]:  אם זה היה קורה בחו\"ל, אפשר פשוט להשאיר קצת חלה עד אחרי שבת ולהפריש מאותה חתיכה על מה שכבר נאכל ומה שנשלח לאחרים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":46,"xmlIndex":49,"text":"נתינת חלה בלי להפריש","spans":[{"text":"נתינת חלה בלי להפריש","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":47,"xmlIndex":50,"text":"הייתה אישה בארץ ישראל[11] שאפתה חלות לשבת ושלחה אותן לילדים הנשואים שלה שגרו בעיר אחרת. בליל שבת היא נזכרה שהיא שכחה להפריש חלה ורצתה לדעת אם היא יכולה להפריש מהחלה שנשארה בבית שלה ולפטור את החלות שהיא שלחה לילדים שלה. במקרה כזה, צריך להתייחס לשתי בעיות. ראשית, הפרשה בשבת אסורה מדרבנן משום מתקן, ושנית, בארץ ישראל אסור להפריש על לחם שלא נמצא במקום. אף על פי כן, הזכרנו בקטע הקודם שלפי החיד\"א, במצבים של בדיעבד, מועילה הפרשה במקום אחד על לחם שנמצא במקום אחר. השאלה היא: האם מותר לאמא לעבור על שני איסורים דרבנן, תיקון והפרשה על לחם שלא נמצא במקום, כדי למנוע מהילדים שלה לעבור על איסור אכילת החלות בלי הפרשת חלה?","spans":[{"text":"הייתה אישה בארץ ישראל"},{"text":"[11]","footnote":11},{"text":" שאפתה חלות לשבת ושלחה אותן לילדים הנשואים שלה שגרו בעיר אחרת. בליל שבת היא נזכרה שהיא שכחה להפריש "},{"text":"חלה","italic":true},{"text":" ורצתה לדעת אם היא יכולה להפריש מהחלה שנשארה בבית שלה ולפטור את החלות שהיא שלחה לילדים שלה. במקרה כזה, צריך להתייחס לשתי בעיות. ראשית, הפרשה בשבת אסורה מדרבנן משום מתקן, ושנית, בארץ ישראל אסור להפריש על לחם שלא נמצא במקום. אף על פי כן, הזכרנו בקטע הקודם שלפי החיד\"א, במצבים של בדיעבד, מועילה הפרשה במקום אחד על לחם שנמצא במקום אחר. השאלה היא: האם מותר לאמא לעבור על שני איסורים דרבנן, תיקון והפרשה על לחם שלא נמצא במקום, כדי למנוע מהילדים שלה לעבור על איסור אכילת החלות בלי הפרשת "},{"text":"חלה","italic":true},{"text":"?"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[11],"defaultTabWidth":36}],"footnotes":[{"id":11,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" אם זה היה קורה בחו\"ל, אפשר פשוט להשאיר קצת חלה עד אחרי שבת ולהפריש מאותה חתיכה על מה שכבר נאכל ומה שנשלח לאחרים.","spans":[{"text":" אם זה היה קורה בחו\"ל, אפשר פשוט להשאיר קצת חלה עד אחרי שבת ולהפריש מאותה חתיכה על מה שכבר נאכל ומה שנשלח לאחרים."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"2e7b22772e502556b9236b8fcbc478f4eb9a02a1e94701223261595ddc00e06c"},{"chunk_code":"HC1-C5","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שליחת חלות — היתר הברוך אומר","chunk_summary":"הברוך אומר דן בהיתר לעבור על איסורים קלים כדי למנוע מאחרים אכילת טבל, ובפרט כשמי ששלח את החלות גרם לתקלה.","content_markdown":"**ברוך אומר** (יו\"ד כב) (14) מביא את ה**גמרא עירובין** (לב, ב), שמלמדת ש'חבר' (דהיינו, תלמיד חכם) מותר להפריש על מאכל שלא לפניו, כדי למנוע מעם הארץ לאכול טבל (פירות שלא הופרשו מהם תרומה). הגמרא מסבירה שלמרות שאסור לאדם להפריש על דבר שלא נמצא בפניו, כאן מותר כדי למנוע מאחר לעשות איסור חמור יותר של אכילת טבל.\n\n**תוספות** באחד[12] מהפירושים שלו, כתב שדין זה שייך רק כאשר זו אשמתו של ה'חבר' שאותו אדם עומד לאכול טבל (כגון, ה'חבר' שלח לו טבל בלי להפריש קודם). על פי ביאור זה של תוספות, ברוך אומר פסק שהואיל וזו אשמת האמא שהילדים שלה יאכלו טבל, מותר לה לעבור על איסור קל יותר של הפרשת על אוכל שלא בפניה ועל האיסור הקל של הפרשה בשבת כדי למנוע מילדיה לעבור על איסור חמור יותר של אכילת טבל.\n\nהוא מסיק שהואיל והאמא כבר מפרישה *חלה* כדי להציל את החלות שהיא שלחה לילדים היא יכולה לכלול באותה הפרשה גם את החלות שנשארו בבית (מהן היא עושה את ההפרשה), וגם לה יהיה מותר לאכול מהן בשבת.\n\nSource Notes\n\n[12]:  בפירוש השני, הוא כתב שאפילו אם זה לא הייתה אשמת ה'חבר', עדיין מותר לו להפריש. נראה שכך פסקו משנ\"ב סימן שו סקנ\"ו ודרך אמונה (תרומות פ\"ג – ציון ההלכה סקרפ\"ט).","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":48,"xmlIndex":51,"text":"ברוך אומר (יו\"ד כב) (14) מביא את הגמרא עירובין (לב, ב), שמלמדת ש'חבר' (דהיינו, תלמיד חכם) מותר להפריש על מאכל שלא לפניו, כדי למנוע מעם הארץ לאכול טבל (פירות שלא הופרשו מהם תרומה). הגמרא מסבירה שלמרות שאסור לאדם להפריש על דבר שלא נמצא בפניו, כאן מותר כדי למנוע מאחר לעשות איסור חמור יותר של אכילת טבל.","spans":[{"text":"ברוך אומר","bold":true},{"text":" (יו\"ד כב) (14) מביא את ה"},{"text":"גמרא עירובין","bold":true},{"text":" (לב, ב), שמלמדת ש'חבר' (דהיינו, תלמיד חכם) מותר להפריש על מאכל שלא לפניו, כדי למנוע מעם הארץ לאכול טבל (פירות שלא הופרשו מהם תרומה). הגמרא מסבירה שלמרות שאסור לאדם להפריש על דבר שלא נמצא בפניו, כאן מותר כדי למנוע מאחר לעשות איסור חמור יותר של אכילת טבל."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":49,"xmlIndex":52,"text":"תוספות באחד[12] מהפירושים שלו, כתב שדין זה שייך רק כאשר זו אשמתו של ה'חבר' שאותו אדם עומד לאכול טבל (כגון, ה'חבר' שלח לו טבל בלי להפריש קודם). על פי ביאור זה של תוספות, ברוך אומר פסק שהואיל וזו אשמת האמא שהילדים שלה יאכלו טבל, מותר לה לעבור על איסור קל יותר של הפרשת על אוכל שלא בפניה ועל האיסור הקל של הפרשה בשבת כדי למנוע מילדיה לעבור על איסור חמור יותר של אכילת טבל.","spans":[{"text":"תוספות","bold":true},{"text":" באחד"},{"text":"[12]","footnote":12},{"text":" מהפירושים שלו, כתב שדין זה שייך רק כאשר זו אשמתו של ה'חבר' שאותו אדם עומד לאכול טבל (כגון, ה'חבר' שלח לו טבל בלי להפריש קודם). על פי ביאור זה של תוספות, ברוך אומר פסק שהואיל וזו אשמת האמא שהילדים שלה יאכלו טבל, מותר לה לעבור על איסור קל יותר של הפרשת על אוכל שלא בפניה ועל האיסור הקל של הפרשה בשבת כדי למנוע מילדיה לעבור על איסור חמור יותר של אכילת טבל."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[12],"defaultTabWidth":36},{"kind":"paragraph","paragraph":50,"xmlIndex":53,"text":"הוא מסיק שהואיל והאמא כבר מפרישה חלה כדי להציל את החלות שהיא שלחה לילדים היא יכולה לכלול באותה הפרשה גם את החלות שנשארו בבית (מהן היא עושה את ההפרשה), וגם לה יהיה מותר לאכול מהן בשבת.","spans":[{"text":"הוא מסיק שהואיל והאמא כבר מפרישה "},{"text":"חלה","italic":true},{"text":" כדי להציל את החלות שהיא שלחה לילדים היא יכולה לכלול באותה הפרשה גם את החלות שנשארו בבית (מהן היא עושה את ההפרשה), וגם לה יהיה מותר לאכול מהן בשבת."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":12,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" בפירוש השני, הוא כתב שאפילו אם זה לא הייתה אשמת ה'חבר', עדיין מותר לו להפריש. נראה שכך פסקו משנ\"ב סימן שו סקנ\"ו ודרך אמונה (תרומות פ\"ג – ציון ההלכה סקרפ\"ט).","spans":[{"text":" בפירוש השני, הוא כתב שאפילו אם זה לא הייתה אשמת ה'חבר', עדיין מותר לו להפריש. נראה שכך פסקו משנ\"ב סימן שו סקנ\"ו ודרך אמונה (תרומות פ\"ג – ציון ההלכה סקרפ\"ט)."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[14],"approved_hash":"7919ede222106cbfe6799b08aa25bdceadd10549f94682a1f180c56ceea3c9fe"},{"chunk_code":"HC1-C6","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שליחת חלות — קושיית הנתיבות וסיכום השיטות","chunk_summary":"לפי הנתיבות, כאשר המקבלים שוגגים באיסור דרבנן, אין בהכרח הצדקה לעבור על איסורים כדי להצילם; מובאים צדדים להקל וסיכום השיטות.","content_markdown":"אולם, דרך זו לכאורה עומדת בניגוד לדעת **נתיבות המשפט** (רלד, ג) (15). ונבאר: הנתיבות פסק שלמרות שמי שעובר בשוגג על איסור דאורייתא חייב לעשות תשובה, מי שעובר בשוגג על איסור דרבנן אינו צריך לעשות תשובה. **משנת יהושע** (חושן משפט, סז) (16) ביאר שלגבי איסור דאורייתא, המעשה אסור במהותו (איסור \"חפצא\"), ואפילו כאשר אדם עובד בשוגג, עליו לעשות תשובה. לדוגמא, אם אדם שכח שהיום שבת והדליק גפרור, הואיל והמעשה בעצמותו אסור הוא חייב לחזור בתשובה, אפילו שהעבירה נעשתה בשוגג. לעומת זאת, איסור דרבנן נתקן על האדם (\"גברא\") שישמע לדברי חז\"ל, וכשאדם עובר בשוגג על איסור דרבנן, זה לא נחשב שהוא לא שמע לדברי חז\"ל. רק עבירה במזיד על דברי חכמים נחשבת כמעשה נגד דבריהם, אבל מי שבטעות לא ציית להוראתם לא נחשב כמי ש\"לא שמע\" לדברי חז\"ל.\n\nלפי סברת הנתיבות, אפילו אם הילדים אכלו חלת טבל בשוגג, הם לא עשו שום דבר אסור ולא יהיו צריכים לעשות תשובה מפני שהם עברו **בשוגג** על איסור **דרבנן.**[13] לפיכך, יהיה אסור לאמא לעבור על שני האיסורים של הפרשה בשבת וממקום אחד על השני, מפני שהיא לא מצילה אותם מאיסור שצריך לתקן.\n\nאף על פי כן, עדיין יש מספר סיבות מדוע יתכן שכדאי שהאמא תפריש: 1) שמא בימינו רוב היהודים בעולם כבר גרים בארץ ישראל, וכתוצאה מכך חיוב הפרשת *חלה* הוא דאורייתא לפי דעות רבות, כפי שהתבאר לעיל. 2) נראה שרוב הפוסקים חולקים על הנתיבות, כגון **שער הציון** (שלד, סקס\"ה) שכתב שמי שעובר בשוגג על איסור דרבנן בשבת צריך לעשות תשובה. למעשה, כל אחד ישאל את רבו מה לעשות בשבת, אבל במהלך השבוע רוב הפוסקים מקילים ומתירים להפריש על חלה שנמצאת במקום אחר אם אין דרך ליידע את המקבל; ראה דרך אמונה (ביה\"ל תרומות פ\"ג, רפט).\n\nלסיכום, אם בארץ ישראל שכחת להפריש *חלה* לפני ששלחת חלק מהלחם מקום אחר ונזכרת רק בשבת:\n\n- ברוך אומר מתיר לעבור על שני איסורים קלים מדרבנן של הפרשה על מקום אחר והפרשה בשבת, כדי למנוע אחרים מלעבור על איסור גדול יותר של אכילת טבל.\n\n- הנתיבות לכאורה יאסור לעשות כן, בכלל שהמקבל לא יעבור על איסור דרבנן (הואיל והוא לא יודע על כך).\n\n- יש חולקים על הנתיבות, ויש פוסקים שמותר להפריש במקרה זה.\n\nSource Notes\n\n[13]:  במקרה זה, כשלא הייתה לילדים שום דרך לדעת שלא נעשתה הפרשת *חלה*, יש אף מקום נוסף להקל, הואיל והמקרה שלהם דומה יותר לאונס מאשר לשוגג.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":51,"xmlIndex":54,"text":"אולם, דרך זו לכאורה עומדת בניגוד לדעת נתיבות המשפט (רלד, ג) (15). ונבאר: הנתיבות פסק שלמרות שמי שעובר בשוגג על איסור דאורייתא חייב לעשות תשובה, מי שעובר בשוגג על איסור דרבנן אינו צריך לעשות תשובה. משנת יהושע (חושן משפט, סז) (16) ביאר שלגבי איסור דאורייתא, המעשה אסור במהותו (איסור \"חפצא\"), ואפילו כאשר אדם עובד בשוגג, עליו לעשות תשובה. לדוגמא, אם אדם שכח שהיום שבת והדליק גפרור, הואיל והמעשה בעצמותו אסור הוא חייב לחזור בתשובה, אפילו שהעבירה נעשתה בשוגג. לעומת זאת, איסור דרבנן נתקן על האדם (\"גברא\") שישמע לדברי חז\"ל, וכשאדם עובר בשוגג על איסור דרבנן, זה לא נחשב שהוא לא שמע לדברי חז\"ל. רק עבירה במזיד על דברי חכמים נחשבת כמעשה נגד דבריהם, אבל מי שבטעות לא ציית להוראתם לא נחשב כמי ש\"לא שמע\" לדברי חז\"ל.","spans":[{"text":"אולם, דרך זו לכאורה עומדת בניגוד לדעת "},{"text":"נתיבות המשפט","bold":true},{"text":" (רלד, ג) (15). ונבאר: הנתיבות פסק שלמרות שמי שעובר בשוגג על איסור דאורייתא חייב לעשות תשובה, מי שעובר בשוגג על איסור דרבנן אינו צריך לעשות תשובה. "},{"text":"משנת יהושע","bold":true},{"text":" (חושן משפט, סז) (16) ביאר שלגבי איסור דאורייתא, המעשה אסור במהותו (איסור \"חפצא\"), ואפילו כאשר אדם עובד בשוגג, עליו לעשות תשובה. לדוגמא, אם אדם שכח שהיום שבת והדליק גפרור, הואיל והמעשה בעצמותו אסור הוא חייב לחזור בתשובה, אפילו שהעבירה נעשתה בשוגג. לעומת זאת, איסור דרבנן נתקן על האדם (\"גברא\") שישמע לדברי חז\"ל, וכשאדם עובר בשוגג על איסור דרבנן, זה לא נחשב שהוא לא שמע לדברי חז\"ל. רק עבירה במזיד על דברי חכמים נחשבת כמעשה נגד דבריהם, אבל מי שבטעות לא ציית להוראתם לא נחשב כמי ש\"לא שמע\" לדברי חז\"ל."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":52,"xmlIndex":55,"text":"לפי סברת הנתיבות, אפילו אם הילדים אכלו חלת טבל בשוגג, הם לא עשו שום דבר אסור ולא יהיו צריכים לעשות תשובה מפני שהם עברו בשוגג על איסור דרבנן.[13] לפיכך, יהיה אסור לאמא לעבור על שני האיסורים של הפרשה בשבת וממקום אחד על השני, מפני שהיא לא מצילה אותם מאיסור שצריך לתקן.","spans":[{"text":"לפי סברת הנתיבות, אפילו אם הילדים אכלו חלת טבל בשוגג, הם לא עשו שום דבר אסור ולא יהיו צריכים לעשות תשובה מפני שהם עברו "},{"text":"בשוגג ","bold":true},{"text":"על איסור "},{"text":"דרבנן.","bold":true},{"text":"[13]","footnote":13},{"text":" ","bold":true},{"text":"לפיכך, יהיה אסור לאמא לעבור על שני האיסורים של הפרשה בשבת וממקום אחד על השני, מפני שהיא לא מצילה אותם מאיסור שצריך לתקן."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[13],"defaultTabWidth":36},{"kind":"paragraph","paragraph":53,"xmlIndex":56,"text":"אף על פי כן, עדיין יש מספר סיבות מדוע יתכן שכדאי שהאמא תפריש: 1) שמא בימינו רוב היהודים בעולם כבר גרים בארץ ישראל, וכתוצאה מכך חיוב הפרשת חלה הוא דאורייתא לפי דעות רבות, כפי שהתבאר לעיל. 2) נראה שרוב הפוסקים חולקים על הנתיבות, כגון שער הציון (שלד, סקס\"ה) שכתב שמי שעובר בשוגג על איסור דרבנן בשבת צריך לעשות תשובה. למעשה, כל אחד ישאל את רבו מה לעשות בשבת, אבל במהלך השבוע רוב הפוסקים מקילים ומתירים להפריש על חלה שנמצאת במקום אחר אם אין דרך ליידע את המקבל; ראה דרך אמונה (ביה\"ל תרומות פ\"ג, רפט).","spans":[{"text":"אף על פי כן, עדיין יש מספר סיבות מדוע יתכן שכדאי שהאמא תפריש: 1) שמא בימינו רוב היהודים בעולם כבר גרים בארץ ישראל, וכתוצאה מכך חיוב הפרשת "},{"text":"חלה","italic":true},{"text":" הוא דאורייתא לפי דעות רבות, כפי שהתבאר לעיל. 2) נראה שרוב הפוסקים חולקים על הנתיבות, כגון "},{"text":"שער הציון","bold":true},{"text":" (שלד, סקס\"ה) שכתב שמי שעובר בשוגג על איסור דרבנן בשבת צריך לעשות תשובה. למעשה, כל אחד ישאל את רבו מה לעשות בשבת, אבל במהלך השבוע רוב הפוסקים מקילים ומתירים להפריש על חלה שנמצאת במקום אחר אם אין דרך ליידע את המקבל; ראה דרך אמונה (ביה\"ל תרומות פ\"ג, רפט)."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":54,"xmlIndex":57,"text":"לסיכום, אם בארץ ישראל שכחת להפריש חלה לפני ששלחת חלק מהלחם מקום אחר ונזכרת רק בשבת:","spans":[{"text":"לסיכום, אם בארץ ישראל שכחת להפריש "},{"text":"חלה","italic":true},{"text":" לפני ששלחת חלק מהלחם מקום אחר ונזכרת רק בשבת:"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"list","paragraph":55,"xmlIndex":58,"text":"ברוך אומר מתיר לעבור על שני איסורים קלים מדרבנן של הפרשה על מקום אחר והפרשה בשבת, כדי למנוע אחרים מלעבור על איסור גדול יותר של אכילת טבל.","spans":[{"text":"ברוך אומר מתיר לעבור על שני איסורים קלים מדרבנן של הפרשה על מקום אחר והפרשה בשבת, כדי למנוע אחרים מלעבור על איסור גדול יותר של אכילת טבל."}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":56,"xmlIndex":59,"text":"הנתיבות לכאורה יאסור לעשות כן, בכלל שהמקבל לא יעבור על איסור דרבנן (הואיל והוא לא יודע על כך).","spans":[{"text":"הנתיבות לכאורה יאסור לעשות כן, בכלל שהמקבל לא יעבור על איסור דרבנן (הואיל והוא לא יודע על כך)."}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":57,"xmlIndex":60,"text":"יש חולקים על הנתיבות, ויש פוסקים שמותר להפריש במקרה זה.","spans":[{"text":"יש חולקים על הנתיבות, ויש פוסקים שמותר להפריש במקרה זה."}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18}],"footnotes":[{"id":13,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" במקרה זה, כשלא הייתה לילדים שום דרך לדעת שלא נעשתה הפרשת חלה, יש אף מקום נוסף להקל, הואיל והמקרה שלהם דומה יותר לאונס מאשר לשוגג.","spans":[{"text":" במקרה זה, כשלא הייתה לילדים שום דרך לדעת שלא נעשתה הפרשת "},{"text":"חלה","italic":true},{"text":", יש אף מקום נוסף להקל, הואיל והמקרה שלהם דומה יותר לאונס מאשר לשוגג."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[15,16],"approved_hash":"64d5ce831181cd26e1921ecc39be2a1de1cd39efa7ee9c386f100e31d9abbcc8"},{"chunk_code":"HC1-C7","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"מצות — מדוע מפרישים לעיתים רק לאחר האפייה","chunk_summary":"בגלל החשש לחימוץ והכנת עיסות קטנות, הפרשת חלה ממצות נעשית לעיתים לאחר האפייה; יש קונים מצות כדי להפריש מהן בעצמם.","content_markdown":"<u>שכח להפריש</u> *<u>חלה</u>* <u>ממצה</u>\n\nלכתחילה, מצות הפרשת *חלה* צריכה להיעשות מיד אחרי שערבבו את המים והקמח והם נעשו בצק (אנו נלמד בהמשך את הזמן המדויק בו לכתחילה יש להפריש). אולם, לגבי מצה השו\"ע באו\"ח סימן תנז פסק שיש לעשות הפרשת *חלה* אחרי אפית המצה, משתי סיבות. ראשית, אם מפרישים את ה*חלה* מהבצק יהיה צריך לשרוף את החלק המופרש תוך 18 דקות לפני שזה ייעשה חמץ, ואופי מצות לא רוצים דבר שעלול להחמיץ במאפיית המצות. שנית, כמות הקמח שמשתמשים בה לכל עיסה אינה עומדת בשיעור הנדרש להפרשת *חלה*.[14] לפיכך, אחרי אפית המצות, שמים את כולם בכלי גדול או בעגלה אחת ומפרישים *חלה* מהכל ביחד. יש מאפיות מצות שמוכרים מצות שלא הפרישו מהן עדיין *חלה*, כדי שהקונה יוכל לברך ולקיים את המצוה של הפרשת *חלה*.\n\nSource Notes\n\n[14]:  השו\"ע אינו מציע דרך לצרף יחד את העיסות אלא מסיק שעדיף להפריש אחרי האפיה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":58,"xmlIndex":61,"text":"שכח להפריש חלה ממצה","spans":[{"text":"שכח להפריש ","underline":true},{"text":"חלה","italic":true,"underline":true},{"text":" ממצה","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":59,"xmlIndex":62,"text":"לכתחילה, מצות הפרשת חלה צריכה להיעשות מיד אחרי שערבבו את המים והקמח והם נעשו בצק (אנו נלמד בהמשך את הזמן המדויק בו לכתחילה יש להפריש). אולם, לגבי מצה השו\"ע באו\"ח סימן תנז פסק שיש לעשות הפרשת חלה אחרי אפית המצה, משתי סיבות. ראשית, אם מפרישים את החלה מהבצק יהיה צריך לשרוף את החלק המופרש תוך 18 דקות לפני שזה ייעשה חמץ, ואופי מצות לא רוצים דבר שעלול להחמיץ במאפיית המצות. שנית, כמות הקמח שמשתמשים בה לכל עיסה אינה עומדת בשיעור הנדרש להפרשת חלה.[14] לפיכך, אחרי אפית המצות, שמים את כולם בכלי גדול או בעגלה אחת ומפרישים חלה מהכל ביחד. יש מאפיות מצות שמוכרים מצות שלא הפרישו מהן עדיין חלה, כדי שהקונה יוכל לברך ולקיים את המצוה של הפרשת חלה.","spans":[{"text":"לכתחילה, מצות הפרשת "},{"text":"חלה","italic":true},{"text":" צריכה להיעשות מיד אחרי שערבבו את המים והקמח והם נעשו בצק (אנו נלמד בהמשך את הזמן המדויק בו לכתחילה יש להפריש). אולם, לגבי מצה השו\"ע באו\"ח סימן תנז פסק שיש לעשות הפרשת "},{"text":"חלה","italic":true},{"text":" אחרי אפית המצה, משתי סיבות. ראשית, אם מפרישים את ה"},{"text":"חלה","italic":true},{"text":" מהבצק יהיה צריך לשרוף את החלק המופרש תוך 18 דקות לפני שזה ייעשה חמץ, ואופי מצות לא רוצים דבר שעלול להחמיץ במאפיית המצות. שנית, כמות הקמח שמשתמשים בה לכל עיסה אינה עומדת בשיעור הנדרש להפרשת "},{"text":"חלה","italic":true},{"text":"."},{"text":"[14]","footnote":14},{"text":" לפיכך, אחרי אפית המצות, שמים את כולם בכלי גדול או בעגלה אחת ומפרישים "},{"text":"חלה","italic":true},{"text":" מהכל ביחד. יש מאפיות מצות שמוכרים מצות שלא הפרישו מהן עדיין "},{"text":"חלה","italic":true},{"text":", כדי שהקונה יוכל לברך ולקיים את המצוה של הפרשת "},{"text":"חלה","italic":true},{"text":"."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[14],"defaultTabWidth":36}],"footnotes":[{"id":14,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" השו\"ע אינו מציע דרך לצרף יחד את העיסות אלא מסיק שעדיף להפריש אחרי האפיה.","spans":[{"text":" השו\"ע אינו מציע דרך לצרף יחד את העיסות אלא מסיק שעדיף להפריש אחרי האפיה."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"d483e46e659d475c3002861fee93c913546f686d9ca82a71ae596434a57532bf"},{"chunk_code":"HC1-C8","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שכח להפריש חלה ממצות בחוץ לארץ בליל פסח","chunk_summary":"לפי המשנה ברורה, יש להשאיר מן המצות או מן העיסות הנצרכות, ולאחר יום טוב לצרף את השאריות ולהפריש מהן חלה.","content_markdown":"מה לעשות אם אפית מצות כחלק מחבורה במאפית המצות ושכחת להפריש *חלה* מהמצות שלך לאחר מכן, ורק בליל פסח נזכרת בכך? ה**משנ\"ב** (תנז סק\"י) (17) כתב שהפרשה ביו\"ט אסורה כמו בשבת. לפיכך, אם חיוב ההפרשה כבר חל לפני יו\"ט (כגון שהמצות צורפו יחד בכלי, או שהיה שיעור מספיק בכל עיסה בפני עצמה), כתב המשנ\"ב שבחו\"ל הדין הוא כך: אם ידעת אלו מצות הגיעו מכל עיסה (כגון, קנית מצות מקמח מלא ומצות מקמח רגיל ואתה יכול להבחין ביניהם), יש להשאיר מצה מכל סוג ולהפריש ממנה אחרי יו\"ט. אם אתה לא יודע להבחין מה המקור של המצות ומאיזו עיסה הן באו (כגון, קנית מצות רגילות משתי מקורות שונים וכולן חייבות בחלה), צריך להשאיר חתיכה קטנה מכל מצה. אחרי יו\"ט יש לצרף את כל החתיכות לכלי ולהפריש משם. **שער הציון** (כא) ביאר שהואיל והשאריות מכל מצה צורפו בתוך כלי, מועילה הפרשה אחת עבור כולן.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":60,"xmlIndex":63,"text":"מה לעשות אם אפית מצות כחלק מחבורה במאפית המצות ושכחת להפריש חלה מהמצות שלך לאחר מכן, ורק בליל פסח נזכרת בכך? המשנ\"ב (תנז סק\"י) (17) כתב שהפרשה ביו\"ט אסורה כמו בשבת. לפיכך, אם חיוב ההפרשה כבר חל לפני יו\"ט (כגון שהמצות צורפו יחד בכלי, או שהיה שיעור מספיק בכל עיסה בפני עצמה), כתב המשנ\"ב שבחו\"ל הדין הוא כך: אם ידעת אלו מצות הגיעו מכל עיסה (כגון, קנית מצות מקמח מלא ומצות מקמח רגיל ואתה יכול להבחין ביניהם), יש להשאיר מצה מכל סוג ולהפריש ממנה אחרי יו\"ט. אם אתה לא יודע להבחין מה המקור של המצות ומאיזו עיסה הן באו (כגון, קנית מצות רגילות משתי מקורות שונים וכולן חייבות בחלה), צריך להשאיר חתיכה קטנה מכל מצה. אחרי יו\"ט יש לצרף את כל החתיכות לכלי ולהפריש משם. שער הציון (כא) ביאר שהואיל והשאריות מכל מצה צורפו בתוך כלי, מועילה הפרשה אחת עבור כולן.","spans":[{"text":"מה לעשות אם אפית מצות כחלק מחבורה במאפית המצות ושכחת להפריש "},{"text":"חלה","italic":true},{"text":" מהמצות שלך לאחר מכן, ורק בליל פסח נזכרת בכך? ה"},{"text":"משנ\"ב","bold":true},{"text":" (תנז סק\"י) (17) כתב שהפרשה ביו\"ט אסורה כמו בשבת. לפיכך, אם חיוב ההפרשה כבר חל לפני יו\"ט (כגון שהמצות צורפו יחד בכלי, או שהיה שיעור מספיק בכל עיסה בפני עצמה), כתב המשנ\"ב שבחו\"ל הדין הוא כך: אם ידעת אלו מצות הגיעו מכל עיסה (כגון, קנית מצות מקמח מלא ומצות מקמח רגיל ואתה יכול להבחין ביניהם), יש להשאיר מצה מכל סוג ולהפריש ממנה אחרי יו\"ט. אם אתה לא יודע להבחין מה המקור של המצות ומאיזו עיסה הן באו (כגון, קנית מצות רגילות משתי מקורות שונים וכולן חייבות בחלה), צריך להשאיר חתיכה קטנה מכל מצה. אחרי יו\"ט יש לצרף את כל החתיכות לכלי ולהפריש משם. "},{"text":"שער הציון","bold":true},{"text":" (כא) ביאר שהואיל והשאריות מכל מצה צורפו בתוך כלי, מועילה הפרשה אחת עבור כולן."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[17],"approved_hash":"0ac36ee164c2f8cca3d86b810c297467e132bc8fcfe7f6c2c6faf5b993ac23cd"},{"chunk_code":"HC1-C9","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שכח להפריש חלה ממצות בארץ ישראל — שלושה פתרונות","chunk_summary":"שלוש אפשרויות הנידונות בפוסקים: היתר הרשז״א כשאין מצה אחרת לקיום מצוות הלילה; הפרשה בידי קטן בגיל המתאים; והפרשה מוקדמת של רב הקהילה, על הקושי שבה.","content_markdown":"הנ\"ל שייך רק בחו\"ל, שם מותר להשאיר מהמצה ולהפריש אחרי יו\"ט. מה עושים בא\"י? יש 3 פתרונות אפשריים.\n\n1) **שש\"כ** (פרק יא, טז) (18), בשם **רשז\"א**, פסק שבא\"י אם אין דרך אחרת להשיג מצה כשרה (כגון, נופש פסח מאורגן שקנו רק מצות שחייבות בהפרשת *חלה*), יהיה מותר להפריש ביו\"ט פסח כדי לקיים את המצוה דאורייתא של אכילת מצה. בדומה לזה, בלילה הראשון של סוכות, שיש חובה דאורייתא לאכול כזית לחם בסוכה, אם שכחת להפריש *חלה* ואין דרך אחרת להשיג לחם, מותר להפריש. הוא מוסיף שכאשר מפרישים בא\"י ביו\"ט, מוטב לקרוא שם לחלק שמפרישים רק במחשבה ולא בדיבור ובלי ברכה (אבל עדיין צריך לעשות את מעשה ההפרשה). בהערה (נח) הוא מסביר שהנ\"ל נכון רק בא\"י, אבל בחו\"ל יש להשאיר מעט מכל מצה או לחם.\n\n2) חלת לחם (סימן י, ז) מציע אפשרות אחרת, אבל כדי להבין אותה כראוי, תחילה עלינו ללמוד שתי הלכות חשובות.\n\nא. ה**ביאור הלכה** (סימן שמג) (19) מביא שהרשב\"א (על פי הבנת הר\"ן בדבריו) פסק שמותר לילד לעבור על איסור דרבנן אם הדבר נעשה בשבילו. לכן, אם שכחת להביא סידור לבית הכנסת ואין שם עירוב, מותר לקטן להביא סידור לעצמו, ומותר לך לקרוא בו יחד עם הילד.\n\nב. ה**רמב\"ם** (תרומות פ\"ד, ה) פסק שאם קטן שהגיע לגיל בו השבועות והנדרים שלו חלים, והוא הפריש תרומה, התרומה תקפה. השו\"ע ב**יו\"ד סימן רלג** פסק שנדרים של בן בגיל 12 ובת בגיל 11 שמבינים למי הם נודרים, הם נדרים תקפים. לפי זה, השו\"ע ב**סימן שלא, לג** פסק שתרומה שהפריש קטן כזה מחייבת.[15]\n\nעל פי 2 ההלכות הללו, **חלת לחם** (סימן י, ז) (20) הציע שעדיף לתת את המצה כמתנה לילד (בן בגיל 12 או בת בגיל 11) ושהם יפרישו עבור עצמם. הואיל והפרשתם תקפה, יהיה מותר גם לכולם ליהנות מהמצה. \n\n3) **רשז\"א** בהליכות שלמה (פ\"ט, א) (21), מציע שמיד לפני שמתחיל פסח, רב הקהילה יפריש *חלה* ויהיה בדעתו להפריש עבור כל אחד מבני הקהילה ששכח לעשות זאת בעצמו. למעשה, הרב בויאר מבני ברק מפריש *חלה* בכל ערב שבת 40 דק' לפני השקיעה בשביל כל היהודים בעולם.[16] הפרשה זו מועילה בגלל שזו זכות עבור מי ששכח להפריש, והכלל הוא ש\"זכין לאדם שלא בפניו\". ואכן, רשז\"א עצמו עשה כן בשערי חסד.[17] בהערה הוא מסביר שהסיבה שיש לעשות כן זמן קצר לפני יו\"ט הוא שאם הרב יפריש מוקדם יותר וחבר הקהילה ייזכר וירצה להפריש מאוחר יותר ביום, הפרשת הרב כבר איננה זכות לאותו אדם, מפני שהוא מעדיף לצאת ולברך בעצמו. ועוד, **חקת הפסח** (פכ\"ו, סקי\"ג) ממשיך וטוען שאם הרב עושה את ההפרשה בבוקר, יתכן שהוא יגרום לאלו שיברכו מאוחר יותר ביום לברך ברכה לבטלה.\n\nאולם, יש קושי משמעותי בהצעה של רשז\"א: למדנו לעיל שאסור להפריש ממקום אחד על מקום אחר בא\"י, ואפילו בחו\"ל אין להפריש בעיסה אחת על עיסה אחרת. אם כן, כיצד הוא היה יכול להפריש על אחרים?\n\n**מנחת יצחק** (ח\"ד, נט) (22) ביאר שהדבר עדיין יכול להיות מותר מפני שבדיעבד ניתן להפריש מעיסה אחת על עיסה אחרת על פי מה שלמדנו לעיל שמותר ל'חבר' לעבור על איסור קל כדי להציל אחר מאיסור חמור יותר. למרות שלמדנו שתוספות מתירים רק אם ה'חבר' הוא הגורם לכך שהאחר עובר על האיסור החמור (וכאן רב הקהילה אינו הגורם לכך שאחרים אינם מפרישים), יש 2 פתרונות אפשריים מדוע זה יהיה מותר. ראשית, תוספות בתירוץ השני כתבו שמותר ל'חבר' לעבור על איסור קל אפילו אם הוא לא הגורם שהאחר אוכל טבל, וכך אנו פוסקים למעשה, כפי שכתב ה**משנ\"ב** סימן שו סקנ\"ו. שנית, אפילו לפי התירוץ הראשון של תוספות, תוספות מסכימים שמותר ל'חבר' לעבור על איסור קל בשביל הציבור אפילו אם הוא לא הגורם שהם עוברים את האיסור. אם כן, רשז\"א סבר שעדיף לעבור על איסור קל להפריש ממקום על מקום אחר כדי שיהיה באפשרות אנשים ששכחו להפריש לאכול מצה. כך גם פסק **משפטי ארץ** (פ\"ה, כא).\n\nSource Notes\n\n[15]:  מאידך, הגר\"א (שלא, עח) פסק בניגוד לשו\"ע שהפרשת קטן לעולם איננה תקפה.\n\n[16]:  ראה https://www.jdn.co.il/j_world/2221901\n\n[17]:  בהערה 13 שם מובא בשם רשז\"א שאמר שכמעט כל שנה מישהו בקהילה שלו שוכח, והוא שמח שביכולתו לעזור לאחרים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":61,"xmlIndex":64,"text":"הנ\"ל שייך רק בחו\"ל, שם מותר להשאיר מהמצה ולהפריש אחרי יו\"ט. מה עושים בא\"י? יש 3 פתרונות אפשריים.","spans":[{"text":"הנ\"ל שייך רק בחו\"ל, שם מותר להשאיר מהמצה ולהפריש אחרי יו\"ט. מה עושים בא\"י? יש 3 פתרונות אפשריים."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"list","paragraph":62,"xmlIndex":65,"text":"שש\"כ (פרק יא, טז) (18), בשם רשז\"א, פסק שבא\"י אם אין דרך אחרת להשיג מצה כשרה (כגון, נופש פסח מאורגן שקנו רק מצות שחייבות בהפרשת חלה), יהיה מותר להפריש ביו\"ט פסח כדי לקיים את המצוה דאורייתא של אכילת מצה. בדומה לזה, בלילה הראשון של סוכות, שיש חובה דאורייתא לאכול כזית לחם בסוכה, אם שכחת להפריש חלה ואין דרך אחרת להשיג לחם, מותר להפריש. הוא מוסיף שכאשר מפרישים בא\"י ביו\"ט, מוטב לקרוא שם לחלק שמפרישים רק במחשבה ולא בדיבור ובלי ברכה (אבל עדיין צריך לעשות את מעשה ההפרשה). בהערה (נח) הוא מסביר שהנ\"ל נכון רק בא\"י, אבל בחו\"ל יש להשאיר מעט מכל מצה או לחם.","spans":[{"text":"שש\"כ","bold":true},{"text":" (פרק יא, טז) (18), בשם "},{"text":"רשז\"א","bold":true},{"text":", פסק שבא\"י אם אין דרך אחרת להשיג מצה כשרה (כגון, נופש פסח מאורגן שקנו רק מצות שחייבות בהפרשת "},{"text":"חלה","italic":true},{"text":"), יהיה מותר להפריש ביו\"ט פסח כדי לקיים את המצוה דאורייתא של אכילת מצה. בדומה לזה, בלילה הראשון של סוכות, שיש חובה דאורייתא לאכול כזית לחם בסוכה, אם שכחת להפריש "},{"text":"חלה","italic":true},{"text":" ואין דרך אחרת להשיג לחם, מותר להפריש. הוא מוסיף שכאשר מפרישים בא\"י ביו\"ט, מוטב לקרוא שם לחלק שמפרישים רק במחשבה ולא בדיבור ובלי ברכה (אבל עדיין צריך לעשות את מעשה ההפרשה). בהערה (נח) הוא מסביר שהנ\"ל נכון רק בא\"י, אבל בחו\"ל יש להשאיר מעט מכל מצה או לחם."}],"marker":"1)","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":63,"xmlIndex":66,"text":"חלת לחם (סימן י, ז) מציע אפשרות אחרת, אבל כדי להבין אותה כראוי, תחילה עלינו ללמוד שתי הלכות חשובות.","spans":[{"text":"חלת לחם (סימן י, ז) מציע אפשרות אחרת, אבל כדי להבין אותה כראוי, תחילה עלינו ללמוד שתי הלכות חשובות."}],"marker":"2)","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":64,"xmlIndex":67,"text":"הביאור הלכה (סימן שמג) (19) מביא שהרשב\"א (על פי הבנת הר\"ן בדבריו) פסק שמותר לילד לעבור על איסור דרבנן אם הדבר נעשה בשבילו. לכן, אם שכחת להביא סידור לבית הכנסת ואין שם עירוב, מותר לקטן להביא סידור לעצמו, ומותר לך לקרוא בו יחד עם הילד.","spans":[{"text":"ה"},{"text":"ביאור הלכה","bold":true},{"text":" (סימן שמג) (19) מביא שהרשב\"א (על פי הבנת הר\"ן בדבריו) פסק שמותר לילד לעבור על איסור דרבנן אם הדבר נעשה בשבילו. לכן, אם שכחת להביא סידור לבית הכנסת ואין שם עירוב, מותר לקטן להביא סידור לעצמו, ומותר לך לקרוא בו יחד עם הילד."}],"marker":"א.","level":0,"indent":72,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":65,"xmlIndex":68,"text":"הרמב\"ם (תרומות פ\"ד, ה) פסק שאם קטן שהגיע לגיל בו השבועות והנדרים שלו חלים, והוא הפריש תרומה, התרומה תקפה. השו\"ע ביו\"ד סימן רלג פסק שנדרים של בן בגיל 12 ובת בגיל 11 שמבינים למי הם נודרים, הם נדרים תקפים. לפי זה, השו\"ע בסימן שלא, לג פסק שתרומה שהפריש קטן כזה מחייבת.[15]","spans":[{"text":"ה"},{"text":"רמב\"ם","bold":true},{"text":" (תרומות פ\"ד, ה) פסק שאם קטן שהגיע לגיל בו השבועות והנדרים שלו חלים, והוא הפריש תרומה, התרומה תקפה. השו\"ע ב"},{"text":"יו\"ד סימן רלג","bold":true},{"text":" פסק שנדרים של בן בגיל 12 ובת בגיל 11 שמבינים למי הם נודרים, הם נדרים תקפים. לפי זה, השו\"ע ב"},{"text":"סימן שלא, לג","bold":true},{"text":" פסק שתרומה שהפריש קטן כזה מחייבת."},{"text":"[15]","footnote":15}],"marker":"ב.","level":0,"indent":72,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[15],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":66,"xmlIndex":69,"text":"על פי 2 ההלכות הללו, חלת לחם (סימן י, ז) (20) הציע שעדיף לתת את המצה כמתנה לילד (בן בגיל 12 או בת בגיל 11) ושהם יפרישו עבור עצמם. הואיל והפרשתם תקפה, יהיה מותר גם לכולם ליהנות מהמצה. ","spans":[{"text":"על פי 2 ההלכות הללו, "},{"text":"חלת לחם","bold":true},{"text":" (סימן י, ז) (20) הציע שעדיף לתת את המצה כמתנה לילד (בן בגיל 12 או בת בגיל 11) ושהם יפרישו עבור עצמם. הואיל והפרשתם תקפה, יהיה מותר גם לכולם ליהנות מהמצה. "}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"list","paragraph":67,"xmlIndex":70,"text":"רשז\"א בהליכות שלמה (פ\"ט, א) (21), מציע שמיד לפני שמתחיל פסח, רב הקהילה יפריש חלה ויהיה בדעתו להפריש עבור כל אחד מבני הקהילה ששכח לעשות זאת בעצמו. למעשה, הרב בויאר מבני ברק מפריש חלה בכל ערב שבת 40 דק' לפני השקיעה בשביל כל היהודים בעולם.[16] הפרשה זו מועילה בגלל שזו זכות עבור מי ששכח להפריש, והכלל הוא ש\"זכין לאדם שלא בפניו\". ואכן, רשז\"א עצמו עשה כן בשערי חסד.[17] בהערה הוא מסביר שהסיבה שיש לעשות כן זמן קצר לפני יו\"ט הוא שאם הרב יפריש מוקדם יותר וחבר הקהילה ייזכר וירצה להפריש מאוחר יותר ביום, הפרשת הרב כבר איננה זכות לאותו אדם, מפני שהוא מעדיף לצאת ולברך בעצמו. ועוד, חקת הפסח (פכ\"ו, סקי\"ג) ממשיך וטוען שאם הרב עושה את ההפרשה בבוקר, יתכן שהוא יגרום לאלו שיברכו מאוחר יותר ביום לברך ברכה לבטלה.","spans":[{"text":"רשז\"א","bold":true},{"text":" בהליכות שלמה (פ\"ט, א) (21), מציע שמיד לפני שמתחיל פסח, רב הקהילה יפריש "},{"text":"חלה","italic":true},{"text":" ויהיה בדעתו להפריש עבור כל אחד מבני הקהילה ששכח לעשות זאת בעצמו. למעשה, הרב בויאר מבני ברק מפריש "},{"text":"חלה","italic":true},{"text":" בכל ערב שבת 40 דק' לפני השקיעה בשביל כל היהודים בעולם."},{"text":"[16]","footnote":16},{"text":" הפרשה זו מועילה בגלל שזו זכות עבור מי ששכח להפריש, והכלל הוא ש\"זכין לאדם שלא בפניו\". ואכן, רשז\"א עצמו עשה כן בשערי חסד."},{"text":"[17]","footnote":17},{"text":" בהערה הוא מסביר שהסיבה שיש לעשות כן זמן קצר לפני יו\"ט הוא שאם הרב יפריש מוקדם יותר וחבר הקהילה ייזכר וירצה להפריש מאוחר יותר ביום, הפרשת הרב כבר איננה זכות לאותו אדם, מפני שהוא מעדיף לצאת ולברך בעצמו. ועוד, "},{"text":"חקת הפסח","bold":true},{"text":" (פכ\"ו, סקי\"ג) ממשיך וטוען שאם הרב עושה את ההפרשה בבוקר, יתכן שהוא יגרום לאלו שיברכו מאוחר יותר ביום לברך ברכה לבטלה."}],"marker":"3)","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[16,17],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":68,"xmlIndex":71,"text":"אולם, יש קושי משמעותי בהצעה של רשז\"א: למדנו לעיל שאסור להפריש ממקום אחד על מקום אחר בא\"י, ואפילו בחו\"ל אין להפריש בעיסה אחת על עיסה אחרת. אם כן, כיצד הוא היה יכול להפריש על אחרים?","spans":[{"text":"אולם, יש קושי משמעותי בהצעה של רשז\"א: למדנו לעיל שאסור להפריש ממקום אחד על מקום אחר בא\"י, ואפילו בחו\"ל אין להפריש בעיסה אחת על עיסה אחרת. אם כן, כיצד הוא היה יכול להפריש על אחרים?"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":69,"xmlIndex":72,"text":"מנחת יצחק (ח\"ד, נט) (22) ביאר שהדבר עדיין יכול להיות מותר מפני שבדיעבד ניתן להפריש מעיסה אחת על עיסה אחרת על פי מה שלמדנו לעיל שמותר ל'חבר' לעבור על איסור קל כדי להציל אחר מאיסור חמור יותר. למרות שלמדנו שתוספות מתירים רק אם ה'חבר' הוא הגורם לכך שהאחר עובר על האיסור החמור (וכאן רב הקהילה אינו הגורם לכך שאחרים אינם מפרישים), יש 2 פתרונות אפשריים מדוע זה יהיה מותר. ראשית, תוספות בתירוץ השני כתבו שמותר ל'חבר' לעבור על איסור קל אפילו אם הוא לא הגורם שהאחר אוכל טבל, וכך אנו פוסקים למעשה, כפי שכתב המשנ\"ב סימן שו סקנ\"ו. שנית, אפילו לפי התירוץ הראשון של תוספות, תוספות מסכימים שמותר ל'חבר' לעבור על איסור קל בשביל הציבור אפילו אם הוא לא הגורם שהם עוברים את האיסור. אם כן, רשז\"א סבר שעדיף לעבור על איסור קל להפריש ממקום על מקום אחר כדי שיהיה באפשרות אנשים ששכחו להפריש לאכול מצה. כך גם פסק משפטי ארץ (פ\"ה, כא).","spans":[{"text":"מנחת יצחק","bold":true},{"text":" (ח\"ד, נט) (22) ביאר שהדבר עדיין יכול להיות מותר מפני שבדיעבד ניתן להפריש מעיסה אחת על עיסה אחרת על פי מה שלמדנו לעיל שמותר ל'חבר' לעבור על איסור קל כדי להציל אחר מאיסור חמור יותר. למרות שלמדנו שתוספות מתירים רק אם ה'חבר' הוא הגורם לכך שהאחר עובר על האיסור החמור (וכאן רב הקהילה אינו הגורם לכך שאחרים אינם מפרישים), יש 2 פתרונות אפשריים מדוע זה יהיה מותר. ראשית, תוספות בתירוץ השני כתבו שמותר ל'חבר' לעבור על איסור קל אפילו אם הוא לא הגורם שהאחר אוכל טבל, וכך אנו פוסקים למעשה, כפי שכתב ה"},{"text":"משנ\"ב ","bold":true},{"text":"סימן שו סקנ\"ו. שנית, אפילו לפי התירוץ הראשון של תוספות, תוספות מסכימים שמותר ל'חבר' לעבור על איסור קל בשביל הציבור אפילו אם הוא לא הגורם שהם עוברים את האיסור. אם כן, רשז\"א סבר שעדיף לעבור על איסור קל להפריש ממקום על מקום אחר כדי שיהיה באפשרות אנשים ששכחו להפריש לאכול מצה. כך גם פסק "},{"text":"משפטי ארץ","bold":true},{"text":" (פ\"ה, כא)."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":15,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" מאידך, הגר\"א (שלא, עח) פסק בניגוד לשו\"ע שהפרשת קטן לעולם איננה תקפה.","spans":[{"text":" מאידך, הגר\"א (שלא, עח) פסק בניגוד לשו\"ע שהפרשת קטן לעולם איננה תקפה."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":16,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" ראה https://www.jdn.co.il/j_world/2221901","spans":[{"text":" ראה https://www.jdn.co.il/j_world/2221901"}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":17,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" בהערה 13 שם מובא בשם רשז\"א שאמר שכמעט כל שנה מישהו בקהילה שלו שוכח, והוא שמח שביכולתו לעזור לאחרים.","spans":[{"text":" בהערה 13 שם מובא בשם רשז\"א שאמר שכמעט כל שנה מישהו בקהילה שלו שוכח, והוא שמח שביכולתו לעזור לאחרים."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[18,19,20,21,22],"approved_hash":"f1b9a2dc149cf52e6627ec9a5aa5d980ced1299d9e69f2c6e5be19d727685ca1"},{"chunk_code":"HC1-C10","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"העברת מצות בין ארץ ישראל לחוץ לארץ","chunk_summary":"לפי הבנת הכסף משנה ברמב״ם, מעמד העיסה נקבע במקום לישתה; החשב האפוד בשם הב״ח מציע הבנה מקילה יותר לגבי מצות שהועברו בין ארצות.","content_markdown":"<u>לשלוח מצה לחו\"ל</u>\n\nלמדנו לעיל שאם אדם שכח להפריש *חלה* בחו\"ל הוא רשאי להשאיר קצת מהלחם או החלה שהוא משתמש בהם בשבת או יו\"ט[18] ואחר כך להפריש ממה שנשאר, אבל בא\"י הדבר אסור. ה**רמב\"ם** (ביכורים פ\"ה, ו) פסק, כפי שהתבאר בכסף משנה ומשנה למלך, שחיוב **התורה** על הפרשת *חלה* חל רק בקמח שנעשה לבצק בא\"י, לא משנה מה מקור החיטה.[19] לעומת זאת, קמח שיוצר בא\"י והובא לחו\"ל ונעשה לבצק חייב ב*חלה* רק **מדרבנן**, כמו כל *חלה* בחו\"ל. פעמים רבות מאפיות של מצות שולחות מצות מישראל לחו\"ל ולהיפך. לאור דברי הרמב\"ם, מה יש לעשות אם אפית מצות עם קבוצה של אנשים במאפיה ושכחתם להפריש *חלה*?\n\nאם המצות נעשו בחו\"ל ונשלחו לא\"י, צריך להשאיר מכל מצה ואחרי יו\"ט, בחול המועד, לתת את כל השאריות בכלי אחד ולהפריש מהכלי, כפי שהוזכר לעיל בשם המשנ\"ב. אולם, אם המצה נעשתה בא\"י, נראה שיהיה אסור לאכול ממנה בלי הפרשה, אפילו אם כעת היא נמצאת בחו\"ל, ויש לעשות מה שהוצע בקטע הקודם. אף על פי כן, **חשב האפוד** (ח\"ב, מג) (23), בשם הב\"ח, מבין את הרמב\"ם אחרת ופוסק שלחם שהוצא מא\"י לחו\"ל חייב ב*חלה* רק מדרבנן. לכן, יש לאכול מהמצה ולהשאיר כמות קטנה מכל חתיכה כדי להפריש לאחר מכן. אולם, **משפטי ארץ** (פ\"ט, א) פסק כמו הבנת הכסף משנה והמשנה למלך ברמב\"ם לעיל, ואם כן יהיה אסור להפריש.\n\nSource Notes\n\n[18]:  יש לציין שהשו\"ע בסימן תקו, ג פסק שאם העיסה הוכנה ביו\"ט מותר להפריש. אסור להפריש ביו\"ט רק אם העיסה הוכנה לפני יו\"ט.\n\n[19]:  בימינו, רוב הקמח בא\"י מקורו בחו\"ל.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":70,"xmlIndex":73,"text":"לשלוח מצה לחו\"ל","spans":[{"text":"לשלוח מצה לחו\"ל","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":71,"xmlIndex":74,"text":"למדנו לעיל שאם אדם שכח להפריש חלה בחו\"ל הוא רשאי להשאיר קצת מהלחם או החלה שהוא משתמש בהם בשבת או יו\"ט[18] ואחר כך להפריש ממה שנשאר, אבל בא\"י הדבר אסור. הרמב\"ם (ביכורים פ\"ה, ו) פסק, כפי שהתבאר בכסף משנה ומשנה למלך, שחיוב התורה על הפרשת חלה חל רק בקמח שנעשה לבצק בא\"י, לא משנה מה מקור החיטה.[19] לעומת זאת, קמח שיוצר בא\"י והובא לחו\"ל ונעשה לבצק חייב בחלה רק מדרבנן, כמו כל חלה בחו\"ל. פעמים רבות מאפיות של מצות שולחות מצות מישראל לחו\"ל ולהיפך. לאור דברי הרמב\"ם, מה יש לעשות אם אפית מצות עם קבוצה של אנשים במאפיה ושכחתם להפריש חלה?","spans":[{"text":"למדנו לעיל שאם אדם שכח להפריש "},{"text":"חלה","italic":true},{"text":" בחו\"ל הוא רשאי להשאיר קצת מהלחם או החלה שהוא משתמש בהם בשבת או יו\"ט"},{"text":"[18]","footnote":18},{"text":" ואחר כך להפריש ממה שנשאר, אבל בא\"י הדבר אסור. ה"},{"text":"רמב\"ם","bold":true},{"text":" (ביכורים פ\"ה, ו) פסק, כפי שהתבאר בכסף משנה ומשנה למלך, שחיוב "},{"text":"התורה","bold":true},{"text":" על הפרשת "},{"text":"חלה","italic":true},{"text":" חל רק בקמח שנעשה לבצק בא\"י, לא משנה מה מקור החיטה."},{"text":"[19]","footnote":19},{"text":" לעומת זאת, קמח שיוצר בא\"י והובא לחו\"ל ונעשה לבצק חייב ב"},{"text":"חלה","italic":true},{"text":" רק "},{"text":"מדרבנן","bold":true},{"text":", כמו כל "},{"text":"חלה","italic":true},{"text":" בחו\"ל. פעמים רבות מאפיות של מצות שולחות מצות מישראל לחו\"ל ולהיפך. לאור דברי הרמב\"ם, מה יש לעשות אם אפית מצות עם קבוצה של אנשים במאפיה ושכחתם להפריש "},{"text":"חלה","italic":true},{"text":"?"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[18,19],"defaultTabWidth":36},{"kind":"paragraph","paragraph":72,"xmlIndex":75,"text":"אם המצות נעשו בחו\"ל ונשלחו לא\"י, צריך להשאיר מכל מצה ואחרי יו\"ט, בחול המועד, לתת את כל השאריות בכלי אחד ולהפריש מהכלי, כפי שהוזכר לעיל בשם המשנ\"ב. אולם, אם המצה נעשתה בא\"י, נראה שיהיה אסור לאכול ממנה בלי הפרשה, אפילו אם כעת היא נמצאת בחו\"ל, ויש לעשות מה שהוצע בקטע הקודם. אף על פי כן, חשב האפוד (ח\"ב, מג) (23), בשם הב\"ח, מבין את הרמב\"ם אחרת ופוסק שלחם שהוצא מא\"י לחו\"ל חייב בחלה רק מדרבנן. לכן, יש לאכול מהמצה ולהשאיר כמות קטנה מכל חתיכה כדי להפריש לאחר מכן. אולם, משפטי ארץ (פ\"ט, א) פסק כמו הבנת הכסף משנה והמשנה למלך ברמב\"ם לעיל, ואם כן יהיה אסור להפריש.","spans":[{"text":"אם המצות נעשו בחו\"ל ונשלחו לא\"י, צריך להשאיר מכל מצה ואחרי יו\"ט, בחול המועד, לתת את כל השאריות בכלי אחד ולהפריש מהכלי, כפי שהוזכר לעיל בשם המשנ\"ב. אולם, אם המצה נעשתה בא\"י, נראה שיהיה אסור לאכול ממנה בלי הפרשה, אפילו אם כעת היא נמצאת בחו\"ל, ויש לעשות מה שהוצע בקטע הקודם. אף על פי כן, "},{"text":"חשב האפוד","bold":true},{"text":" (ח\"ב, מג) (23), בשם הב\"ח, מבין את הרמב\"ם אחרת ופוסק שלחם שהוצא מא\"י לחו\"ל חייב ב"},{"text":"חלה","italic":true},{"text":" רק מדרבנן. לכן, יש לאכול מהמצה ולהשאיר כמות קטנה מכל חתיכה כדי להפריש לאחר מכן. אולם, "},{"text":"משפטי ארץ","bold":true},{"text":" (פ\"ט, א) פסק כמו הבנת הכסף משנה והמשנה למלך ברמב\"ם לעיל, ואם כן יהיה אסור להפריש."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":18,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" יש לציין שהשו\"ע בסימן תקו, ג פסק שאם העיסה הוכנה ביו\"ט מותר להפריש. אסור להפריש ביו\"ט רק אם העיסה הוכנה לפני יו\"ט.","spans":[{"text":" יש לציין שהשו\"ע בסימן תקו, ג פסק שאם העיסה הוכנה ביו\"ט מותר להפריש. אסור להפריש ביו\"ט רק אם העיסה הוכנה לפני יו\"ט."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":19,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" בימינו, רוב הקמח בא\"י מקורו בחו\"ל.","spans":[{"text":" בימינו, רוב הקמח בא\"י מקורו בחו\"ל."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[23],"approved_hash":"88bdf1e6c38bf09680af9a0a91ed528e9127aa84ff0257de6130eeab0ce26900"},{"chunk_code":"HC1-C11","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"ברכה על הפרשת חלה לאחר שכבר אכלו","chunk_summary":"מחלוקת אם מברכים כאשר מפרישים לאחר שבת או יום טוב בחוץ לארץ, לאחר שכבר אכלו מן הלחם או המצות.","content_markdown":"<u>ברכה בהפרשה אחרי האכילה</u>\n\nלמדנו לעיל שאם אדם שכח בחו\"ל להפריש *חלה* פני שבת ויו\"ט, הוא רשאי לאכול ולהשאיר מעט מהלחם ויפריש ממנו אחרי שבת או יו\"ט. **רשז\"א** שהובא בשש\"כ (פמ\"ב, הע' נז), פסק שאין לברך כאשר מפרישים אחרי שבת. הואיל והשאירו את הלחם בשבת בכוונה בשביל להפריש אחרי שבת, זה נחשב כאילו זה חל למפרע בשבת. לכן, אי אפשר לברך ברכה במוצאי שבת על ההפרשה שנחשב שכבר אירעה מוקדם יותר. אולם, **ערה\"ש** (או\"ח שכג, ג) ו**ר' חיים קנייבסקי** בדרך אמונה ביכורים פ\"ה (סקקכ\"א) פסקו שאדם צריך לברך כאשר הוא מפריש הואיל ובגמרא לא כתוב אחרת.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":73,"xmlIndex":76,"text":"ברכה בהפרשה אחרי האכילה","spans":[{"text":"ברכה בהפרשה אחרי האכילה","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":74,"xmlIndex":77,"text":"למדנו לעיל שאם אדם שכח בחו\"ל להפריש חלה פני שבת ויו\"ט, הוא רשאי לאכול ולהשאיר מעט מהלחם ויפריש ממנו אחרי שבת או יו\"ט. רשז\"א שהובא בשש\"כ (פמ\"ב, הע' נז), פסק שאין לברך כאשר מפרישים אחרי שבת. הואיל והשאירו את הלחם בשבת בכוונה בשביל להפריש אחרי שבת, זה נחשב כאילו זה חל למפרע בשבת. לכן, אי אפשר לברך ברכה במוצאי שבת על ההפרשה שנחשב שכבר אירעה מוקדם יותר. אולם, ערה\"ש (או\"ח שכג, ג) ור' חיים קנייבסקי בדרך אמונה ביכורים פ\"ה (סקקכ\"א) פסקו שאדם צריך לברך כאשר הוא מפריש הואיל ובגמרא לא כתוב אחרת.","spans":[{"text":"למדנו לעיל שאם אדם שכח בחו\"ל להפריש "},{"text":"חלה","italic":true},{"text":" פני שבת ויו\"ט, הוא רשאי לאכול ולהשאיר מעט מהלחם ויפריש ממנו אחרי שבת או יו\"ט. "},{"text":"רשז\"א","bold":true},{"text":" שהובא בשש\"כ (פמ\"ב, הע' נז), פסק שאין לברך כאשר מפרישים אחרי שבת. הואיל והשאירו את הלחם בשבת בכוונה בשביל להפריש אחרי שבת, זה נחשב כאילו זה חל למפרע בשבת. לכן, אי אפשר לברך ברכה במוצאי שבת על ההפרשה שנחשב שכבר אירעה מוקדם יותר. אולם, "},{"text":"ערה\"ש","bold":true},{"text":" (או\"ח שכג, ג) ו"},{"text":"ר' חיים קנייבסקי","bold":true},{"text":" בדרך אמונה ביכורים פ\"ה (סקקכ\"א) פסקו שאדם צריך לברך כאשר הוא מפריש הואיל ובגמרא לא כתוב אחרת."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"82d8ae222245eed7eb9fc411192137e60cc1760ec75ab9f05896079f18576bcf"},{"chunk_code":"HC1-D1","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ד","chunk_title":"כמה חלה מפרישים — הקדמה","chunk_summary":"הקדמה לשיעורים המקוריים של אחד מעשרים וארבעה בעיסת בעל הבית ואחד מארבעים ושמונה בעיסת נחתום, ולשינוי במנהג ההפרשה בימינו.","content_markdown":"### ד. *כמה מפרישים?*\n\nאחרי שלמדנו את ההבדלים הבסיסיים בין הפרשת *חלה* בא\"י וחו\"ל, בחלק זה נלמד כמה בצק צריך להפריש. אנו נלמד שבתחילה מי שהפריש בצק בא\"י בבית היה צריך להפריש 1/24 מהבצק, ואילו אופה היה צריך להפריש רק 1/48 מהעיסה. אולם, בימינו הכמות שמפרישים השתנתה, כפי שיבואר להלן.","content_document":{"version":1,"language":"he","blocks":[{"kind":"heading","paragraph":75,"xmlIndex":79,"text":"כמה מפרישים?","spans":[{"text":"כמה מפרישים?","italic":true,"color":"#2F5496"}],"marker":"ד.","level":0,"indent":72,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"rightIndent":43.2,"hanging":18,"tabStops":[{"position":150.45,"alignment":"left","leader":"none"},{"position":234,"alignment":"center","leader":"none"},{"position":279,"alignment":"left","leader":"none"}]},{"kind":"paragraph","paragraph":76,"xmlIndex":81,"text":"אחרי שלמדנו את ההבדלים הבסיסיים בין הפרשת חלה בא\"י וחו\"ל, בחלק זה נלמד כמה בצק צריך להפריש. אנו נלמד שבתחילה מי שהפריש בצק בא\"י בבית היה צריך להפריש 1/24 מהבצק, ואילו אופה היה צריך להפריש רק 1/48 מהעיסה. אולם, בימינו הכמות שמפרישים השתנתה, כפי שיבואר להלן.","spans":[{"text":"אחרי שלמדנו את ההבדלים הבסיסיים בין הפרשת "},{"text":"חלה","italic":true},{"text":" בא\"י וחו\"ל, בחלק זה נלמד כמה בצק צריך להפריש. אנו נלמד שבתחילה מי שהפריש בצק בא\"י בבית היה צריך להפריש 1/24 מהבצק, ואילו אופה היה צריך להפריש רק 1/48 מהעיסה. אולם, בימינו הכמות שמפרישים השתנתה, כפי שיבואר להלן."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"0cbb225b8a2cf0185b0515b351c8d82ffaf8712c7ec2c0efede4f222710a39ed"},{"chunk_code":"HC1-D2","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ד","chunk_title":"שיטת הרמב״ם: מצווה אחת ושיעור כלשהו מן התורה","chunk_summary":"לדעת הרמב״ם, ההפרשה והנתינה הן מצווה אחת, ומן התורה די בכלשהו; חכמים קבעו שיעור נתינה מכובד של אחד מעשרים וארבעה או אחד מארבעים ושמונה.","content_markdown":"כדי להבין מדוע בתחילה היה צריך כמויות של 1/24 ו1/48 להפרשת *חלה*, תחילה עלינו להבין טוב יותר את המבנה והצורה של מצות הפרשת *חלה*. ה**רמב\"ם** (עשה, קלג) (24) פסק שיש מצוה אחת של הפרשת *חלה* מהעיסה ונתינתה לכהן. בהלכות ביכורים (פ\"ה, א), ה**רמב\"ם** ביאר שמדאורייתא, אדם יכול לקיים את המצווה על ידי הפרשה ונתינת אפילו כמות כלשהי. אולם, הפסוק \"תתן לו\", מלמד שראוי להפריש כמות שראויה לנתינה, שהיא 1/24 מעיסה ביתית ו1/48 מעיסת אופה.\n\nכמויות אלו של 1/24 ו1/48 מקורן מה**משנה חלה** (פ\"ב, ז)  (25), שמלמדת שמי שאופה לחם בביתו צריך להפריש 1/24 מהעיסה, אפילו אם הוא אופה בשביל הרבה אורחים, ואילו אופה (נחתום) צריך להפריש רק 1/48 מהעיסה. ה**רמב\"ם** בפירוש המשניות ביאר עוד שכאשר אופים בבית, צריך לתת כמות גדולה יותר של 1/24 כדי לקיים את לשון \"נתינה\" של הפסוק, שמשמע כמות מכובדת. לעומת זאת, אופה במאפיה, שמכין כמויות גדולות של בצק, נותן חלק קטן יותר של 1/48**,** שבדרך כלל יוצא אותה כמות בצק כמו 1/24 מעיסה ביתית. המשנה מוסיפה שאם העיסה נטמאה, מפרישים רק 1/48.\n\nמדברי הרמב\"ם נראה בבירור, הואיל וההפרשה והנתינה הן מצוה אחת, ומדאורייתא מקיימים את החובה אפילו בשיעור כלשהו, מה שהוא כתב שצריך לתת 1/24 או 1/48 כדי לקיים את לשון \"נתינה\" של הפסוק, בוודאי הכוונה היא רק לאסמכתא. ואכן, ה**מזרחי** על רש\"י (במדבר פט\"ו, כא) כתב בפירוש שהפסוק הוא רק אסמכתא.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":77,"xmlIndex":82,"text":"כדי להבין מדוע בתחילה היה צריך כמויות של 1/24 ו1/48 להפרשת חלה, תחילה עלינו להבין טוב יותר את המבנה והצורה של מצות הפרשת חלה. הרמב\"ם (עשה, קלג) (24) פסק שיש מצוה אחת של הפרשת חלה מהעיסה ונתינתה לכהן. בהלכות ביכורים (פ\"ה, א), הרמב\"ם ביאר שמדאורייתא, אדם יכול לקיים את המצווה על ידי הפרשה ונתינת אפילו כמות כלשהי. אולם, הפסוק \"תתן לו\", מלמד שראוי להפריש כמות שראויה לנתינה, שהיא 1/24 מעיסה ביתית ו1/48 מעיסת אופה.","spans":[{"text":"כדי להבין מדוע בתחילה היה צריך כמויות של 1/24 ו1/48 להפרשת "},{"text":"חלה","italic":true},{"text":", תחילה עלינו להבין טוב יותר את המבנה והצורה של מצות הפרשת "},{"text":"חלה","italic":true},{"text":". ה"},{"text":"רמב\"ם","bold":true},{"text":" (עשה, קלג) (24) פסק שיש מצוה אחת של הפרשת "},{"text":"חלה ","italic":true},{"text":"מהעיסה ונתינתה לכהן. בהלכות ביכורים (פ\"ה, א), ה"},{"text":"רמב\"ם","bold":true},{"text":" ביאר שמדאורייתא, אדם יכול לקיים את המצווה על ידי הפרשה ונתינת אפילו כמות כלשהי. אולם, הפסוק \"תתן לו\", מלמד שראוי להפריש כמות שראויה לנתינה, שהיא 1/24 מעיסה ביתית ו1/48 מעיסת אופה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":78,"xmlIndex":83,"text":"כמויות אלו של 1/24 ו1/48 מקורן מהמשנה חלה (פ\"ב, ז)  (25), שמלמדת שמי שאופה לחם בביתו צריך להפריש 1/24 מהעיסה, אפילו אם הוא אופה בשביל הרבה אורחים, ואילו אופה (נחתום) צריך להפריש רק 1/48 מהעיסה. הרמב\"ם בפירוש המשניות ביאר עוד שכאשר אופים בבית, צריך לתת כמות גדולה יותר של 1/24 כדי לקיים את לשון \"נתינה\" של הפסוק, שמשמע כמות מכובדת. לעומת זאת, אופה במאפיה, שמכין כמויות גדולות של בצק, נותן חלק קטן יותר של 1/48, שבדרך כלל יוצא אותה כמות בצק כמו 1/24 מעיסה ביתית. המשנה מוסיפה שאם העיסה נטמאה, מפרישים רק 1/48.","spans":[{"text":"כמויות אלו של 1/24 ו1/48 מקורן מה"},{"text":"משנה חלה","bold":true},{"text":" (פ\"ב, ז)  (25), שמלמדת שמי שאופה לחם בביתו צריך להפריש 1/24 מהעיסה, אפילו אם הוא אופה בשביל הרבה אורחים, ואילו אופה (נחתום) צריך להפריש רק 1/48 מהעיסה. ה"},{"text":"רמב\"ם","bold":true},{"text":" בפירוש המשניות ביאר עוד שכאשר אופים בבית, צריך לתת כמות גדולה יותר של 1/24 כדי לקיים את לשון \"נתינה\" של הפסוק, שמשמע כמות מכובדת. לעומת זאת, אופה במאפיה, שמכין כמויות גדולות של בצק, נותן חלק קטן יותר של 1/48"},{"text":", ","bold":true},{"text":"שבדרך כלל יוצא אותה כמות בצק כמו 1/24 מעיסה ביתית. המשנה מוסיפה שאם העיסה נטמאה, מפרישים רק 1/48."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":79,"xmlIndex":84,"text":"מדברי הרמב\"ם נראה בבירור, הואיל וההפרשה והנתינה הן מצוה אחת, ומדאורייתא מקיימים את החובה אפילו בשיעור כלשהו, מה שהוא כתב שצריך לתת 1/24 או 1/48 כדי לקיים את לשון \"נתינה\" של הפסוק, בוודאי הכוונה היא רק לאסמכתא. ואכן, המזרחי על רש\"י (במדבר פט\"ו, כא) כתב בפירוש שהפסוק הוא רק אסמכתא.","spans":[{"text":"מדברי הרמב\"ם נראה בבירור, הואיל וההפרשה והנתינה הן מצוה אחת, ומדאורייתא מקיימים את החובה אפילו בשיעור כלשהו, מה שהוא כתב שצריך לתת 1/24 או 1/48 כדי לקיים את לשון \"נתינה\" של הפסוק, בוודאי הכוונה היא רק לאסמכתא. ואכן, ה"},{"text":"מזרחי","bold":true},{"text":" על רש\"י (במדבר פט\"ו, כא) כתב בפירוש שהפסוק הוא רק אסמכתא."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[24,25],"approved_hash":"725479162e48933034dbf817fdba2c3f0905ca65e7c9525d205f56e49105cf7e"},{"chunk_code":"HC1-D3","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ד","chunk_title":"הרמב״ן והנודע ביהודה — הפרשה לעומת נתינה","chunk_summary":"הרמב״ן מונה את ההפרשה ואת הנתינה כשתי מצוות; הנודע ביהודה מבאר את שיעור הנתינה מן התורה ביחס לכמות העיסה המינימלית המחייבת בחלה.","content_markdown":"ה**רמב\"ן** (השגות, שורש יב) (26) חולק על הרמב\"ם ופוסק שהפרשת *חלה* מורכבת משתי מצוות נפרדות: 1) הפרשת בצק כ*חלה*, ובכך התרת הבצק שנשאר באכילה (והוא כבר לא טבל). 2) נתינת הבצק לכהן.\n\nה**נודע ביהודה** (יו\"ד תנינא, רא) (27) כתב שאפילו נתינת 1/24 או 1/48 יכולה להיות חלק ממצווה דאורייתא. הוא מסביר שהואיל ויש שני חלקים למצות הפרשת *חלה*, הפרשה ונתינה, כאשר אדם מפריש אפילו כמות כלשהי, הוא מקיים מדאורייתא את מצות הפרשה. אולם, כאשר הוא נותן את הבצק לכהן, מציע הנודע ביהודה שהכמות שצריך להפריש היא תמיד 1/24 משיעור הקמח המינימלי שחייב בהפרשת *חלה* (עשירית האיפה, שלהלן נלמד שהיינו בין 1.2-2.2 ק\"ג). אם אדם מכין רק את כמות המינימום של בצק שחייב בהפרשת *חלה*, אזי יש מצוה דאורייתא לתת כמות שנחשבת לנתינה משמעותית, דהיינו, 1/24 מעיסה ביתית ו1/48 מעיסה של אופה (שזו בערך אותה כמות הואיל והאופה מכין יותר). אבל, אם מכינים בבית כמות כפולה מהמינימום שחייב ב*חלה*, מדוארייתא תהיה חובה להפריש 1/48 מהעיסה, ואילו מדרבנן, צריך להפריש 1/24 משיעור העיסה בפועל.[20]\n\nלסיכום:\n\n- הרמב\"ם פסק שהפרשה ונתינה של *חלה* זו מצוה אחת שניתן לקיים בכל כמות שהיא, אבל מדרבנן, יש לתת 1/24 מעיסה ביתית ו1/48 מעיסה של אופה משום שזה נחשב לנתינה מכובדת.\n\n- הרמב\"ן חולק וסובר שיש 2 מצוות – הפרשה ונתינה.\n\n- לפי הנודע ביהודה, מצות התורה של הפרשה מתקיימת בכמות כלשהי, ואילו מצות התורה של נתינה מתקיימת ב1/24 משיעור המינימום החייב בהפרשת *חלה*. (אם העיסה גדולה יותר מהמינימום, עדיין נותנים 1/24, אבל כל כמות שהיא מעבר ל1/24 משיעור המינימום היא רק מדרבנן.)\n\nSource Notes\n\n[20]:  הרוב מבינים שדברי הנודע ביהודה מתיישבים רק לפי דעת הרמב\"ן שיש 2 חלקים למצוה, אבל שבט הלוי (ח\"ב, קעח סק\"ב) הבין שהנודע ביהודה יכול להסתדר גם לפי הרמב\"ם.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":80,"xmlIndex":85,"text":"הרמב\"ן (השגות, שורש יב) (26) חולק על הרמב\"ם ופוסק שהפרשת חלה מורכבת משתי מצוות נפרדות: 1) הפרשת בצק כחלה, ובכך התרת הבצק שנשאר באכילה (והוא כבר לא טבל). 2) נתינת הבצק לכהן.","spans":[{"text":"ה"},{"text":"רמב\"ן","bold":true},{"text":" (השגות, שורש יב) (26) חולק על הרמב\"ם ופוסק שהפרשת "},{"text":"חלה","italic":true},{"text":" מורכבת משתי מצוות נפרדות: 1) הפרשת בצק כ"},{"text":"חלה","italic":true},{"text":", ובכך התרת הבצק שנשאר באכילה (והוא כבר לא טבל). 2) נתינת הבצק לכהן."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":81,"xmlIndex":86,"text":"הנודע ביהודה (יו\"ד תנינא, רא) (27) כתב שאפילו נתינת 1/24 או 1/48 יכולה להיות חלק ממצווה דאורייתא. הוא מסביר שהואיל ויש שני חלקים למצות הפרשת חלה, הפרשה ונתינה, כאשר אדם מפריש אפילו כמות כלשהי, הוא מקיים מדאורייתא את מצות הפרשה. אולם, כאשר הוא נותן את הבצק לכהן, מציע הנודע ביהודה שהכמות שצריך להפריש היא תמיד 1/24 משיעור הקמח המינימלי שחייב בהפרשת חלה (עשירית האיפה, שלהלן נלמד שהיינו בין 1.2-2.2 ק\"ג). אם אדם מכין רק את כמות המינימום של בצק שחייב בהפרשת חלה, אזי יש מצוה דאורייתא לתת כמות שנחשבת לנתינה משמעותית, דהיינו, 1/24 מעיסה ביתית ו1/48 מעיסה של אופה (שזו בערך אותה כמות הואיל והאופה מכין יותר). אבל, אם מכינים בבית כמות כפולה מהמינימום שחייב בחלה, מדוארייתא תהיה חובה להפריש 1/48 מהעיסה, ואילו מדרבנן, צריך להפריש 1/24 משיעור העיסה בפועל.[20]","spans":[{"text":"ה"},{"text":"נודע ביהודה","bold":true},{"text":" (יו\"ד תנינא, רא) (27) כתב שאפילו נתינת 1/24 או 1/48 יכולה להיות חלק ממצווה דאורייתא. הוא מסביר שהואיל ויש שני חלקים למצות הפרשת "},{"text":"חלה","italic":true},{"text":", הפרשה ונתינה, כאשר אדם מפריש אפילו כמות כלשהי, הוא מקיים מדאורייתא את מצות הפרשה. אולם, כאשר הוא נותן את הבצק לכהן, מציע הנודע ביהודה שהכמות שצריך להפריש היא תמיד 1/24 משיעור הקמח המינימלי שחייב בהפרשת "},{"text":"חלה","italic":true},{"text":" (עשירית האיפה, שלהלן נלמד שהיינו בין 1.2-2.2 ק\"ג). אם אדם מכין רק את כמות המינימום של בצק שחייב בהפרשת "},{"text":"חלה","italic":true},{"text":", אזי יש מצוה דאורייתא לתת כמות שנחשבת לנתינה משמעותית, דהיינו, 1/24 מעיסה ביתית ו1/48 מעיסה של אופה (שזו בערך אותה כמות הואיל והאופה מכין יותר). אבל, אם מכינים בבית כמות כפולה מהמינימום שחייב ב"},{"text":"חלה","italic":true},{"text":", מדוארייתא תהיה חובה להפריש 1/48 מהעיסה, ואילו מדרבנן, צריך להפריש 1/24 משיעור העיסה בפועל."},{"text":"[20]","footnote":20}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[20],"defaultTabWidth":36},{"kind":"paragraph","paragraph":82,"xmlIndex":87,"text":"לסיכום:","spans":[{"text":"לסיכום:"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"list","paragraph":83,"xmlIndex":88,"text":"הרמב\"ם פסק שהפרשה ונתינה של חלה זו מצוה אחת שניתן לקיים בכל כמות שהיא, אבל מדרבנן, יש לתת 1/24 מעיסה ביתית ו1/48 מעיסה של אופה משום שזה נחשב לנתינה מכובדת.","spans":[{"text":"הרמב\"ם פסק שהפרשה ונתינה של "},{"text":"חלה","italic":true},{"text":" זו מצוה אחת שניתן לקיים בכל כמות שהיא, אבל מדרבנן, יש לתת 1/24 מעיסה ביתית ו1/48 מעיסה של אופה משום שזה נחשב לנתינה מכובדת."}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":84,"xmlIndex":89,"text":"הרמב\"ן חולק וסובר שיש 2 מצוות – הפרשה ונתינה.","spans":[{"text":"הרמב\"ן חולק וסובר שיש 2 מצוות – הפרשה ונתינה."}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":85,"xmlIndex":90,"text":"לפי הנודע ביהודה, מצות התורה של הפרשה מתקיימת בכמות כלשהי, ואילו מצות התורה של נתינה מתקיימת ב1/24 משיעור המינימום החייב בהפרשת חלה. (אם העיסה גדולה יותר מהמינימום, עדיין נותנים 1/24, אבל כל כמות שהיא מעבר ל1/24 משיעור המינימום היא רק מדרבנן.)","spans":[{"text":"לפי הנודע ביהודה, מצות התורה של הפרשה מתקיימת בכמות כלשהי, ואילו מצות התורה של נתינה מתקיימת ב1/24 משיעור המינימום החייב בהפרשת "},{"text":"חלה","italic":true},{"text":". (אם העיסה גדולה יותר מהמינימום, עדיין נותנים 1/24, אבל כל כמות שהיא מעבר ל1/24 משיעור המינימום היא רק מדרבנן.)"}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18}],"footnotes":[{"id":20,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" הרוב מבינים שדברי הנודע ביהודה מתיישבים רק לפי דעת הרמב\"ן שיש 2 חלקים למצוה, אבל שבט הלוי (ח\"ב, קעח סק\"ב) הבין שהנודע ביהודה יכול להסתדר גם לפי הרמב\"ם.","spans":[{"text":" הרוב מבינים שדברי הנודע ביהודה מתיישבים רק לפי דעת הרמב\"ן שיש 2 חלקים למצוה, אבל שבט הלוי (ח\"ב, קעח סק\"ב) הבין שהנודע ביהודה יכול להסתדר גם לפי הרמב\"ם."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[26,27],"approved_hash":"3adf9e4e5d67f40c8af68f7fde48fba5e34683c56d36945ce44156c3d093102d"},{"chunk_code":"HC1-D4","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ד","chunk_title":"שיעור ההפרשה למעשה בארץ ישראל ובחוץ לארץ","chunk_summary":"בירור שיטות השולחן ערוך והרמ״א והמנהג למעשה: כיום הן אשכנזים והן ספרדים מפרישים חלה אחת, בשיעור כלשהו, נהגו בכזית, ושורפים אותה.","content_markdown":"כיצד פוסקים? השו\"ע ב**סימן שכב, א** (28) הביא את לשון הרמב\"ם שיש מצוה דאורייתא להפריש *חלה* ולתת לכהן, ומן התורה החיוב מתקיים אפילו בשיעור כלשהו. אולם, מדרבנן, יש לתת 1/24 מעיסה ביתית ו1/48 מעיסה של אופה. השו\"ע הוסיף, על פי ה**משנה חלה** (פ\"ב, ז) שהובאה לעיל, שאם העיסה נטמאה ובכל מקרה ה*חלה* תישרף, אפילו מעיסה ביתית צריך להפריש רק 1/48.\n\nכל הנ\"ל נוגע להפרשת *חלה* בא\"י, אבל בחו\"ל, ההלכה שונה במעט, וכפי שיבואר. ה**משנה חלה** (פ\"ד, ח) מלמדת שהעולם מחולק לשלשה אזורים: חלקים של א\"י שהתקדשו על ידי עזרא, חלקים של א\"י שלא התקדשו ע\"י עזרא, ושאר העולם. המשנה מבארת שמספר ה*חלות* (דהיינו, חתיכות הבצק, אחת או שתיים) שמפרישים והגודל של כל *חלה*, תלוי באזור. בחלקי א\"י שהתקדשו ע\"י עזרא מפרישים רק *חלה* אחת, ובשאר חלקי א\"י שלא התקדשו ע\"י עזרא ובחו\"ל, מפרישים 2 *חלות*, אחת שורפים ואת השנייה נותנים לכהן.[21]\n\nיש מחלוקת משולשת בראשונים כיצד להבין את המשנה. לשם הבהירות והקיצור, אנו נעסוק רק בפסק של השו\"ע, הרמ\"א, וההלכה למעשה בימינו, שמוסכמת על בני אשכנז ובני ע\"מ.\n\nבא\"י, כולם מודים שמפרישים *חלה* אחת ושורפים. בחו\"ל, ה**שו\"ע** בסעיפים ד-ה (29) פסק שאפשר או להפריש שתיים, אחת לשרפה ואחת שתינתן לכהן, או שאפשר להפריש אחת (שיעור 1/48 מהעיסה)[22] ולתת אותה לכהן שאיננו טמא בטומאה שיוצאת מגופו (דהיינו, בעל קרי, נדה, זב או זבה). ה**רמ\"א** בסעיף ה' חולק וסובר שבין בא\"י ובין בחו\"ל, מפרישים רק *חלה* אחת. היא יכולה להיות בכל גודל שהוא, אמנם המנהג הוא להפריש כזית, ויש לשרוף אותה.\n\nה**ט\"ז** (ה) ביאר שהמנהג לשרוף את ה*חלה* במקום לתת אותה לכהן מפני שבימינו אנו לא בטוחים מי באמת כהן. הרמ\"א הוסיף שאם הכהן אוכל את ה*חלה*, עליו לברך תחילה ברכה מיוחדת.[23]\n\nלסיכום:\n\n- ב<u>א\"י</u> מפרישים חלה אחת ושורפים אותה.\n\n- **שו\"ע** – ה*חלה* צריכה להיות בשיעור של 1/48 מהבצק.\n\n- **רמ\"א** – כל כמות, אמנם נהגו להפריש כזית.\n\n- ב<u>חו\"ל</u>:\n\n- **שו\"ע** – או מפרישים 2 *חלות*, שורפים אחת ונותנים את השנייה לכהן, אפילו אם הוא טמא, או שמפרישים *חלה* אחת ונותנים אותה לכהן שאיננו טמא בטומאה שיוצאות מגופו.\n\n- **רמ\"א** – בימינו, בין בא\"י ובין בחו\"ל, מפרישים רק *חלה* אחת בכל גודל שהוא, אבל ראוי להפריש כזית, ושורפים אותה (מפני שאנו לא בטוחים מי באמת כהן).\n\nכיצד אנו פוסקים למעשה? בני אשכנז פוסקים כמו הרמ\"א שניתן להפריש כל כמות שהיא של *חלה*, אמנם המנהג להפריש כזית, ויש לשרוף אותה. לגבי בני ע\"מ, **בית יוסף** כתב שהמנהג הוא להפריש רק *חלה* אחת ולשרוף אותה, ונראה שהבית יוסף מתייחס למנהג בין בא\"י ובין בחו\"ל (כמו הרמ\"א). ה**ברכי יוסף** (שכב, ב) (30) כתב שלמרות שהשו\"ע לא מביא זאת כאן, ב**סימן שלא, יט** הוא פסק שהואיל ובימינו שורפים תרומה, די להפריש כמות כלשהי, ואותו עיקרון נכון גם לגבי *חלה*. ה**גרע\"י** בהליכות עולם (ח\"ג, עמ' מט) פסק אף הוא שגם בני ע\"מ יפרישו *חלה* אחת, והיא יכולה להיות בכל שיעור שהוא, ויש לשרוף אותה.\n\nSource Notes\n\n[21]:  הירושלמי (חלה פ\"ד, ד) ביאר את הסיבה מדוע באזורים של א\"י שלא התקדשו על ידי עזרא צריך להפריש 2 *חלות*. ה*חלה* הראשונה מופרשת ונשרפת בגלל שחז\"ל גזרו טומאה על חו\"ל וכן על אזורים בא\"י שלא התקדשו ע\"י עזרא (טומאת ארץ העמים). אולם, הואיל ורבים אינם מודעים לטומאה זו, הם עלולים לחשוב שכל הפרשת *חלה* טענה שריפה. לכן, נותנים *חלה* שניה לכהן. אבל אי אפשר לתת לכהן *חלה* אחת בלבד מפני שאז אלו שכן יודעים על הטומאה יסברו שמותר לאכול *חלה* טמאה. לכן, צריך את שתי ה*חלות*. בחו\"ל רגיל הרמב\"ם (ביכורים פ\"ה, ח) ביאר שאת ה*חלה* הראשונה שורפים משום שיש טומאה בחו\"ל, ואת השנייה נותנים לכהן כדי שלא תשתכח תורת *חלה*.\n\n[22]:  משתמשים בשיעור הקטן יותר הואיל וההפרשה בחו\"ל.\n\n[23]:  הרמ\"א בהלכות פסח סימן תנז כתב שכהן קטן יכול לאכול מצה שנעשתה מבצק של הפרשת *חלה*. ה**ש\"ך** (שכב, ט) מקשה שנראה שהרמ\"א סותר את עצמו. כאן הוא כתב שהמנהג הוא לשרוף את ה*חלה*, ואילו בהלכות פסח הוא פסק שניתן לתת את זה לקטן? הש\"ך עונה שיש לחלק בין פסח לשאר ימות השנה. ה**מג\"א** (תנז, ט) ביאר שבערב פסח (ופסח) המנהג הוא לתת *חלה* לכהן קטן הואיל ויש הרבה *חלה* שמופרשת ואם הם לא יאכלו מה*חלה*, אנשים עלולים לפקפק אם הם כהנים. ה**ערה\"ש** (שכב, כא) הוכיח שהרמ\"א מסכים לחילוק זה שיש זמנים בהם כהנים אוכלים *חלה*, הואיל והוא כתב את נוסח הברכה שכהן צריך לברך כאשר הוא אוכל *חלה*.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":86,"xmlIndex":91,"text":"כיצד פוסקים? השו\"ע בסימן שכב, א (28) הביא את לשון הרמב\"ם שיש מצוה דאורייתא להפריש חלה ולתת לכהן, ומן התורה החיוב מתקיים אפילו בשיעור כלשהו. אולם, מדרבנן, יש לתת 1/24 מעיסה ביתית ו1/48 מעיסה של אופה. השו\"ע הוסיף, על פי המשנה חלה (פ\"ב, ז) שהובאה לעיל, שאם העיסה נטמאה ובכל מקרה החלה תישרף, אפילו מעיסה ביתית צריך להפריש רק 1/48.","spans":[{"text":"כיצד פוסקים? השו\"ע ב"},{"text":"סימן שכב, א","bold":true},{"text":" (28) הביא את לשון הרמב\"ם שיש מצוה דאורייתא להפריש "},{"text":"חלה","italic":true},{"text":" ולתת לכהן, ומן התורה החיוב מתקיים אפילו בשיעור כלשהו. אולם, מדרבנן, יש לתת 1/24 מעיסה ביתית ו1/48 מעיסה של אופה. השו\"ע הוסיף, על פי ה"},{"text":"משנה חלה","bold":true},{"text":" (פ\"ב, ז) שהובאה לעיל, שאם העיסה נטמאה ובכל מקרה ה"},{"text":"חלה","italic":true},{"text":" תישרף, אפילו מעיסה ביתית צריך להפריש רק 1/48."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":87,"xmlIndex":92,"text":"כל הנ\"ל נוגע להפרשת חלה בא\"י, אבל בחו\"ל, ההלכה שונה במעט, וכפי שיבואר. המשנה חלה (פ\"ד, ח) מלמדת שהעולם מחולק לשלשה אזורים: חלקים של א\"י שהתקדשו על ידי עזרא, חלקים של א\"י שלא התקדשו ע\"י עזרא, ושאר העולם. המשנה מבארת שמספר החלות (דהיינו, חתיכות הבצק, אחת או שתיים) שמפרישים והגודל של כל חלה, תלוי באזור. בחלקי א\"י שהתקדשו ע\"י עזרא מפרישים רק חלה אחת, ובשאר חלקי א\"י שלא התקדשו ע\"י עזרא ובחו\"ל, מפרישים 2 חלות, אחת שורפים ואת השנייה נותנים לכהן.[21]","spans":[{"text":"כל הנ\"ל נוגע להפרשת "},{"text":"חלה","italic":true},{"text":" בא\"י, אבל בחו\"ל, ההלכה שונה במעט, וכפי שיבואר. ה"},{"text":"משנה חלה","bold":true},{"text":" (פ\"ד, ח) מלמדת שהעולם מחולק לשלשה אזורים: חלקים של א\"י שהתקדשו על ידי עזרא, חלקים של א\"י שלא התקדשו ע\"י עזרא, ושאר העולם. המשנה מבארת שמספר ה"},{"text":"חלות","italic":true},{"text":" (דהיינו, חתיכות הבצק, אחת או שתיים) שמפרישים והגודל של כל "},{"text":"חלה","italic":true},{"text":", תלוי באזור. בחלקי א\"י שהתקדשו ע\"י עזרא מפרישים רק "},{"text":"חלה","italic":true},{"text":" אחת, ובשאר חלקי א\"י שלא התקדשו ע\"י עזרא ובחו\"ל, מפרישים 2 "},{"text":"חלות","italic":true},{"text":", אחת שורפים ואת השנייה נותנים לכהן."},{"text":"[21]","footnote":21}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[21],"defaultTabWidth":36},{"kind":"paragraph","paragraph":88,"xmlIndex":93,"text":"יש מחלוקת משולשת בראשונים כיצד להבין את המשנה. לשם הבהירות והקיצור, אנו נעסוק רק בפסק של השו\"ע, הרמ\"א, וההלכה למעשה בימינו, שמוסכמת על בני אשכנז ובני ע\"מ.","spans":[{"text":"יש מחלוקת משולשת בראשונים כיצד להבין את המשנה. לשם הבהירות והקיצור, אנו נעסוק רק בפסק של השו\"ע, הרמ\"א, וההלכה למעשה בימינו, שמוסכמת על בני אשכנז ובני ע\"מ."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":89,"xmlIndex":94,"text":"בא\"י, כולם מודים שמפרישים חלה אחת ושורפים. בחו\"ל, השו\"ע בסעיפים ד-ה (29) פסק שאפשר או להפריש שתיים, אחת לשרפה ואחת שתינתן לכהן, או שאפשר להפריש אחת (שיעור 1/48 מהעיסה)[22] ולתת אותה לכהן שאיננו טמא בטומאה שיוצאת מגופו (דהיינו, בעל קרי, נדה, זב או זבה). הרמ\"א בסעיף ה' חולק וסובר שבין בא\"י ובין בחו\"ל, מפרישים רק חלה אחת. היא יכולה להיות בכל גודל שהוא, אמנם המנהג הוא להפריש כזית, ויש לשרוף אותה.","spans":[{"text":"בא\"י, כולם מודים שמפרישים "},{"text":"חלה","italic":true},{"text":" אחת ושורפים. בחו\"ל, ה"},{"text":"שו\"ע","bold":true},{"text":" בסעיפים ד-ה (29) פסק שאפשר או להפריש שתיים, אחת לשרפה ואחת שתינתן לכהן, או שאפשר להפריש אחת (שיעור 1/48 מהעיסה)"},{"text":"[22]","footnote":22},{"text":" ולתת אותה לכהן שאיננו טמא בטומאה שיוצאת מגופו (דהיינו, בעל קרי, נדה, זב או זבה). ה"},{"text":"רמ\"א","bold":true},{"text":" בסעיף ה' חולק וסובר שבין בא\"י ובין בחו\"ל, מפרישים רק "},{"text":"חלה","italic":true},{"text":" אחת. היא יכולה להיות בכל גודל שהוא, אמנם המנהג הוא להפריש כזית, ויש לשרוף אותה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[22],"defaultTabWidth":36},{"kind":"paragraph","paragraph":90,"xmlIndex":95,"text":"הט\"ז (ה) ביאר שהמנהג לשרוף את החלה במקום לתת אותה לכהן מפני שבימינו אנו לא בטוחים מי באמת כהן. הרמ\"א הוסיף שאם הכהן אוכל את החלה, עליו לברך תחילה ברכה מיוחדת.[23]","spans":[{"text":"ה"},{"text":"ט\"ז","bold":true},{"text":" (ה) ביאר שהמנהג לשרוף את ה"},{"text":"חלה","italic":true},{"text":" במקום לתת אותה לכהן מפני שבימינו אנו לא בטוחים מי באמת כהן. הרמ\"א הוסיף שאם הכהן אוכל את ה"},{"text":"חלה","italic":true},{"text":", עליו לברך תחילה ברכה מיוחדת."},{"text":"[23]","footnote":23}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[23],"defaultTabWidth":36},{"kind":"paragraph","paragraph":91,"xmlIndex":96,"text":"לסיכום:","spans":[{"text":"לסיכום:"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"list","paragraph":92,"xmlIndex":97,"text":"בא\"י מפרישים חלה אחת ושורפים אותה.","spans":[{"text":"ב"},{"text":"א\"י","underline":true},{"text":" מפרישים חלה אחת ושורפים אותה."}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":93,"xmlIndex":98,"text":"שו\"ע – החלה צריכה להיות בשיעור של 1/48 מהבצק.","spans":[{"text":"שו\"ע ","bold":true},{"text":"– ה"},{"text":"חלה","italic":true},{"text":" צריכה להיות בשיעור של 1/48 מהבצק."}],"marker":"•","level":0,"indent":90,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":94,"xmlIndex":99,"text":"רמ\"א – כל כמות, אמנם נהגו להפריש כזית.","spans":[{"text":"רמ\"א","bold":true},{"text":" – כל כמות, אמנם נהגו להפריש כזית."}],"marker":"•","level":0,"indent":90,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":95,"xmlIndex":100,"text":"בחו\"ל:","spans":[{"text":"ב"},{"text":"חו\"ל","underline":true},{"text":":"}],"marker":"•","level":0,"indent":54,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":96,"xmlIndex":101,"text":"שו\"ע – או מפרישים 2 חלות, שורפים אחת ונותנים את השנייה לכהן, אפילו אם הוא טמא, או שמפרישים חלה אחת ונותנים אותה לכהן שאיננו טמא בטומאה שיוצאות מגופו.","spans":[{"text":"שו\"ע","bold":true},{"text":" – או מפרישים 2 "},{"text":"חלות","italic":true},{"text":", שורפים אחת ונותנים את השנייה לכהן, אפילו אם הוא טמא, או שמפרישים "},{"text":"חלה","italic":true},{"text":" אחת ונותנים אותה לכהן שאיננו טמא בטומאה שיוצאות מגופו."}],"marker":"•","level":0,"indent":90,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"list","paragraph":97,"xmlIndex":102,"text":"רמ\"א – בימינו, בין בא\"י ובין בחו\"ל, מפרישים רק חלה אחת בכל גודל שהוא, אבל ראוי להפריש כזית, ושורפים אותה (מפני שאנו לא בטוחים מי באמת כהן).","spans":[{"text":"רמ\"א","bold":true},{"text":" – בימינו, בין בא\"י ובין בחו\"ל, מפרישים רק "},{"text":"חלה","italic":true},{"text":" אחת בכל גודל שהוא, אבל ראוי להפריש כזית, ושורפים אותה (מפני שאנו לא בטוחים מי באמת כהן)."}],"marker":"•","level":0,"indent":90,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":98,"xmlIndex":103,"text":"כיצד אנו פוסקים למעשה? בני אשכנז פוסקים כמו הרמ\"א שניתן להפריש כל כמות שהיא של חלה, אמנם המנהג להפריש כזית, ויש לשרוף אותה. לגבי בני ע\"מ, בית יוסף כתב שהמנהג הוא להפריש רק חלה אחת ולשרוף אותה, ונראה שהבית יוסף מתייחס למנהג בין בא\"י ובין בחו\"ל (כמו הרמ\"א). הברכי יוסף (שכב, ב) (30) כתב שלמרות שהשו\"ע לא מביא זאת כאן, בסימן שלא, יט הוא פסק שהואיל ובימינו שורפים תרומה, די להפריש כמות כלשהי, ואותו עיקרון נכון גם לגבי חלה. הגרע\"י בהליכות עולם (ח\"ג, עמ' מט) פסק אף הוא שגם בני ע\"מ יפרישו חלה אחת, והיא יכולה להיות בכל שיעור שהוא, ויש לשרוף אותה.","spans":[{"text":"כיצד אנו פוסקים למעשה? בני אשכנז פוסקים כמו הרמ\"א שניתן להפריש כל כמות שהיא של "},{"text":"חלה","italic":true},{"text":", אמנם המנהג להפריש כזית, ויש לשרוף אותה. לגבי בני ע\"מ, "},{"text":"בית יוסף","bold":true},{"text":" כתב שהמנהג הוא להפריש רק "},{"text":"חלה","italic":true},{"text":" אחת ולשרוף אותה, ונראה שהבית יוסף מתייחס למנהג בין בא\"י ובין בחו\"ל (כמו הרמ\"א). ה"},{"text":"ברכי יוסף","bold":true},{"text":" (שכב, ב) (30) כתב שלמרות שהשו\"ע לא מביא זאת כאן, ב"},{"text":"סימן שלא, יט","bold":true},{"text":" הוא פסק שהואיל ובימינו שורפים תרומה, די להפריש כמות כלשהי, ואותו עיקרון נכון גם לגבי "},{"text":"חלה","italic":true},{"text":". ה"},{"text":"גרע\"י","bold":true},{"text":" בהליכות עולם (ח\"ג, עמ' מט) פסק אף הוא שגם בני ע\"מ יפרישו "},{"text":"חלה","italic":true},{"text":" אחת, והיא יכולה להיות בכל שיעור שהוא, ויש לשרוף אותה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":21,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" הירושלמי (חלה פ\"ד, ד) ביאר את הסיבה מדוע באזורים של א\"י שלא התקדשו על ידי עזרא צריך להפריש 2 חלות. החלה הראשונה מופרשת ונשרפת בגלל שחז\"ל גזרו טומאה על חו\"ל וכן על אזורים בא\"י שלא התקדשו ע\"י עזרא (טומאת ארץ העמים). אולם, הואיל ורבים אינם מודעים לטומאה זו, הם עלולים לחשוב שכל הפרשת חלה טענה שריפה. לכן, נותנים חלה שניה לכהן. אבל אי אפשר לתת לכהן חלה אחת בלבד מפני שאז אלו שכן יודעים על הטומאה יסברו שמותר לאכול חלה טמאה. לכן, צריך את שתי החלות. בחו\"ל רגיל הרמב\"ם (ביכורים פ\"ה, ח) ביאר שאת החלה הראשונה שורפים משום שיש טומאה בחו\"ל, ואת השנייה נותנים לכהן כדי שלא תשתכח תורת חלה.","spans":[{"text":" הירושלמי (חלה פ\"ד, ד) ביאר את הסיבה מדוע באזורים של א\"י שלא התקדשו על ידי עזרא צריך להפריש 2 "},{"text":"חלות","italic":true},{"text":". ה"},{"text":"חלה","italic":true},{"text":" הראשונה מופרשת ונשרפת בגלל שחז\"ל גזרו טומאה על חו\"ל וכן על אזורים בא\"י שלא התקדשו ע\"י עזרא (טומאת ארץ העמים). אולם, הואיל ורבים אינם מודעים לטומאה זו, הם עלולים לחשוב שכל הפרשת "},{"text":"חלה","italic":true},{"text":" טענה שריפה. לכן, נותנים "},{"text":"חלה","italic":true},{"text":" שניה לכהן. אבל אי אפשר לתת לכהן "},{"text":"חלה","italic":true},{"text":" אחת בלבד מפני שאז אלו שכן יודעים על הטומאה יסברו שמותר לאכול "},{"text":"חלה","italic":true},{"text":" טמאה. לכן, צריך את שתי ה"},{"text":"חלות","italic":true},{"text":". בחו\"ל רגיל הרמב\"ם (ביכורים פ\"ה, ח) ביאר שאת ה"},{"text":"חלה","italic":true},{"text":" הראשונה שורפים משום שיש טומאה בחו\"ל, ואת השנייה נותנים לכהן כדי שלא תשתכח תורת "},{"text":"חלה","italic":true},{"text":"."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":22,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" משתמשים בשיעור הקטן יותר הואיל וההפרשה בחו\"ל.","spans":[{"text":" משתמשים בשיעור הקטן יותר הואיל וההפרשה בחו\"ל."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]},{"id":23,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" הרמ\"א בהלכות פסח סימן תנז כתב שכהן קטן יכול לאכול מצה שנעשתה מבצק של הפרשת חלה. הש\"ך (שכב, ט) מקשה שנראה שהרמ\"א סותר את עצמו. כאן הוא כתב שהמנהג הוא לשרוף את החלה, ואילו בהלכות פסח הוא פסק שניתן לתת את זה לקטן? הש\"ך עונה שיש לחלק בין פסח לשאר ימות השנה. המג\"א (תנז, ט) ביאר שבערב פסח (ופסח) המנהג הוא לתת חלה לכהן קטן הואיל ויש הרבה חלה שמופרשת ואם הם לא יאכלו מהחלה, אנשים עלולים לפקפק אם הם כהנים. הערה\"ש (שכב, כא) הוכיח שהרמ\"א מסכים לחילוק זה שיש זמנים בהם כהנים אוכלים חלה, הואיל והוא כתב את נוסח הברכה שכהן צריך לברך כאשר הוא אוכל חלה.","spans":[{"text":" הרמ\"א בהלכות פסח סימן תנז כתב שכהן קטן יכול לאכול מצה שנעשתה מבצק של הפרשת "},{"text":"חלה","italic":true},{"text":". ה"},{"text":"ש\"ך","bold":true},{"text":" (שכב, ט) מקשה שנראה שהרמ\"א סותר את עצמו. כאן הוא כתב שהמנהג הוא לשרוף את ה"},{"text":"חלה","italic":true},{"text":", ואילו בהלכות פסח הוא פסק שניתן לתת את זה לקטן? הש\"ך עונה שיש לחלק בין פסח לשאר ימות השנה. ה"},{"text":"מג\"א","bold":true},{"text":" (תנז, ט) ביאר שבערב פסח (ופסח) המנהג הוא לתת "},{"text":"חלה","italic":true},{"text":" לכהן קטן הואיל ויש הרבה "},{"text":"חלה","italic":true},{"text":" שמופרשת ואם הם לא יאכלו מה"},{"text":"חלה","italic":true},{"text":", אנשים עלולים לפקפק אם הם כהנים. ה"},{"text":"ערה\"ש","bold":true},{"text":" (שכב, כא) הוכיח שהרמ\"א מסכים לחילוק זה שיש זמנים בהם כהנים אוכלים "},{"text":"חלה","italic":true},{"text":", הואיל והוא כתב את נוסח הברכה שכהן צריך לברך כאשר הוא אוכל "},{"text":"חלה","italic":true},{"text":"."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[28,29,30],"approved_hash":"d90aea8f3e3eaaaa9da2b35ed45efc708e81a52a5bff371adf9209e5ab361e61"},{"chunk_code":"HC1-E1","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"שריפת החלה שהופרשה — המקור וחשש ההנאה","chunk_summary":"הגמרא, הראשונים, השולחן ערוך והרמ״א מלמדים שיש לשרוף חלה טמאה; לישראל אסור ליהנות מאש שריפתה, ולכן נידונה שריפה נפרדת.","content_markdown":"### ה. *מה עושים עם החלה שהופרשה?*\n\nאחרי שלמדנו שבימינו בין בני ע\"מ ובין בני אשכנז מסכימים להפריש בערך כזית *חלה* אותה שורפים, כעת נעמיק בהלכות של שריפת *חלה.*\n\nה**גמרא שבת** (כה, א) (31) מלמדת שכשם שיש מצוה לשרוף קדשים (כגון, קורבנות) שנטמאו, כך גם יש מצוה לשרוף תרומה (ו*חלה*) שנטמאה. הגמרא מוסיפה שכאשר תרומה/*חלה* נשרפת, מותר לכהן ליהנות מהאש, אבל לישראל אסור. **רש\"י** מבאר ששורפים תרומה או משום שהיא דומה לקדשים, או מפני שאם ישאירו אותה בלי לשורפה הדבר עלול להביא לידי הנאה בטעות מהתרומה. רוב הראשונים[24] מבינים ששיש חיוב דווקא לשרוף תרומה ו*חלה* שנטמאו, ולא רק להיפטר מהן בדרך כלשהי.\n\nהשו\"ע ב**סעיף ד** והרמ\"א ב**סעיף ה** (29) פסקו שיש לשרוף את ה*חלה* באש נפרדת מפני שמי שאינו כהן עלול ליהנות משריפתה. הרמ\"א הוסיף שהמנהג בזמנו היה לשרוף את ה*חלה* לפני השימוש בתנור, בגלל שאם יאפו אוכל בתנור בזמן שה*חלה* נשרפת, נמצא שהאדם נהנה מתוספת האש והחום שנוצרים על ידי שריפת ה*חלה*. **חלקת בנימין** (שכב סקצ\"ז) (32) ביאר שלמרות שנתינת ה*חלה* בתנור אחרי שהוא כבר התחמם כולו אף היא תוסיף בחום התנור (וממילא תגרום שהאדם ייהנה מה*חלה*), תוספת זו מעטה מאוד כך שזה לא נחשב שאתה נהנה מה*חלה*.\n\nSource Notes\n\n[24]:  ראה תוספות שם ד\"ה כך, ואגרות משה (יו\"ד ח\"ג, קכט).","content_document":{"version":1,"language":"he","blocks":[{"kind":"heading","paragraph":99,"xmlIndex":104,"text":"מה עושים עם החלה שהופרשה?","spans":[{"text":"מה עושים עם החלה שהופרשה?","italic":true,"color":"#2F5496"}],"marker":"ה.","level":0,"indent":72,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"rightIndent":43.2,"hanging":18,"tabStops":[{"position":150.45,"alignment":"left","leader":"none"},{"position":234,"alignment":"center","leader":"none"},{"position":279,"alignment":"left","leader":"none"}]},{"kind":"paragraph","paragraph":100,"xmlIndex":106,"text":"אחרי שלמדנו שבימינו בין בני ע\"מ ובין בני אשכנז מסכימים להפריש בערך כזית חלה אותה שורפים, כעת נעמיק בהלכות של שריפת חלה.","spans":[{"text":"אחרי שלמדנו שבימינו בין בני ע\"מ ובין בני אשכנז מסכימים להפריש בערך כזית "},{"text":"חלה","italic":true},{"text":" אותה שורפים, כעת נעמיק בהלכות של שריפת"},{"text":" חלה.","italic":true}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":101,"xmlIndex":107,"text":"הגמרא שבת (כה, א) (31) מלמדת שכשם שיש מצוה לשרוף קדשים (כגון, קורבנות) שנטמאו, כך גם יש מצוה לשרוף תרומה (וחלה) שנטמאה. הגמרא מוסיפה שכאשר תרומה/חלה נשרפת, מותר לכהן ליהנות מהאש, אבל לישראל אסור. רש\"י מבאר ששורפים תרומה או משום שהיא דומה לקדשים, או מפני שאם ישאירו אותה בלי לשורפה הדבר עלול להביא לידי הנאה בטעות מהתרומה. רוב הראשונים[24] מבינים ששיש חיוב דווקא לשרוף תרומה וחלה שנטמאו, ולא רק להיפטר מהן בדרך כלשהי.","spans":[{"text":"ה"},{"text":"גמרא שבת","bold":true},{"text":" (כה, א) (31) מלמדת שכשם שיש מצוה לשרוף קדשים (כגון, קורבנות) שנטמאו, כך גם יש מצוה לשרוף תרומה (ו"},{"text":"חלה","italic":true},{"text":") שנטמאה. הגמרא מוסיפה שכאשר תרומה/"},{"text":"חלה","italic":true},{"text":" נשרפת, מותר לכהן ליהנות מהאש, אבל לישראל אסור. "},{"text":"רש\"י","bold":true},{"text":" מבאר ששורפים תרומה או משום שהיא דומה לקדשים, או מפני שאם ישאירו אותה בלי לשורפה הדבר עלול להביא לידי הנאה בטעות מהתרומה. רוב הראשונים"},{"text":"[24]","footnote":24},{"text":" מבינים ששיש חיוב דווקא לשרוף תרומה ו"},{"text":"חלה","italic":true},{"text":" שנטמאו, ולא רק להיפטר מהן בדרך כלשהי."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[24],"defaultTabWidth":36},{"kind":"paragraph","paragraph":102,"xmlIndex":108,"text":"השו\"ע בסעיף ד והרמ\"א בסעיף ה (29) פסקו שיש לשרוף את החלה באש נפרדת מפני שמי שאינו כהן עלול ליהנות משריפתה. הרמ\"א הוסיף שהמנהג בזמנו היה לשרוף את החלה לפני השימוש בתנור, בגלל שאם יאפו אוכל בתנור בזמן שהחלה נשרפת, נמצא שהאדם נהנה מתוספת האש והחום שנוצרים על ידי שריפת החלה. חלקת בנימין (שכב סקצ\"ז) (32) ביאר שלמרות שנתינת החלה בתנור אחרי שהוא כבר התחמם כולו אף היא תוסיף בחום התנור (וממילא תגרום שהאדם ייהנה מהחלה), תוספת זו מעטה מאוד כך שזה לא נחשב שאתה נהנה מהחלה.","spans":[{"text":"השו\"ע ב"},{"text":"סעיף ד","bold":true},{"text":" והרמ\"א ב"},{"text":"סעיף ה","bold":true},{"text":" (29) פסקו שיש לשרוף את ה"},{"text":"חלה","italic":true},{"text":" באש נפרדת מפני שמי שאינו כהן עלול ליהנות משריפתה. הרמ\"א הוסיף שהמנהג בזמנו היה לשרוף את ה"},{"text":"חלה","italic":true},{"text":" לפני השימוש בתנור, בגלל שאם יאפו אוכל בתנור בזמן שה"},{"text":"חלה","italic":true},{"text":" נשרפת, נמצא שהאדם נהנה מתוספת האש והחום שנוצרים על ידי שריפת ה"},{"text":"חלה","italic":true},{"text":". "},{"text":"חלקת בנימין","bold":true},{"text":" (שכב סקצ\"ז) (32) ביאר שלמרות שנתינת ה"},{"text":"חלה","italic":true},{"text":" בתנור אחרי שהוא כבר התחמם כולו אף היא תוסיף בחום התנור (וממילא תגרום שהאדם ייהנה מה"},{"text":"חלה","italic":true},{"text":"), תוספת זו מעטה מאוד כך שזה לא נחשב שאתה נהנה מה"},{"text":"חלה","italic":true},{"text":"."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":24,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" ראה תוספות שם ד\"ה כך, ואגרות משה (יו\"ד ח\"ג, קכט).","spans":[{"text":" ראה תוספות שם ד\"ה כך, ואגרות משה (יו\"ד ח\"ג, קכט)."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[29,31,32],"approved_hash":"d733a9e9c3e2e3afb45524f1f3ff7496f6e9d773c5eca1102fe18d6a1401ddcc"},{"chunk_code":"HC1-E2","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"שריפת חלה בתנור בימינו","chunk_summary":"בתנור מודרני שכבר התחמם, שריפת החלה אינה מוסיפה בדרך כלל חום משמעותי; בכל זאת יש לעטוף אותה היטב בשתי שכבות נייר כסף מחשש ריחא וזיעה.","content_markdown":"**נפק\"מ למעשה**\n\n<u>שריפת</u> *<u>חלה</u>* <u>בימינו</u>\n\nמה הדרך הטובה ביותר לשרוף *חלה* בימינו? האם צריך לשרוף את ה*חלה* לפני אפיית הלחם? **חלקת בנימין** (שכב, סקצ\"ט) (32) פסק שתנורי הגז שלנו כבר רותחים לגמרי כשאופים בהם, ושריפת ה*חלה* בתנור לא מגבירה את החום של התנור. לכן, אפיית מאכל אחר בשעה ששורפים בתנור את ה*חלה* לא נחשבת כהנאה משריפת ה*חלה*. למרות זאת, הואיל וה*חלה* אסורה באכילה (ואיסור זה חמור יותר מאכילת חזיר[25]) יש לוודא שעוטפים את ה*חלה* בעטיפה כפולה של נייר אלומיניום כדי למנוע בעיות של ריחא או זיעה שעלולים לאסור את המאכלים האחרים בתנור או את התנור עצמו.\n\nSource Notes\n\n[25]:  ישראל שאוכל תרומה חייב מיתה, אבל מי שאוכל חזיר חייב מלקות, אמנם כאן האיסור הוא רק מדרבנן מפני שבימינו *חלה* היא רק דרבנן.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":103,"xmlIndex":109,"text":"נפק\"מ למעשה","spans":[{"text":"נפק\"מ למעשה","bold":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":104,"xmlIndex":110,"text":"שריפת חלה בימינו","spans":[{"text":"שריפת ","underline":true},{"text":"חלה","italic":true,"underline":true},{"text":" בימינו","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":105,"xmlIndex":111,"text":"מה הדרך הטובה ביותר לשרוף חלה בימינו? האם צריך לשרוף את החלה לפני אפיית הלחם? חלקת בנימין (שכב, סקצ\"ט) (32) פסק שתנורי הגז שלנו כבר רותחים לגמרי כשאופים בהם, ושריפת החלה בתנור לא מגבירה את החום של התנור. לכן, אפיית מאכל אחר בשעה ששורפים בתנור את החלה לא נחשבת כהנאה משריפת החלה. למרות זאת, הואיל והחלה אסורה באכילה (ואיסור זה חמור יותר מאכילת חזיר[25]) יש לוודא שעוטפים את החלה בעטיפה כפולה של נייר אלומיניום כדי למנוע בעיות של ריחא או זיעה שעלולים לאסור את המאכלים האחרים בתנור או את התנור עצמו.","spans":[{"text":"מה הדרך הטובה ביותר לשרוף "},{"text":"חלה ","italic":true},{"text":"בימינו? האם צריך לשרוף את ה"},{"text":"חלה","italic":true},{"text":" לפני אפיית הלחם? "},{"text":"חלקת בנימין","bold":true},{"text":" (שכב, סקצ\"ט) (32) פסק שתנורי הגז שלנו כבר רותחים לגמרי כשאופים בהם, ושריפת ה"},{"text":"חלה","italic":true},{"text":" בתנור לא מגבירה את החום של התנור. לכן, אפיית מאכל אחר בשעה ששורפים בתנור את ה"},{"text":"חלה","italic":true},{"text":" לא נחשבת כהנאה משריפת ה"},{"text":"חלה","italic":true},{"text":". למרות זאת, הואיל וה"},{"text":"חלה","italic":true},{"text":" אסורה באכילה (ואיסור זה חמור יותר מאכילת חזיר"},{"text":"[25]","footnote":25},{"text":") יש לוודא שעוטפים את ה"},{"text":"חלה","italic":true},{"text":" בעטיפה כפולה של נייר אלומיניום כדי למנוע בעיות של ריחא או זיעה שעלולים לאסור את המאכלים האחרים בתנור או את התנור עצמו."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[25],"defaultTabWidth":36}],"footnotes":[{"id":25,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" ישראל שאוכל תרומה חייב מיתה, אבל מי שאוכל חזיר חייב מלקות, אמנם כאן האיסור הוא רק מדרבנן מפני שבימינו חלה היא רק דרבנן.","spans":[{"text":" ישראל שאוכל תרומה חייב מיתה, אבל מי שאוכל חזיר חייב מלקות, אמנם כאן האיסור הוא רק מדרבנן מפני שבימינו "},{"text":"חלה","italic":true},{"text":" היא רק דרבנן."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[32],"approved_hash":"86ca794a34f900e7cf13293770a9190d4a7630e2fea3bd06634a19f3df96d853"},{"chunk_code":"HC1-E3","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"נייר כסף שנקרע בזמן שריפת חלה בתנור","chunk_summary":"דיון בריחא ובזיעה: לפי הרב משה פיינשטיין והחיי הלוי, מאכלים אחרים מותרים כשחלה נחשפה, אך מגע ישיר עם הרשת מחייב ליבון; יש פוסקים החולקים.","content_markdown":"<u>נייר אלומיניום שנקרע</u>\n\nמה הדין אם אתה שורף *חלה* בתנור עם עוד מאכלים ושכחת לכסות את ה*חלה* או שנייר האלומיניום נקרע כשה*חלה* תופחת במהלך האפייה? האם שאר האוכל מותר? כדי לענות על שאלה זו, נסקור בקצרה מה שלמדנו בהלכות בשר בחלב. כאשר שני מאכלים נאפים יחד בתנור, כשאחד מהם אסור והשני מותר, או שאחד בשרי והאחר חלבי, יש 2 בעיות שצריך לדון בהן: 1) ריחא – העברת ריח ממאכל אחד לשני; 2) זיעה – העברת אדים.\n\nהשו\"ע ב**סימן קח, א** פסק שבדיעבד, אנו לא חוששים לריחא. אם כן, אם בישלת בשר יבש עם גבינה יבשה באותו תנור בו זמנית (כך שאין בעיה של זיעה), שניהם מותרים, למרות שיש ערבוב של ריח. אולם, אם הבשר או הגבינה היו לחים (ופוסקים רבים מניחים שרוב המאכלים הינם לחים), יש בעיה של זיעה, מפני שהאדים ממאכל אחד נכנסים בשני. פוסקים רבים סוברים שאפילו שימוש באותו תנור לחלבי ואחר כך לבשרי (או להיפך) אסור משום שהאדם מהמאכל החלבי נבלעים בדפנות התנור ומאוחר יותר יוצאים כשאופים מאכל בשרי.\n\nה**אגר\"מ** (יו\"ד ח\"T, מ) כתב שיש סוגי מאכלים מסוימים שאינם מוציאים אדים, כגון *חלה* או שאר תבשילים שאינם נוזליים. על פי זה, **חיי הלוי** (ח\"ג יו\"ד ע\"ט, ב) (33) פסק שאם אדם אפה בטעות *חלה* בלי לעטוף אותה בנייר אלומיניום, או אם הנייר העוטף נקרע במהלך האפייה, המאכלים האחרים בתנור מותרים. אולם, אם רשת התנור באה במגע ישיר עם ה*חלה* הגלויה, היא טעונה הכשרה על ידי ליבון. יש לציין שאחרונים רבים, כגון בספר **הפרשת חלה כהלכתה** (עמ' קה), חולקים על ר' משה ופוסקים שאפילו לחם מוציא אדים וכל האוכל שבתנור, וכן התנור עצמו, יהיו אסורים במקרה שנייר האלומיניום נקרע.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":106,"xmlIndex":112,"text":"נייר אלומיניום שנקרע","spans":[{"text":"נייר אלומיניום שנקרע","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":107,"xmlIndex":113,"text":"מה הדין אם אתה שורף חלה בתנור עם עוד מאכלים ושכחת לכסות את החלה או שנייר האלומיניום נקרע כשהחלה תופחת במהלך האפייה? האם שאר האוכל מותר? כדי לענות על שאלה זו, נסקור בקצרה מה שלמדנו בהלכות בשר בחלב. כאשר שני מאכלים נאפים יחד בתנור, כשאחד מהם אסור והשני מותר, או שאחד בשרי והאחר חלבי, יש 2 בעיות שצריך לדון בהן: 1) ריחא – העברת ריח ממאכל אחד לשני; 2) זיעה – העברת אדים.","spans":[{"text":"מה הדין אם אתה שורף "},{"text":"חלה","italic":true},{"text":" בתנור עם עוד מאכלים ושכחת לכסות את ה"},{"text":"חלה","italic":true},{"text":" או שנייר האלומיניום נקרע כשה"},{"text":"חלה","italic":true},{"text":" תופחת במהלך האפייה? האם שאר האוכל מותר? כדי לענות על שאלה זו, נסקור בקצרה מה שלמדנו בהלכות בשר בחלב. כאשר שני מאכלים נאפים יחד בתנור, כשאחד מהם אסור והשני מותר, או שאחד בשרי והאחר חלבי, יש 2 בעיות שצריך לדון בהן: 1) ריחא – העברת ריח ממאכל אחד לשני; 2) זיעה – העברת אדים."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":108,"xmlIndex":114,"text":"השו\"ע בסימן קח, א פסק שבדיעבד, אנו לא חוששים לריחא. אם כן, אם בישלת בשר יבש עם גבינה יבשה באותו תנור בו זמנית (כך שאין בעיה של זיעה), שניהם מותרים, למרות שיש ערבוב של ריח. אולם, אם הבשר או הגבינה היו לחים (ופוסקים רבים מניחים שרוב המאכלים הינם לחים), יש בעיה של זיעה, מפני שהאדים ממאכל אחד נכנסים בשני. פוסקים רבים סוברים שאפילו שימוש באותו תנור לחלבי ואחר כך לבשרי (או להיפך) אסור משום שהאדם מהמאכל החלבי נבלעים בדפנות התנור ומאוחר יותר יוצאים כשאופים מאכל בשרי.","spans":[{"text":"השו\"ע ב"},{"text":"סימן קח, א","bold":true},{"text":" פסק שבדיעבד, אנו לא חוששים לריחא. אם כן, אם בישלת בשר יבש עם גבינה יבשה באותו תנור בו זמנית (כך שאין בעיה של זיעה), שניהם מותרים, למרות שיש ערבוב של ריח. אולם, אם הבשר או הגבינה היו לחים (ופוסקים רבים מניחים שרוב המאכלים הינם לחים), יש בעיה של זיעה, מפני שהאדים ממאכל אחד נכנסים בשני. פוסקים רבים סוברים שאפילו שימוש באותו תנור לחלבי ואחר כך לבשרי (או להיפך) אסור משום שהאדם מהמאכל החלבי נבלעים בדפנות התנור ומאוחר יותר יוצאים כשאופים מאכל בשרי."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":109,"xmlIndex":115,"text":"האגר\"מ (יו\"ד ח\"T, מ) כתב שיש סוגי מאכלים מסוימים שאינם מוציאים אדים, כגון חלה או שאר תבשילים שאינם נוזליים. על פי זה, חיי הלוי (ח\"ג יו\"ד ע\"ט, ב) (33) פסק שאם אדם אפה בטעות חלה בלי לעטוף אותה בנייר אלומיניום, או אם הנייר העוטף נקרע במהלך האפייה, המאכלים האחרים בתנור מותרים. אולם, אם רשת התנור באה במגע ישיר עם החלה הגלויה, היא טעונה הכשרה על ידי ליבון. יש לציין שאחרונים רבים, כגון בספר הפרשת חלה כהלכתה (עמ' קה), חולקים על ר' משה ופוסקים שאפילו לחם מוציא אדים וכל האוכל שבתנור, וכן התנור עצמו, יהיו אסורים במקרה שנייר האלומיניום נקרע.","spans":[{"text":"ה"},{"text":"אגר\"מ","bold":true},{"text":" (יו\"ד ח\"T, מ) כתב שיש סוגי מאכלים מסוימים שאינם מוציאים אדים, כגון "},{"text":"חלה","italic":true},{"text":" או שאר תבשילים שאינם נוזליים. על פי זה, "},{"text":"חיי הלוי","bold":true},{"text":" (ח\"ג יו\"ד ע\"ט, ב) (33) פסק שאם אדם אפה בטעות "},{"text":"חלה","italic":true},{"text":" בלי לעטוף אותה בנייר אלומיניום, או אם הנייר העוטף נקרע במהלך האפייה, המאכלים האחרים בתנור מותרים. אולם, אם רשת התנור באה במגע ישיר עם ה"},{"text":"חלה","italic":true},{"text":" הגלויה, היא טעונה הכשרה על ידי ליבון. יש לציין שאחרונים רבים, כגון בספר "},{"text":"הפרשת חלה כהלכתה","bold":true},{"text":" (עמ' קה), חולקים על ר' משה ופוסקים שאפילו לחם מוציא אדים וכל האוכל שבתנור, וכן התנור עצמו, יהיו אסורים במקרה שנייר האלומיניום נקרע."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[33],"approved_hash":"42e82538d57e453ddccb4a0bb869bd05fad0c20ced2476b672b24b64d17645a1"},{"chunk_code":"HC1-E4","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"שריפת חלה באש של ביעור חמץ","chunk_summary":"דיון אם השורפים חמץ נהנים מתוספת האש של החלה; צדדי ההיתר הם שהאש כבר מספיקה ושמצוות לאו ליהנות ניתנו.","content_markdown":"<u>שריפת חמץ</u>\n\nכפי שהוזכר לעיל, אנשים רבים קונים מצות שעדיין לא הפרישו מהם *חלה* והם מפרישים בבית. אחר כך הם לוקחים את המצה המופרשת בתור *חלה* ומשליכים אותה למדורה המשמשת לשריפת חמץ בערב פסח. **חלקת בנימין** (שכב, ביאורים ד\"ה ונוהגין) (34) שואל האם יש לאסור מנהג זה מפני שכל אלו ששורפים את החמץ שלהם נהנים מריבוי האש מחמת ה*חלה* הנשרפת.\n\nהוא מציע, כפי שהוזכר לעיל (32), שאם האש כבר מאוד חמה, תוספת מעטה של חתיכת מצה לא מגבירה את האש במידה משמעותית, ולפיכך זה לא נחשב שנהנים מה*חלה*. בנוסף, אפילו אם המצה מגבירה את החום באופן משמעותי, יתכן שזה יהיה מותר בגלל הכלל ש\"מצוות לאו ליהנות נתנו\", ושריפת החמץ על ידי החום של ה*חלה* לא נחשבת הנאה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":110,"xmlIndex":116,"text":"שריפת חמץ","spans":[{"text":"שריפת חמץ","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":111,"xmlIndex":117,"text":"כפי שהוזכר לעיל, אנשים רבים קונים מצות שעדיין לא הפרישו מהם חלה והם מפרישים בבית. אחר כך הם לוקחים את המצה המופרשת בתור חלה ומשליכים אותה למדורה המשמשת לשריפת חמץ בערב פסח. חלקת בנימין (שכב, ביאורים ד\"ה ונוהגין) (34) שואל האם יש לאסור מנהג זה מפני שכל אלו ששורפים את החמץ שלהם נהנים מריבוי האש מחמת החלה הנשרפת.","spans":[{"text":"כפי שהוזכר לעיל, אנשים רבים קונים מצות שעדיין לא הפרישו מהם "},{"text":"חלה","italic":true},{"text":" והם מפרישים בבית. אחר כך הם לוקחים את המצה המופרשת בתור "},{"text":"חלה","italic":true},{"text":" ומשליכים אותה למדורה המשמשת לשריפת חמץ בערב פסח. "},{"text":"חלקת בנימין","bold":true},{"text":" (שכב, ביאורים ד\"ה ונוהגין) (34) שואל האם יש לאסור מנהג זה מפני שכל אלו ששורפים את החמץ שלהם נהנים מריבוי האש מחמת ה"},{"text":"חלה","italic":true},{"text":" הנשרפת."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":112,"xmlIndex":118,"text":"הוא מציע, כפי שהוזכר לעיל (32), שאם האש כבר מאוד חמה, תוספת מעטה של חתיכת מצה לא מגבירה את האש במידה משמעותית, ולפיכך זה לא נחשב שנהנים מהחלה. בנוסף, אפילו אם המצה מגבירה את החום באופן משמעותי, יתכן שזה יהיה מותר בגלל הכלל ש\"מצוות לאו ליהנות נתנו\", ושריפת החמץ על ידי החום של החלה לא נחשבת הנאה.","spans":[{"text":"הוא מציע, כפי שהוזכר לעיל (32), שאם האש כבר מאוד חמה, תוספת מעטה של חתיכת מצה לא מגבירה את האש במידה משמעותית, ולפיכך זה לא נחשב שנהנים מה"},{"text":"חלה","italic":true},{"text":". בנוסף, אפילו אם המצה מגבירה את החום באופן משמעותי, יתכן שזה יהיה מותר בגלל הכלל ש\"מצוות לאו ליהנות נתנו\", ושריפת החמץ על ידי החום של ה"},{"text":"חלה","italic":true},{"text":" לא נחשבת הנאה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[32,34],"approved_hash":"87aef0810dad2a3522c2d09035e4a8d334d1c16f2cfc23ec75fbbb75024b34b4"},{"chunk_code":"HC1-E5","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"השלכת חלה כשאין אפשרות לשרוף","chunk_summary":"לכתחילה שורפים את החלה; כשאי אפשר, הגר״ע יוסף ופוסקים נוספים דנים בהפרשת פחות מכזית ובהשלכתו כשהוא עטוף.","content_markdown":"<u>זריקת ה</u>*<u>חלה</u>*\n\nעל פי הגמרא שבת (31) ופסק השו\"ע והרמ\"א, נראה בבירור שיש לשרוף את ה*חלה* המופרשת. אמנם, יש כאלו שעוטפים את ה*חלה* וזורקים אותה, ומבססים את מנהגם על רש\"י בגמרא לעיל וה**חזון איש** (סוף קונטרס תרו\"מ ודמאי טו, א), שכתבו שאפשר להיפטר מתרומה בדרך זו, ואותו דבר יהיה נכון גם לגבי *חלה*. אולם, **מנחת יצחק** (ח\"ד, יג) חולק וסובר שהחזו\"א הקל רק לגבי תרומה, אבל לא לגבי *חלה* (ראה שם את טעם הדבר). אם כן, נראה שתמיד צריך לשרוף *חלה*.\n\nאף על פי כן, הגרע\"י ב**חזון עובדיה** (תרומות ומעשרות עמ' רכז) (35) פסק שהואיל ו*חלה* יכולה להיות בכל גודל שהוא (אפילו פחות מכזית), אם אין דרך לשרוף אותה, ראוי שאדם יפריש פחות מכזית, ישים בשקית פלסטיק, ויזרוק לפח. זה מבוסס על **מהר\"י אסאד** (יו\"ד, שנב) שפסק שהחיוב לשרוף *חלה* חל רק בשיעור כזית, אבל שיעור קטן מכזית אינו טעון שריפה. לכן, אם אין לך דרך לשרוף את ה*חלה*, או אם זה ערב שבת והתנור/הכיריים בשימוש, יש להפריש פחות מכזית. למעשה, המנחת יצחק (לעיל) ו**שש\"כ** (פמ\"ב הע' נג) כתבו שאם אין שום דרך לשרוף את ה*חלה*, ניתן לזרוק אותה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":113,"xmlIndex":119,"text":"זריקת החלה","spans":[{"text":"זריקת ה","underline":true},{"text":"חלה","italic":true,"underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":114,"xmlIndex":120,"text":"על פי הגמרא שבת (31) ופסק השו\"ע והרמ\"א, נראה בבירור שיש לשרוף את החלה המופרשת. אמנם, יש כאלו שעוטפים את החלה וזורקים אותה, ומבססים את מנהגם על רש\"י בגמרא לעיל והחזון איש (סוף קונטרס תרו\"מ ודמאי טו, א), שכתבו שאפשר להיפטר מתרומה בדרך זו, ואותו דבר יהיה נכון גם לגבי חלה. אולם, מנחת יצחק (ח\"ד, יג) חולק וסובר שהחזו\"א הקל רק לגבי תרומה, אבל לא לגבי חלה (ראה שם את טעם הדבר). אם כן, נראה שתמיד צריך לשרוף חלה.","spans":[{"text":"על פי הגמרא שבת (31) ופסק השו\"ע והרמ\"א, נראה בבירור שיש לשרוף את ה"},{"text":"חלה ","italic":true},{"text":"המופרשת. אמנם, יש כאלו שעוטפים את ה"},{"text":"חלה","italic":true},{"text":" וזורקים אותה, ומבססים את מנהגם על רש\"י בגמרא לעיל וה"},{"text":"חזון איש","bold":true},{"text":" (סוף קונטרס תרו\"מ ודמאי טו, א), שכתבו שאפשר להיפטר מתרומה בדרך זו, ואותו דבר יהיה נכון גם לגבי "},{"text":"חלה","italic":true},{"text":". אולם, "},{"text":"מנחת יצחק","bold":true},{"text":" (ח\"ד, יג) חולק וסובר שהחזו\"א הקל רק לגבי תרומה, אבל לא לגבי "},{"text":"חלה","italic":true},{"text":" (ראה שם את טעם הדבר). אם כן, נראה שתמיד צריך לשרוף "},{"text":"חלה","italic":true},{"text":"."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":115,"xmlIndex":121,"text":"אף על פי כן, הגרע\"י בחזון עובדיה (תרומות ומעשרות עמ' רכז) (35) פסק שהואיל וחלה יכולה להיות בכל גודל שהוא (אפילו פחות מכזית), אם אין דרך לשרוף אותה, ראוי שאדם יפריש פחות מכזית, ישים בשקית פלסטיק, ויזרוק לפח. זה מבוסס על מהר\"י אסאד (יו\"ד, שנב) שפסק שהחיוב לשרוף חלה חל רק בשיעור כזית, אבל שיעור קטן מכזית אינו טעון שריפה. לכן, אם אין לך דרך לשרוף את החלה, או אם זה ערב שבת והתנור/הכיריים בשימוש, יש להפריש פחות מכזית. למעשה, המנחת יצחק (לעיל) ושש\"כ (פמ\"ב הע' נג) כתבו שאם אין שום דרך לשרוף את החלה, ניתן לזרוק אותה.","spans":[{"text":"אף על פי כן, הגרע\"י ב"},{"text":"חזון עובדיה","bold":true},{"text":" (תרומות ומעשרות עמ' רכז) (35) פסק שהואיל ו"},{"text":"חלה ","italic":true},{"text":"יכולה להיות בכל גודל שהוא (אפילו פחות מכזית), אם אין דרך לשרוף אותה, ראוי שאדם יפריש פחות מכזית, ישים בשקית פלסטיק, ויזרוק לפח. זה מבוסס על "},{"text":"מהר\"י אסאד","bold":true},{"text":" (יו\"ד, שנב) שפסק שהחיוב לשרוף "},{"text":"חלה","italic":true},{"text":" חל רק בשיעור כזית, אבל שיעור קטן מכזית אינו טעון שריפה. לכן, אם אין לך דרך לשרוף את ה"},{"text":"חלה","italic":true},{"text":", או אם זה ערב שבת והתנור/הכיריים בשימוש, יש להפריש פחות מכזית. למעשה, המנחת יצחק (לעיל) ו"},{"text":"שש\"כ","bold":true},{"text":" (פמ\"ב הע' נג) כתבו שאם אין שום דרך לשרוף את ה"},{"text":"חלה","italic":true},{"text":", ניתן לזרוק אותה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[31,35],"approved_hash":"a32c9715610e58727cc0d1d02a37d229be24f94e1efa3c0fafacdce677c8fb28"},{"chunk_code":"HC1-E6","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"האם חייבים לשרוף את החלה מיד","chunk_summary":"יש המחייבים שריפה מיידית מחשש תקלה, ואחרים מתירים לשמור או להקפיא בשקית מיוחדת; למעשה עדיף לשרוף בסמוך להפרשה.","content_markdown":"<u>שריפת</u> *<u>חלה</u>* <u>מיד</u>\n\nהאם יש חיוב לשרוף את ה*חלה* מיד, או שאפשר לחכות ולשרוף אותה במועד מאוחר יותר? ה**חלה כהלכתה** (סימן א, יב שיח הארץ) (36) פסק שיש לשרוף את ה*חלה* מיד כדי למנוע אפשרות של הנאה ממנה בטעות. הוא מסביר שלמרות שהרמ\"א, ש\"ך וט\"ז התירו להשאיר תרומה ברשותו של האדם לפני שהוא שורף אותה, *חלה* מצויה יותר, ויש לשרוף אותה מיד.\n\nאמנם, נראה מה**גר\"א** (שלא סקמ\"ב) שאין בעיה להשאיר *חלה*.[26] **חלה כהלכתה** (סימן א סק\"מ) (37) כתב שיש שנהגו להקפיא את ה*חלה* שלהם ולשרוף אותה בשעת ביעור חמץ, אבל כדי למנוע טעויות של הנאה ממנה, יש לשים אותה בשקית מיוחדת. בנוסף, כאשר שורפים *חל*ה בערב פסח, יש להיזהר להוציא את ה*חלה* מהמקפיא מוקדם מפני שאם הוא יזרוק אותה לאש כשהיא עדיין קפואה, יש סיכוי סביר שהיא תישרף רק מבחוץ.\n\nלמעשה, נראה שמן הראוי לשרוף את ה*חלה* מיד אחרי ההפרשה.\n\nSource Notes\n\n[26]:  הגר\"א כתב שהואיל ו\"אין שום תרומה נאכלת\", מותר להשאיר בבית את כל סוגי התרומה (כולל *חלה*).","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":116,"xmlIndex":122,"text":"שריפת חלה מיד","spans":[{"text":"שריפת ","underline":true},{"text":"חלה","italic":true,"underline":true},{"text":" מיד","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":117,"xmlIndex":123,"text":"האם יש חיוב לשרוף את החלה מיד, או שאפשר לחכות ולשרוף אותה במועד מאוחר יותר? החלה כהלכתה (סימן א, יב שיח הארץ) (36) פסק שיש לשרוף את החלה מיד כדי למנוע אפשרות של הנאה ממנה בטעות. הוא מסביר שלמרות שהרמ\"א, ש\"ך וט\"ז התירו להשאיר תרומה ברשותו של האדם לפני שהוא שורף אותה, חלה מצויה יותר, ויש לשרוף אותה מיד.","spans":[{"text":"האם יש חיוב לשרוף את ה"},{"text":"חלה","italic":true},{"text":" מיד, או שאפשר לחכות ולשרוף אותה במועד מאוחר יותר? ה"},{"text":"חלה כהלכתה","bold":true},{"text":" (סימן א, יב שיח הארץ) (36) פסק שיש לשרוף את ה"},{"text":"חלה","italic":true},{"text":" מיד כדי למנוע אפשרות של הנאה ממנה בטעות. הוא מסביר שלמרות שהרמ\"א, ש\"ך וט\"ז התירו להשאיר תרומה ברשותו של האדם לפני שהוא שורף אותה, "},{"text":"חלה","italic":true},{"text":" מצויה יותר, ויש לשרוף אותה מיד."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":118,"xmlIndex":124,"text":"אמנם, נראה מהגר\"א (שלא סקמ\"ב) שאין בעיה להשאיר חלה.[26] חלה כהלכתה (סימן א סק\"מ) (37) כתב שיש שנהגו להקפיא את החלה שלהם ולשרוף אותה בשעת ביעור חמץ, אבל כדי למנוע טעויות של הנאה ממנה, יש לשים אותה בשקית מיוחדת. בנוסף, כאשר שורפים חלה בערב פסח, יש להיזהר להוציא את החלה מהמקפיא מוקדם מפני שאם הוא יזרוק אותה לאש כשהיא עדיין קפואה, יש סיכוי סביר שהיא תישרף רק מבחוץ.","spans":[{"text":"אמנם, נראה מה"},{"text":"גר\"א","bold":true},{"text":" (שלא סקמ\"ב) שאין בעיה להשאיר "},{"text":"חלה","italic":true},{"text":"."},{"text":"[26]","footnote":26},{"text":" "},{"text":"חלה כהלכתה","bold":true},{"text":" (סימן א סק\"מ) (37) כתב שיש שנהגו להקפיא את ה"},{"text":"חלה","italic":true},{"text":" שלהם ולשרוף אותה בשעת ביעור חמץ, אבל כדי למנוע טעויות של הנאה ממנה, יש לשים אותה בשקית מיוחדת. בנוסף, כאשר שורפים "},{"text":"חל","italic":true},{"text":"ה בערב פסח, יש להיזהר להוציא את ה"},{"text":"חלה","italic":true},{"text":" מהמקפיא מוקדם מפני שאם הוא יזרוק אותה לאש כשהיא עדיין קפואה, יש סיכוי סביר שהיא תישרף רק מבחוץ."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[26],"defaultTabWidth":36},{"kind":"paragraph","paragraph":119,"xmlIndex":125,"text":"למעשה, נראה שמן הראוי לשרוף את החלה מיד אחרי ההפרשה.","spans":[{"text":"למעשה, נראה שמן הראוי לשרוף את ה"},{"text":"חלה","italic":true},{"text":" מיד אחרי ההפרשה."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":26,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" הגר\"א כתב שהואיל ו\"אין שום תרומה נאכלת\", מותר להשאיר בבית את כל סוגי התרומה (כולל חלה).","spans":[{"text":" הגר\"א כתב שהואיל ו\"אין שום תרומה נאכלת\", מותר להשאיר בבית את כל סוגי התרומה (כולל "},{"text":"חלה","italic":true},{"text":")."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[36,37],"approved_hash":"5b9355bd2cb8127176c60c5cd167419e99bf1a35dabb65dcda02f871b5156a35"},{"chunk_code":"HC1-E7","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"שימוש במזלג בעת שריפת החלה","chunk_summary":"מזלג שנתחב בחלה שטרם נשרפה כראוי עלול להיאסר ולהצריך ליבון; עדיף להשתמש במלקחיים להוצאת חלה עטופה.","content_markdown":"<u>מזלג</u>\n\n**אמרי יעקב** (ארץ ישראל סימן ב, ילקוטים סקמ\"ג) (38) כתב שכאשר שורפים *חלה* בתנור, יש לוודא לא לתחוב בה מזלג כדי לוודא שהיא נשרפה לגמרי, מפני שאם היא לא, המזלג יבלע טעם אסור מה*חלה* וייאסר. הוא כתב שאם אכן המזלג נאסר מחמת שננעץ ב*חלה*, הואיל והוא בלע את הטעם על ידי חום יבש בתוך התנור, הגעלה לא תספיק ויהיה צורך לעשות ליבון במזלג. הדרך הטובה ביותר להוציא *חלה* עטופה היא על ידי מלקחיים. הואיל וה*חלה* עטופה בעטיפה כפולה, מותר אף להשתמש במלקחיים הרגילות שלך, שכן טעם אינו עובר דרך 2 שכבות של נייר אלומיניום (כפי שלמדנו ב'זמן' הקודם ב'סמיכת חבר' ונעסוק בזה בהמשך, לגבי 2 סירים שנוגעים זה בזה).","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":120,"xmlIndex":126,"text":"מזלג","spans":[{"text":"מזלג","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":121,"xmlIndex":127,"text":"אמרי יעקב (ארץ ישראל סימן ב, ילקוטים סקמ\"ג) (38) כתב שכאשר שורפים חלה בתנור, יש לוודא לא לתחוב בה מזלג כדי לוודא שהיא נשרפה לגמרי, מפני שאם היא לא, המזלג יבלע טעם אסור מהחלה וייאסר. הוא כתב שאם אכן המזלג נאסר מחמת שננעץ בחלה, הואיל והוא בלע את הטעם על ידי חום יבש בתוך התנור, הגעלה לא תספיק ויהיה צורך לעשות ליבון במזלג. הדרך הטובה ביותר להוציא חלה עטופה היא על ידי מלקחיים. הואיל והחלה עטופה בעטיפה כפולה, מותר אף להשתמש במלקחיים הרגילות שלך, שכן טעם אינו עובר דרך 2 שכבות של נייר אלומיניום (כפי שלמדנו ב'זמן' הקודם ב'סמיכת חבר' ונעסוק בזה בהמשך, לגבי 2 סירים שנוגעים זה בזה).","spans":[{"text":"אמרי יעקב","bold":true},{"text":" (ארץ ישראל סימן ב, ילקוטים סקמ\"ג) (38) כתב שכאשר שורפים "},{"text":"חלה","italic":true},{"text":" בתנור, יש לוודא לא לתחוב בה מזלג כדי לוודא שהיא נשרפה לגמרי, מפני שאם היא לא, המזלג יבלע טעם אסור מה"},{"text":"חלה ","italic":true},{"text":"וייאסר. הוא כתב שאם אכן המזלג נאסר מחמת שננעץ ב"},{"text":"חלה","italic":true},{"text":", הואיל והוא בלע את הטעם על ידי חום יבש בתוך התנור, הגעלה לא תספיק ויהיה צורך לעשות ליבון במזלג. הדרך הטובה ביותר להוציא "},{"text":"חלה","italic":true},{"text":" עטופה היא על ידי מלקחיים. הואיל וה"},{"text":"חלה","italic":true},{"text":" עטופה בעטיפה כפולה, מותר אף להשתמש במלקחיים הרגילות שלך, שכן טעם אינו עובר דרך 2 שכבות של נייר אלומיניום (כפי שלמדנו ב'זמן' הקודם ב'סמיכת חבר' ונעסוק בזה בהמשך, לגבי 2 סירים שנוגעים זה בזה)."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[38],"approved_hash":"0219daa63610dc1b4b28074657ea777a291d670959516d137165cf733acbc4b2"},{"chunk_code":"HC1-E8","source_type":"notes","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"שריפת חלה על הכיריים","chunk_summary":"עדיף להניח נייר כסף מתחת לחלה; נידון אם החצובות בולעות איסור וצריכות ליבון, ולפי הרב משה יש צד להקל כשהחלה עטופה.","content_markdown":"<u>שריפה על גבי כיריים</u>\n\nיש שנהגו לשרוף את ה*חלה* על הכיריים. למרות שבעיקרון, אפשר לשרוף את ה*חלה* ישירות על גבי החצובות, עדיף לתת את ה*חלה* על חתיכת נייר אלומיניום, משתי סיבות: 1) למנוע מהחצובות להתלכלך; 2) קובץ מבית לוי פסק שהחצובות נעשות אסורות. ונבאר:\n\n**קובץ מבית לוי** (ח\"א, עמ' כט) (39) הביא את המשנ\"ב בהלכות פסח, שפסק שבשביל פסח, חצובות לא טעונות ליבון משתי סיבות: 1) אפילו אם החצובות בלעו חמץ, טעם החמץ לא יכול לעבור  לסיר שמונח עליהן. טעם הדבר הוא שזה כמו 2 סירים שנוגעים זה בזה (מבחוץ), שהטעם אינו עובר מאחד לשני אלא אם כן יש לחות ביניהם (או בין החצובה לסיר). 2) כל טעם חמץ שנבלע בחצובות נשרף מיד על ידי הלהבות שמלמטה. הקובץ מבית לוי מבאר שהסיבה השנייה של המשנ\"ב שייכת רק בזמן המשנ\"ב אז החצובות היו ישירות על גבי האש, אבל בכיריים בימינו החצובות מוגבהות מעל גבי האש. כתוצאה מכך, אפילו אם הלהבות באות במגע עם החצובות, זה רק בחלק קטן מהחצובות. לכן, קובץ מבית לוי פסק שבערב פסח אדם צריך לעשות ליבון לחצובות. בדומה לזה, לגבי *חלה*, אדם צריך להיזהר לא לשרוף את ה*חלה* ישירות על החצובות.[27] גם הרב אלישיב באשרי האיש (יו\"ד ח\"ב עמ' קסה) פסק שאין לשרוף את ה*חלה* על החצובות.\n\nה**אגר\"מ** יו\"ד (ח\"א, קכד) פסק שלא צריך חצובות נפרדות לבשרי ולחלבי. לכאורה, הוא יסבור שאם אתה עוטף את ה*חלה* בנייר כסף, אתה יכול לשרוף אותה ישירות על החצובות, כמו כל סיר של בשרי וחלבי ששמים ישירות על החצובות.\n\nSource Notes\n\n[27]:  על פי זה, הוא גם מחמיר שיהיו חצובות נפרדות לבשרי ולחלבי.","content_document":{"version":1,"language":"he","blocks":[{"kind":"paragraph","paragraph":122,"xmlIndex":128,"text":"שריפה על גבי כיריים","spans":[{"text":"שריפה על גבי כיריים","underline":true}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":123,"xmlIndex":129,"text":"יש שנהגו לשרוף את החלה על הכיריים. למרות שבעיקרון, אפשר לשרוף את החלה ישירות על גבי החצובות, עדיף לתת את החלה על חתיכת נייר אלומיניום, משתי סיבות: 1) למנוע מהחצובות להתלכלך; 2) קובץ מבית לוי פסק שהחצובות נעשות אסורות. ונבאר:","spans":[{"text":"יש שנהגו לשרוף את ה"},{"text":"חלה","italic":true},{"text":" על הכיריים. למרות שבעיקרון, אפשר לשרוף את ה"},{"text":"חלה","italic":true},{"text":" ישירות על גבי החצובות, עדיף לתת את ה"},{"text":"חלה","italic":true},{"text":" על חתיכת נייר אלומיניום, משתי סיבות: 1) למנוע מהחצובות להתלכלך; 2) קובץ מבית לוי פסק שהחצובות נעשות אסורות. ונבאר:"}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"paragraph","paragraph":124,"xmlIndex":130,"text":"קובץ מבית לוי (ח\"א, עמ' כט) (39) הביא את המשנ\"ב בהלכות פסח, שפסק שבשביל פסח, חצובות לא טעונות ליבון משתי סיבות: 1) אפילו אם החצובות בלעו חמץ, טעם החמץ לא יכול לעבור  לסיר שמונח עליהן. טעם הדבר הוא שזה כמו 2 סירים שנוגעים זה בזה (מבחוץ), שהטעם אינו עובר מאחד לשני אלא אם כן יש לחות ביניהם (או בין החצובה לסיר). 2) כל טעם חמץ שנבלע בחצובות נשרף מיד על ידי הלהבות שמלמטה. הקובץ מבית לוי מבאר שהסיבה השנייה של המשנ\"ב שייכת רק בזמן המשנ\"ב אז החצובות היו ישירות על גבי האש, אבל בכיריים בימינו החצובות מוגבהות מעל גבי האש. כתוצאה מכך, אפילו אם הלהבות באות במגע עם החצובות, זה רק בחלק קטן מהחצובות. לכן, קובץ מבית לוי פסק שבערב פסח אדם צריך לעשות ליבון לחצובות. בדומה לזה, לגבי חלה, אדם צריך להיזהר לא לשרוף את החלה ישירות על החצובות.[27] גם הרב אלישיב באשרי האיש (יו\"ד ח\"ב עמ' קסה) פסק שאין לשרוף את החלה על החצובות.","spans":[{"text":"קובץ מבית לוי","bold":true},{"text":" (ח\"א, עמ' כט) (39) הביא את המשנ\"ב בהלכות פסח, שפסק שבשביל פסח, חצובות לא טעונות ליבון משתי סיבות: 1) אפילו אם החצובות בלעו חמץ, טעם החמץ לא יכול לעבור  לסיר שמונח עליהן. טעם הדבר הוא שזה כמו 2 סירים שנוגעים זה בזה (מבחוץ), שהטעם אינו עובר מאחד לשני אלא אם כן יש לחות ביניהם (או בין החצובה לסיר). 2) כל טעם חמץ שנבלע בחצובות נשרף מיד על ידי הלהבות שמלמטה. הקובץ מבית לוי מבאר שהסיבה השנייה של המשנ\"ב שייכת רק בזמן המשנ\"ב אז החצובות היו ישירות על גבי האש, אבל בכיריים בימינו החצובות מוגבהות מעל גבי האש. כתוצאה מכך, אפילו אם הלהבות באות במגע עם החצובות, זה רק בחלק קטן מהחצובות. לכן, קובץ מבית לוי פסק שבערב פסח אדם צריך לעשות ליבון לחצובות. בדומה לזה, לגבי "},{"text":"חלה","italic":true},{"text":", אדם צריך להיזהר לא לשרוף את ה"},{"text":"חלה","italic":true},{"text":" ישירות על החצובות."},{"text":"[27]","footnote":27},{"text":" גם הרב אלישיב באשרי האיש (יו\"ד ח\"ב עמ' קסה) פסק שאין לשרוף את ה"},{"text":"חלה","italic":true},{"text":" על החצובות."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[27],"defaultTabWidth":36},{"kind":"paragraph","paragraph":125,"xmlIndex":131,"text":"האגר\"מ יו\"ד (ח\"א, קכד) פסק שלא צריך חצובות נפרדות לבשרי ולחלבי. לכאורה, הוא יסבור שאם אתה עוטף את החלה בנייר כסף, אתה יכול לשרוף אותה ישירות על החצובות, כמו כל סיר של בשרי וחלבי ששמים ישירות על החצובות.","spans":[{"text":"ה"},{"text":"אגר\"מ","bold":true},{"text":" יו\"ד (ח\"א, קכד) פסק שלא צריך חצובות נפרדות לבשרי ולחלבי. לכאורה, הוא יסבור שאם אתה עוטף את ה"},{"text":"חלה","italic":true},{"text":" בנייר כסף, אתה יכול לשרוף אותה ישירות על החצובות, כמו כל סיר של בשרי וחלבי ששמים ישירות על החצובות."}],"marker":"","level":0,"indent":0,"firstLine":36,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[{"id":27,"blocks":[{"kind":"paragraph","paragraph":0,"xmlIndex":0,"text":" על פי זה, הוא גם מחמיר שיהיו חצובות נפרדות לבשרי ולחלבי.","spans":[{"text":" על פי זה, הוא גם מחמיר שיהיו חצובות נפרדות לבשרי ולחלבי."}],"marker":"","level":0,"indent":0,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}]}]},"question_document":null,"source_file_name":"סיכום הלכות הפרשת חלה - חלק א.docx","source_numbers":[39],"approved_hash":"347c2dff39064bcaa17864349a2cc307f18367daa10694a081f6ad153ef25130"},{"chunk_code":"HC1-Q1","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"א","chunk_title":"חיוב הפרשת חלה מן התורה או מדרבנן","chunk_summary":"האם מצוות הפרשת חלה היא דאורייתא או דרבנן?","content_markdown":"1) האם מצוות הפרשת *חלה* היא דאורייתא או דרבנן?\n\nהשו\"ע ב**סעיף א'** פסק שמצוות הפרשת *חלה* היא דאורייתא, אבל ב**סעיף ב'** הוא הבהיר שהיא דאורייתא רק בארץ ישראל בזמן שכל עם ישראל מתגוררים בה. ב**סעיף ג'** הוא הוסיף שבחו\"ל, המצווה היא דרבנן ונתקנה כדי שלא תישכח מצוות *חלה*.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":2,"xmlIndex":2,"text":"האם מצוות הפרשת חלה היא דאורייתא או דרבנן?","spans":[{"text":"האם מצוות הפרשת "},{"text":"חלה","italic":true},{"text":" היא דאורייתא או דרבנן?"}],"marker":"1)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":3,"xmlIndex":4,"text":"השו\"ע בסעיף א' פסק שמצוות הפרשת חלה היא דאורייתא, אבל בסעיף ב' הוא הבהיר שהיא דאורייתא רק בארץ ישראל בזמן שכל עם ישראל מתגוררים בה. בסעיף ג' הוא הוסיף שבחו\"ל, המצווה היא דרבנן ונתקנה כדי שלא תישכח מצוות חלה.","spans":[{"text":"השו\"ע ב","color":"#C00000"},{"text":"סעיף א'","bold":true,"color":"#C00000"},{"text":" פסק שמצוות הפרשת ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" היא דאורייתא, אבל ב","color":"#C00000"},{"text":"סעיף ב'","bold":true,"color":"#C00000"},{"text":" הוא הבהיר שהיא דאורייתא רק בארץ ישראל בזמן שכל עם ישראל מתגוררים בה. ב","color":"#C00000"},{"text":"סעיף ג'","bold":true,"color":"#C00000"},{"text":" הוא הוסיף שבחו\"ל, המצווה היא דרבנן ונתקנה כדי שלא תישכח מצוות ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":".","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":2,"xmlIndex":2,"text":"האם מצוות הפרשת חלה היא דאורייתא או דרבנן? _________________________________","spans":[{"text":"האם מצוות הפרשת "},{"text":"חלה","italic":true},{"text":" היא דאורייתא או דרבנן? _________________________________"}],"marker":"1)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":3,"xmlIndex":3,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[],"approved_hash":"e60dee3e1c7777bd61be38e73472b10a822b485a8e568c419c804da8f0635303"},{"chunk_code":"HC1-Q2","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ב","chunk_title":"רוב יהודי העולם בארץ ישראל","chunk_summary":"לפי הלשכה המרכזית לסטטיסטיקה, בערך 46% מהיהודים מתגוררים בארץ ישראל. אולם, מתוך כ-6 מיליון יהודים שגרים בארה\"ב, 37% הם רפורמים, ורבים מהם גרים (או שאימם התגיירה) ואינם יהודים על פי דין. נמצא, שיתכן שבימינו, רוב היהודים כבר גרים בארץ ישראל. האם זה משפיע על המצווה של הפרשת חלה?","content_markdown":"2) לפי הלשכה המרכזית לסטטיסטיקה, בערך 46% מהיהודים מתגוררים בארץ ישראל. אולם, מתוך כ-6 מיליון יהודים שגרים בארה\"ב, 37% הם רפורמים, ורבים מהם גרים (או שאימם התגיירה) ואינם יהודים על פי דין. נמצא, שיתכן שבימינו, רוב היהודים כבר גרים בארץ ישראל. האם זה משפיע על המצווה של הפרשת *חלה*?\n\nה**ריטב\"א** (5) פסק שאפילו אם רוב היהודים גרים בארץ ישראל ולא כולם, מצוות הפרשת *חלה* היא דאורייתא. **באר בשדה** (6) מוכיח שאפילו בתחילה כשעם ישראל נכנסו לא\"י, רק רובם נכנסו ולא כולם, הואיל ועדיין השבטים ראובן, גד וחצי מנשה נשארו מעבר לירדן, ובכל זאת מצוות הפרשת *חלה* הייתה דאורייתא. ה**חזון איש** (7) חולק וסובר שכדי ש*חלה* תהיה דאורייתא צריך שרוב ישראל יכנסו לארץ על פי הוראה מה', באמצעות נביא או מלך. בימינו, הואיל ורוב היהודים נכנסו בלי הוראה ישירה של מלך או נביא, המצווה נשארת דרבנן.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":4,"xmlIndex":6,"text":"לפי הלשכה המרכזית לסטטיסטיקה, בערך 46% מהיהודים מתגוררים בארץ ישראל. אולם, מתוך כ-6 מיליון יהודים שגרים בארה\"ב, 37% הם רפורמים, ורבים מהם גרים (או שאימם התגיירה) ואינם יהודים על פי דין. נמצא, שיתכן שבימינו, רוב היהודים כבר גרים בארץ ישראל. האם זה משפיע על המצווה של הפרשת חלה?","spans":[{"text":"לפי הלשכה המרכזית לסטטיסטיקה, בערך 46% מהיהודים מתגוררים בארץ ישראל. אולם, מתוך כ-6 מיליון יהודים שגרים בארה\"ב, 37% הם רפורמים, ורבים מהם גרים (או שאימם התגיירה) ואינם יהודים על פי דין. נמצא, שיתכן שבימינו, רוב היהודים כבר גרים בארץ ישראל. האם זה משפיע על המצווה של הפרשת "},{"text":"חלה","italic":true},{"text":"?"}],"marker":"2)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":5,"xmlIndex":8,"text":"הריטב\"א (5) פסק שאפילו אם רוב היהודים גרים בארץ ישראל ולא כולם, מצוות הפרשת חלה היא דאורייתא. באר בשדה (6) מוכיח שאפילו בתחילה כשעם ישראל נכנסו לא\"י, רק רובם נכנסו ולא כולם, הואיל ועדיין השבטים ראובן, גד וחצי מנשה נשארו מעבר לירדן, ובכל זאת מצוות הפרשת חלה הייתה דאורייתא. החזון איש (7) חולק וסובר שכדי שחלה תהיה דאורייתא צריך שרוב ישראל יכנסו לארץ על פי הוראה מה', באמצעות נביא או מלך. בימינו, הואיל ורוב היהודים נכנסו בלי הוראה ישירה של מלך או נביא, המצווה נשארת דרבנן.","spans":[{"text":"ה","color":"#C00000"},{"text":"ריטב\"א","bold":true,"color":"#C00000"},{"text":" (5) פסק שאפילו אם רוב היהודים גרים בארץ ישראל ולא כולם, מצוות הפרשת ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" היא דאורייתא. ","color":"#C00000"},{"text":"באר בשדה","bold":true,"color":"#C00000"},{"text":" (6) מוכיח שאפילו בתחילה כשעם ישראל נכנסו לא\"י, רק רובם נכנסו ולא כולם, הואיל ועדיין השבטים ראובן, גד וחצי מנשה נשארו מעבר לירדן, ובכל זאת מצוות הפרשת ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" הייתה דאורייתא. ה","color":"#C00000"},{"text":"חזון איש","bold":true,"color":"#C00000"},{"text":" (7) חולק וסובר שכדי ש","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" תהיה דאורייתא צריך שרוב ישראל יכנסו לארץ על פי הוראה מה', באמצעות נביא או מלך. בימינו, הואיל ורוב היהודים נכנסו בלי הוראה ישירה של מלך או נביא, המצווה נשארת דרבנן.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":4,"xmlIndex":4,"text":"לפי הלשכה המרכזית לסטטיסטיקה, בערך 46% מהיהודים מתגוררים בארץ ישראל. אולם, מתוך כ-6 מיליון יהודים שגרים בארה\"ב, 37% הם רפורמים, ורבים מהם גרים (או שאימם התגיירה) ואינם יהודים על פי דין. נמצא, שיתכן שבימינו, רוב היהודים כבר גרים בארץ ישראל. האם זה משפיע על המצווה של הפרשת חלה? _________________________________________________","spans":[{"text":"לפי הלשכה המרכזית לסטטיסטיקה, בערך 46% מהיהודים מתגוררים בארץ ישראל. אולם, מתוך כ-6 מיליון יהודים שגרים בארה\"ב, 37% הם רפורמים, ורבים מהם גרים (או שאימם התגיירה) ואינם יהודים על פי דין. נמצא, שיתכן שבימינו, רוב היהודים כבר גרים בארץ ישראל. האם זה משפיע על המצווה של הפרשת "},{"text":"חלה","italic":true},{"text":"? _________________________________________________"}],"marker":"2)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":5,"xmlIndex":5,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[5,6,7],"approved_hash":"b0919bbe06661a0502327ccc40e130e11a53cbddb0bd0d702d892b10c2d1d4f4"},{"chunk_code":"HC1-Q3","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ב","chunk_title":"השפעת רוב ישראל בארץ על שמיטה ותרומה","chunk_summary":"אם רוב היהודים גרים בארץ ישראל, מה יהיה המעמד של שנת השמיטה הבאה? האם יהיה צד להקל לסמוך על היתר מכירה? הם יש השפעה על מצות תרומה בימינו?","content_markdown":"3) אם רוב היהודים גרים בארץ ישראל, מה יהיה המעמד של שנת השמיטה הבאה? האם יהיה צד להקל לסמוך על היתר מכירה? הם יש השפעה על מצות תרומה בימינו?\n\nלגבי שמיטה, ה**רמב\"ם** (4) פסק ששמיטה תהיה חיוב דאורייתא רק כשמצוות יובל תהיה דאורייתא. כדי שיובל יהיה דאורייתא צריך שרוב ישראל יכנסו לארץ ישראל ויתיישבו בנחלת אבותיהם המיועדת להם על פי השבט שלהם. אם כן, רק כאשר יבוא המשיח ויגלה לכל אחד את שבטו, עם ישראל יוכלו להתיישב בשטח המיועד להם ושמיטה תהיה דאורייתא.\n\nלגבי תרומה, ה**ראב\"ד** (8) פסק שהחיוב הוא דאורייתא אפילו בלי רוב ישראל גרים בארץ. לעומת זאת, ה**רמב\"ם** (8) מדמה את זה ל*חלה* ופוסק שזה יהיה דאורייתא רק כאשר רוב עם ישראל יגורו בארץ ישראל. ה**חזון איש** (9) כתב שבניגוד להפרשת *חלה*, אפילו הרמב\"ם מסכים שלגבי תרומה, כל עוד רוב היהודים גרים בא\"י, אפילו בלי הוראת מלך או נביא, המצווה נעשית דאורייתא. אולם, **ר' חיים קנייבסקי** (10) טוען שהואיל ו-10 השבטים אבדו, אפילו אם כל היהודים יבואו בימינו לא\"י, רוב היהודים (דהיינו, 10 השבטים) עדיין בחו\"ל, ולפיכך תרומה תישאר דרבנן עד ביאת המשיח.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":6,"xmlIndex":10,"text":"אם רוב היהודים גרים בארץ ישראל, מה יהיה המעמד של שנת השמיטה הבאה? האם יהיה צד להקל לסמוך על היתר מכירה? הם יש השפעה על מצות תרומה בימינו?","spans":[{"text":"אם רוב היהודים גרים בארץ ישראל, מה יהיה המעמד של שנת השמיטה הבאה? האם יהיה צד להקל לסמוך על היתר מכירה? הם יש השפעה על מצות תרומה בימינו?"}],"marker":"3)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":7,"xmlIndex":12,"text":"לגבי שמיטה, הרמב\"ם (4) פסק ששמיטה תהיה חיוב דאורייתא רק כשמצוות יובל תהיה דאורייתא. כדי שיובל יהיה דאורייתא צריך שרוב ישראל יכנסו לארץ ישראל ויתיישבו בנחלת אבותיהם המיועדת להם על פי השבט שלהם. אם כן, רק כאשר יבוא המשיח ויגלה לכל אחד את שבטו, עם ישראל יוכלו להתיישב בשטח המיועד להם ושמיטה תהיה דאורייתא.","spans":[{"text":"לגבי שמיטה, ה","color":"#C00000"},{"text":"רמב\"ם","bold":true,"color":"#C00000"},{"text":" (4) פסק ששמיטה תהיה חיוב דאורייתא רק כשמצוות יובל תהיה דאורייתא. כדי שיובל יהיה דאורייתא צריך שרוב ישראל יכנסו לארץ ישראל ויתיישבו בנחלת אבותיהם המיועדת להם על פי השבט שלהם. אם כן, רק כאשר יבוא המשיח ויגלה לכל אחד את שבטו, עם ישראל יוכלו להתיישב בשטח המיועד להם ושמיטה תהיה דאורייתא.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"answer","paragraph":8,"xmlIndex":14,"text":"לגבי תרומה, הראב\"ד (8) פסק שהחיוב הוא דאורייתא אפילו בלי רוב ישראל גרים בארץ. לעומת זאת, הרמב\"ם (8) מדמה את זה לחלה ופוסק שזה יהיה דאורייתא רק כאשר רוב עם ישראל יגורו בארץ ישראל. החזון איש (9) כתב שבניגוד להפרשת חלה, אפילו הרמב\"ם מסכים שלגבי תרומה, כל עוד רוב היהודים גרים בא\"י, אפילו בלי הוראת מלך או נביא, המצווה נעשית דאורייתא. אולם, ר' חיים קנייבסקי (10) טוען שהואיל ו-10 השבטים אבדו, אפילו אם כל היהודים יבואו בימינו לא\"י, רוב היהודים (דהיינו, 10 השבטים) עדיין בחו\"ל, ולפיכך תרומה תישאר דרבנן עד ביאת המשיח.","spans":[{"text":"לגבי תרומה, ה","color":"#C00000"},{"text":"ראב\"ד","bold":true,"color":"#C00000"},{"text":" (8) פסק שהחיוב הוא דאורייתא אפילו בלי רוב ישראל גרים בארץ. לעומת זאת, ה","color":"#C00000"},{"text":"רמב\"ם","bold":true,"color":"#C00000"},{"text":" (8) מדמה את זה ל","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" ופוסק שזה יהיה דאורייתא רק כאשר רוב עם ישראל יגורו בארץ ישראל. ה","color":"#C00000"},{"text":"חזון איש","bold":true,"color":"#C00000"},{"text":" (9) כתב שבניגוד להפרשת ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":", אפילו הרמב\"ם מסכים שלגבי תרומה, כל עוד רוב היהודים גרים בא\"י, אפילו בלי הוראת מלך או נביא, המצווה נעשית דאורייתא. אולם, ","color":"#C00000"},{"text":"ר' חיים קנייבסקי","bold":true,"color":"#C00000"},{"text":" (10) טוען שהואיל ו-10 השבטים אבדו, אפילו אם כל היהודים יבואו בימינו לא\"י, רוב היהודים (דהיינו, 10 השבטים) עדיין בחו\"ל, ולפיכך תרומה תישאר דרבנן עד ביאת המשיח.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":6,"xmlIndex":6,"text":"אם רוב היהודים גרים בארץ ישראל, מה יהיה המעמד של שנת השמיטה הבאה? האם יהיה צד להקל לסמוך על היתר מכירה? הם יש השפעה על מצות תרומה בימינו? _______________________","spans":[{"text":"אם רוב היהודים גרים בארץ ישראל, מה יהיה המעמד של שנת השמיטה הבאה? האם יהיה צד להקל לסמוך על היתר מכירה? הם יש השפעה על מצות תרומה בימינו? _______________________"}],"marker":"3)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":7,"xmlIndex":7,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[4,8,9,10],"approved_hash":"b63cc9527075c41670c73ff05eceb603d03cd3cfa1e5b58b1de75da4afcf9b78"},{"chunk_code":"HC1-Q4","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שכחו להפריש חלה לפני שבת","chunk_summary":"סיפור אמיתי: אשתך הכינה את החלות הטעימות ביותר לכבוד שבת, אבל היא שכחה להפריש חלה – האם מותר לאכול את החלה?","content_markdown":"4) סיפור אמיתי: אשתך הכינה את החלות הטעימות ביותר לכבוד שבת, אבל היא שכחה להפריש *חלה* – האם מותר לאכול את החלה?\n\nהשו\"ע (11) פסק שבחו\"ל מותר לאכול את ה*חלה* ולהשאיר חתיכה להפריש ממנה אחרי שבת. אולם, בא\"י אסור לאכול וצריך ללוות משכנים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":9,"xmlIndex":16,"text":"סיפור אמיתי: אשתך הכינה את החלות הטעימות ביותר לכבוד שבת, אבל היא שכחה להפריש חלה – האם מותר לאכול את החלה?","spans":[{"text":"סיפור אמיתי: אשתך הכינה את החלות הטעימות ביותר לכבוד שבת, אבל היא שכחה להפריש "},{"text":"חלה","italic":true},{"text":" – האם מותר לאכול את החלה?"}],"marker":"4)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":10,"xmlIndex":18,"text":"השו\"ע (11) פסק שבחו\"ל מותר לאכול את החלה ולהשאיר חתיכה להפריש ממנה אחרי שבת. אולם, בא\"י אסור לאכול וצריך ללוות משכנים.","spans":[{"text":"השו\"ע (11) פסק שבחו\"ל מותר לאכול את ה","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" ולהשאיר חתיכה להפריש ממנה אחרי שבת. אולם, בא\"י אסור לאכול וצריך ללוות משכנים.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":8,"xmlIndex":8,"text":"סיפור אמיתי: אשתך הכינה את החלות הטעימות ביותר לכבוד שבת, אבל היא שכחה להפריש חלה – האם מותר לאכול את החלה? _______________________________________________","spans":[{"text":"סיפור אמיתי: אשתך הכינה את החלות הטעימות ביותר לכבוד שבת, אבל היא שכחה להפריש "},{"text":"חלה","italic":true},{"text":" – האם מותר לאכול את החלה? _______________________________________________"}],"marker":"4)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":9,"xmlIndex":9,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[11],"approved_hash":"db2103c3b785d89b30f83e8e769ddb775ab914056c4b182384b4f65cf3c2569a"},{"chunk_code":"HC1-Q5","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"נתינת חלות לאחרים בלי הפרשה","chunk_summary":"לרב ולרבנית בקהילה שלך נולד תינוק. אשתך המדהימה החליטה להכין להם את החלה המשובחת שלה לכבוד שבת יחד עם החלות שהיא הכינה לעצמכם, אבל היא שכחה להפריש חלה. הבעיה היא שאתה ואשתך יצאתם לשבת ואין לך דרך להודיע להם ונזכרת רק בליל שבת. מה לעשות? האם מועיל שיש איתכם חלה?","content_markdown":"5) לרב ולרבנית בקהילה שלך נולד תינוק. אשתך המדהימה החליטה להכין להם את החלה המשובחת שלה לכבוד שבת יחד עם החלות שהיא הכינה לעצמכם, אבל היא שכחה להפריש *חלה*. הבעיה היא שאתה ואשתך יצאתם לשבת ואין לך דרך להודיע להם ונזכרת רק בליל שבת. מה לעשות? האם מועיל שיש איתכם חלה?\n\nאם הבאת איתך חלה מאותה עיסה שלא הופרש ממנה *חלה* ואתה בחו\"ל, עליך להשאיר קצת מהחלה עד אחרי שבת ולהפריש מהנשאר, בין על מה שאתה אכלת ובין על מה שנתת לרב והרבנית. אם אתה גר בא\"י, יש 2 בעיות. ראשית, אסור להפריש ממקום אחד על מקום אחר, ושנית, אסור להפריש בשבת. אף על פי כן, **ברוך אומר** (14) פסק שיש להפריש, הואיל ובדיעבד הפרשה ממקום אחד על מקום אחר מועילה, ועדיף שתעבור על שני איסורים קלים מאשר שהרב (או אפילו חבר) יעבור על איסור חמור יותר. אמנם, ראה סיכום לפרטים נוספים שם הבאנו שיש חולקים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":11,"xmlIndex":20,"text":"לרב ולרבנית בקהילה שלך נולד תינוק. אשתך המדהימה החליטה להכין להם את החלה המשובחת שלה לכבוד שבת יחד עם החלות שהיא הכינה לעצמכם, אבל היא שכחה להפריש חלה. הבעיה היא שאתה ואשתך יצאתם לשבת ואין לך דרך להודיע להם ונזכרת רק בליל שבת. מה לעשות? האם מועיל שיש איתכם חלה?","spans":[{"text":"לרב ולרבנית בקהילה שלך נולד תינוק. אשתך המדהימה החליטה להכין להם את החלה המשובחת שלה לכבוד שבת יחד עם החלות שהיא הכינה לעצמכם, אבל היא שכחה להפריש "},{"text":"חלה","italic":true},{"text":". הבעיה היא שאתה ואשתך יצאתם לשבת ואין לך דרך להודיע להם ונזכרת רק בליל שבת. מה לעשות? האם מועיל שיש איתכם חלה?"}],"marker":"5)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":12,"xmlIndex":22,"text":"אם הבאת איתך חלה מאותה עיסה שלא הופרש ממנה חלה ואתה בחו\"ל, עליך להשאיר קצת מהחלה עד אחרי שבת ולהפריש מהנשאר, בין על מה שאתה אכלת ובין על מה שנתת לרב והרבנית. אם אתה גר בא\"י, יש 2 בעיות. ראשית, אסור להפריש ממקום אחד על מקום אחר, ושנית, אסור להפריש בשבת. אף על פי כן, ברוך אומר (14) פסק שיש להפריש, הואיל ובדיעבד הפרשה ממקום אחד על מקום אחר מועילה, ועדיף שתעבור על שני איסורים קלים מאשר שהרב (או אפילו חבר) יעבור על איסור חמור יותר. אמנם, ראה סיכום לפרטים נוספים שם הבאנו שיש חולקים.","spans":[{"text":"אם הבאת איתך חלה מאותה עיסה שלא הופרש ממנה ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" ואתה בחו\"ל, עליך להשאיר קצת מהחלה עד אחרי שבת ולהפריש מהנשאר, בין על מה שאתה אכלת ובין על מה שנתת לרב והרבנית. אם אתה גר בא\"י, יש 2 בעיות. ראשית, אסור להפריש ממקום אחד על מקום אחר, ושנית, אסור להפריש בשבת. אף על פי כן, ","color":"#C00000"},{"text":"ברוך אומר","bold":true,"color":"#C00000"},{"text":" (14) פסק שיש להפריש, הואיל ובדיעבד הפרשה ממקום אחד על מקום אחר מועילה, ועדיף שתעבור על שני איסורים קלים מאשר שהרב (או אפילו חבר) יעבור על איסור חמור יותר. אמנם, ראה סיכום לפרטים נוספים שם הבאנו שיש חולקים.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":10,"xmlIndex":10,"text":"לרב ולרבנית בקהילה שלך נולד תינוק. אשתך המדהימה החליטה להכין להם את החלה המשובחת שלה לכבוד שבת יחד עם החלות שהיא הכינה לעצמכם, אבל היא שכחה להפריש חלה. הבעיה היא שאתה ואשתך יצאתם לשבת ואין לך דרך להודיע להם ונזכרת רק בליל שבת. מה לעשות? האם מועיל שיש איתכם חלה? ___________________________________________________","spans":[{"text":"לרב ולרבנית בקהילה שלך נולד תינוק. אשתך המדהימה החליטה להכין להם את החלה המשובחת שלה לכבוד שבת יחד עם החלות שהיא הכינה לעצמכם, אבל היא שכחה להפריש "},{"text":"חלה","italic":true},{"text":". הבעיה היא שאתה ואשתך יצאתם לשבת ואין לך דרך להודיע להם ונזכרת רק בליל שבת. מה לעשות? האם מועיל שיש איתכם חלה? ___________________________________________________"}],"marker":"5)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":11,"xmlIndex":11,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[14],"approved_hash":"58fc811340287e8023f8614147ffdb5ea724f88179fdf868f395ab0e293c99a6"},{"chunk_code":"HC1-Q6","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"שכחו להפריש חלה ממצות בליל פסח","chunk_summary":"אתה אופה מצות עם החבר ה'פרומער' שלך ואתה אומר לו: \"אני קונה מצות שלא הפרישו מהן חלה כדי שלאחר מכן אשתי תוכל לברך על המצוה\". הוא אומר לך, \"זו טעות של 'פרומער מתחיל'; אתה תשכח להפריש\". האם הוא צודק – מה לעשות אם אתה נזכר בליל פסח? כיצד מקרה זה שונה מזה של חלה בשבת?","content_markdown":"6) אתה אופה מצות עם החבר ה'פרומער' שלך ואתה אומר לו: \"אני קונה מצות שלא הפרישו מהן *חלה* כדי שלאחר מכן אשתי תוכל לברך על המצוה\". הוא אומר לך, \"זו טעות של 'פרומער מתחיל'; אתה תשכח להפריש\". האם הוא צודק – מה לעשות אם אתה נזכר בליל פסח? כיצד מקרה זה שונה מזה של חלה בשבת?\n\nאם אתה גר בחו\"ל ואתה לא יודע מאיזו עיסה הגיעה כל מצה, ה**משנ\"ב** (17) פסק שיש להשאיר מעט מכל מצה ובחול המועד להניח את החתיכות בקערה ולהפריש מכולם.\n\nאם אתה גר בא\"י, יש 3 פתרונות אפשריים: 1) **רשז\"א** (18) פסק שאם אין דרך אחרת להשיג מצה, מותר להפריש כדי לאפשר את קיום המצווה דאורייתא של אכילת מצה. הוא מוסיף שכאשר מפרישים בא\"י ביו\"ט, ראוי לקרוא שם *חלה* במחשבה בלבד ולא להוציא בפה וכן לא לברך (אבל את מעשה ההפרשה צריך לעשות). 2) **חלת לחם** (20) כתב שאתה יכול לתת את המצה לבן בגיל 12 או לבת בגיל 11 שהם יפרישו *חלה*. זה מותר מפני שהם בגיל בו ההפרשה תקפה, ולפי הרשב\"א מותר לקטן לעבור על איסור דרבנן לצורך עצמו. 3) **רשז\"א** (3) הציע שרב בכל קהילה יפריש *חלה* ממש לפני פסח ויכוון שזה יחול עבור כל אלו ששכחו. ראה סיכום לפרטים נוספים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":13,"xmlIndex":24,"text":"אתה אופה מצות עם החבר ה'פרומער' שלך ואתה אומר לו: \"אני קונה מצות שלא הפרישו מהן חלה כדי שלאחר מכן אשתי תוכל לברך על המצוה\". הוא אומר לך, \"זו טעות של 'פרומער מתחיל'; אתה תשכח להפריש\". האם הוא צודק – מה לעשות אם אתה נזכר בליל פסח? כיצד מקרה זה שונה מזה של חלה בשבת?","spans":[{"text":"אתה אופה מצות עם החבר ה'פרומער' שלך ואתה אומר לו: \"אני קונה מצות שלא הפרישו מהן "},{"text":"חלה","italic":true},{"text":" כדי שלאחר מכן אשתי תוכל לברך על המצוה\". הוא אומר לך, \"זו טעות של 'פרומער מתחיל'; אתה תשכח להפריש\". האם הוא צודק – מה לעשות אם אתה נזכר בליל פסח? כיצד מקרה זה שונה מזה של חלה בשבת?"}],"marker":"6)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":14,"xmlIndex":26,"text":"אם אתה גר בחו\"ל ואתה לא יודע מאיזו עיסה הגיעה כל מצה, המשנ\"ב (17) פסק שיש להשאיר מעט מכל מצה ובחול המועד להניח את החתיכות בקערה ולהפריש מכולם.","spans":[{"text":"אם אתה גר בחו\"ל ואתה לא יודע מאיזו עיסה הגיעה כל מצה, ה","color":"#C00000"},{"text":"משנ\"ב","bold":true,"color":"#C00000"},{"text":" (17) פסק שיש להשאיר מעט מכל מצה ובחול המועד להניח את החתיכות בקערה ולהפריש מכולם.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36},{"kind":"answer","paragraph":15,"xmlIndex":28,"text":"אם אתה גר בא\"י, יש 3 פתרונות אפשריים: 1) רשז\"א (18) פסק שאם אין דרך אחרת להשיג מצה, מותר להפריש כדי לאפשר את קיום המצווה דאורייתא של אכילת מצה. הוא מוסיף שכאשר מפרישים בא\"י ביו\"ט, ראוי לקרוא שם חלה במחשבה בלבד ולא להוציא בפה וכן לא לברך (אבל את מעשה ההפרשה צריך לעשות). 2) חלת לחם (20) כתב שאתה יכול לתת את המצה לבן בגיל 12 או לבת בגיל 11 שהם יפרישו חלה. זה מותר מפני שהם בגיל בו ההפרשה תקפה, ולפי הרשב\"א מותר לקטן לעבור על איסור דרבנן לצורך עצמו. 3) רשז\"א (3) הציע שרב בכל קהילה יפריש חלה ממש לפני פסח ויכוון שזה יחול עבור כל אלו ששכחו. ראה סיכום לפרטים נוספים.","spans":[{"text":"אם אתה גר בא\"י, יש 3 פתרונות אפשריים: 1) ","color":"#C00000"},{"text":"רשז\"א","bold":true,"color":"#C00000"},{"text":" (18) פסק שאם אין דרך אחרת להשיג מצה, מותר להפריש כדי לאפשר את קיום המצווה דאורייתא של אכילת מצה. הוא מוסיף שכאשר מפרישים בא\"י ביו\"ט, ראוי לקרוא שם ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" במחשבה בלבד ולא להוציא בפה וכן לא לברך (אבל את מעשה ההפרשה צריך לעשות). 2) ","color":"#C00000"},{"text":"חלת לחם","bold":true,"color":"#C00000"},{"text":" (20) כתב שאתה יכול לתת את המצה לבן בגיל 12 או לבת בגיל 11 שהם יפרישו ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":". זה מותר מפני שהם בגיל בו ההפרשה תקפה, ולפי הרשב\"א מותר לקטן לעבור על איסור דרבנן לצורך עצמו. 3) ","color":"#C00000"},{"text":"רשז\"א","bold":true,"color":"#C00000"},{"text":" (3) הציע שרב בכל קהילה יפריש ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" ממש לפני פסח ויכוון שזה יחול עבור כל אלו ששכחו. ראה סיכום לפרטים נוספים.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":12,"xmlIndex":13,"text":"אתה אופה מצות עם החבר ה'פרומער' שלך ואתה אומר לו: \"אני קונה מצות שלא הפרישו מהן חלה כדי שלאחר מכן אשתי תוכל לברך על המצוה\". הוא אומר לך, \"זו טעות של 'פרומער מתחיל'; אתה תשכח להפריש\". האם הוא צודק – מה לעשות אם אתה נזכר בליל פסח? כיצד מקרה זה שונה מזה של חלה בשבת? ________________________________________________________","spans":[{"text":"אתה אופה מצות עם החבר ה'פרומער' שלך ואתה אומר לו: \"אני קונה מצות שלא הפרישו מהן "},{"text":"חלה","italic":true},{"text":" כדי שלאחר מכן אשתי תוכל לברך על המצוה\". הוא אומר לך, \"זו טעות של 'פרומער מתחיל'; אתה תשכח להפריש\". האם הוא צודק – מה לעשות אם אתה נזכר בליל פסח? כיצד מקרה זה שונה מזה של חלה בשבת? ________________________________________________________"}],"marker":"6)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":13,"xmlIndex":14,"text":"____________________________________________________________________ ","spans":[{"text":"____________________________________________________________________"},{"text":" ","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[3,17,18,20],"approved_hash":"dae9e461e4feb055ec18276a25a51ad426c6c55043c5c491d348221562673af6"},{"chunk_code":"HC1-Q7","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ג","chunk_title":"מצות מארץ ישראל שנשלחו לספרד","chunk_summary":"סיפור אמיתי: נופש פסח מאורגן בישראל הזמינו 500 קופסאות של מצות כדי לקחת לנופש בספרד. בליל הסדר, המשגיח נזכר שהוא שכח להפריש חלה – מה עליו לעשות?","content_markdown":"7) סיפור אמיתי: נופש פסח מאורגן בישראל הזמינו 500 קופסאות של מצות כדי לקחת לנופש בספרד. בליל הסדר, המשגיח נזכר שהוא שכח להפריש *חלה* – מה עליו לעשות?\n\nה**רמב\"ם** פסק שחיוב הפרשת *חלה* תלוי במקום בו הכינו מהקמח עיסה. הואיל והקמח הנ\"ל נעשה עיסה בא\"י, יהיה צורך להשתמש באחת האפשרויות שנמנו בתשובה הקודמת. אולם, **חשב האפוד** (23) בשם הב\"ח הבין את הרמב\"ם אחרת ופסק שאם הוציאו לחם מא\"י, יש לו מעמד כשל לחם חו\"ל, ומותר לאכול מכל מצה ולהשאיר מעט, כפי שהציע ה**משנ\"ב** (17). אולם, **משפטי ארץ** (פ\"ט, א) פסק כמו הבנת הכסף משנה ברמב\"ם לעיל, ויהיה אסור להפריש.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":16,"xmlIndex":30,"text":"סיפור אמיתי: נופש פסח מאורגן בישראל הזמינו 500 קופסאות של מצות כדי לקחת לנופש בספרד. בליל הסדר, המשגיח נזכר שהוא שכח להפריש חלה – מה עליו לעשות?","spans":[{"text":"סיפור אמיתי: נופש פסח מאורגן בישראל הזמינו 500 קופסאות של מצות כדי לקחת לנופש בספרד. בליל הסדר, המשגיח נזכר שהוא שכח להפריש "},{"text":"חלה","italic":true},{"text":" – מה עליו לעשות?"}],"marker":"7)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":17,"xmlIndex":32,"text":"הרמב\"ם פסק שחיוב הפרשת חלה תלוי במקום בו הכינו מהקמח עיסה. הואיל והקמח הנ\"ל נעשה עיסה בא\"י, יהיה צורך להשתמש באחת האפשרויות שנמנו בתשובה הקודמת. אולם, חשב האפוד (23) בשם הב\"ח הבין את הרמב\"ם אחרת ופסק שאם הוציאו לחם מא\"י, יש לו מעמד כשל לחם חו\"ל, ומותר לאכול מכל מצה ולהשאיר מעט, כפי שהציע המשנ\"ב (17). אולם, משפטי ארץ (פ\"ט, א) פסק כמו הבנת הכסף משנה ברמב\"ם לעיל, ויהיה אסור להפריש.","spans":[{"text":"ה","color":"#C00000"},{"text":"רמב\"ם","bold":true,"color":"#C00000"},{"text":" פסק שחיוב הפרשת ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" תלוי במקום בו הכינו מהקמח עיסה. הואיל והקמח הנ\"ל נעשה עיסה בא\"י, יהיה צורך להשתמש באחת האפשרויות שנמנו בתשובה הקודמת. אולם, ","color":"#C00000"},{"text":"חשב האפוד","bold":true,"color":"#C00000"},{"text":" (23) בשם הב\"ח הבין את הרמב\"ם אחרת ופסק שאם הוציאו לחם מא\"י, יש לו מעמד כשל לחם חו\"ל, ומותר לאכול מכל מצה ולהשאיר מעט, כפי שהציע ה","color":"#C00000"},{"text":"משנ\"ב","bold":true,"color":"#C00000"},{"text":" (17). אולם, ","color":"#C00000"},{"text":"משפטי ארץ","bold":true,"color":"#C00000"},{"text":" (פ\"ט, א) פסק כמו הבנת הכסף משנה ברמב\"ם לעיל, ויהיה אסור להפריש.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":14,"xmlIndex":15,"text":"סיפור אמיתי: נופש פסח מאורגן בישראל הזמינו 500 קופסאות של מצות כדי לקחת לנופש בספרד. בליל הסדר, המשגיח נזכר שהוא שכח להפריש חלה – מה עליו לעשות? ___________________","spans":[{"text":"סיפור אמיתי: נופש פסח מאורגן בישראל הזמינו 500 קופסאות של מצות כדי לקחת לנופש בספרד. בליל הסדר, המשגיח נזכר שהוא שכח להפריש "},{"text":"חלה","italic":true},{"text":" – מה עליו לעשות? ___________________"}],"marker":"7)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":15,"xmlIndex":16,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[17,23],"approved_hash":"3134ccdf024e2c579437f41715a71934191a15d4509132350713efb306463d24"},{"chunk_code":"HC1-Q8","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ד","chunk_title":"כמה חלה מפרישים","chunk_summary":"מזל טוב! הבת שלך חגגה בת-מצוה וזו הפעם הראשונה שהיא מפרישה חלה. היא שואלת, \"אתה הולך ל'סמיכת-חבר'; כמה אני צריכה להפריש?\" מה אתה עונה?","content_markdown":"8) מזל טוב! הבת שלך חגגה בת-מצוה וזו הפעם הראשונה שהיא מפרישה *חלה*. היא שואלת, \"אתה הולך ל'סמיכת-חבר'; כמה אני צריכה להפריש?\" מה אתה עונה?\n\nלמרות שהשו\"ע והרמ\"א נחלקו בעניין, בימינו בין האשכנזים ובין הספרדים (30) פסקו שניתן להפריש כל כמות שהיא ולשרוף, אבל המנהג הוא להפריש כזית.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":18,"xmlIndex":34,"text":"מזל טוב! הבת שלך חגגה בת-מצוה וזו הפעם הראשונה שהיא מפרישה חלה. היא שואלת, \"אתה הולך ל'סמיכת-חבר'; כמה אני צריכה להפריש?\" מה אתה עונה?","spans":[{"text":"מזל טוב! הבת שלך חגגה בת-מצוה וזו הפעם הראשונה שהיא מפרישה "},{"text":"חלה","italic":true},{"text":". היא שואלת, \"אתה הולך ל'סמיכת-חבר'; כמה אני צריכה להפריש?\" מה אתה עונה?"}],"marker":"8)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":19,"xmlIndex":36,"text":"למרות שהשו\"ע והרמ\"א נחלקו בעניין, בימינו בין האשכנזים ובין הספרדים (30) פסקו שניתן להפריש כל כמות שהיא ולשרוף, אבל המנהג הוא להפריש כזית.","spans":[{"text":"למרות שהשו\"ע והרמ\"א נחלקו בעניין, בימינו בין האשכנזים ובין הספרדים (30) פסקו שניתן להפריש כל כמות שהיא ולשרוף, אבל המנהג הוא להפריש כזית.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":16,"xmlIndex":17,"text":"מזל טוב! הבת שלך חגגה בת-מצוה וזו הפעם הראשונה שהיא מפרישה חלה. היא שואלת, \"אתה הולך ל'סמיכת-חבר'; כמה אני צריכה להפריש?\" מה אתה עונה? ________________________","spans":[{"text":"מזל טוב! הבת שלך חגגה בת-מצוה וזו הפעם הראשונה שהיא מפרישה "},{"text":"חלה","italic":true},{"text":". היא שואלת, \"אתה הולך ל'סמיכת-חבר'; כמה אני צריכה להפריש?\" מה אתה עונה? ________________________"}],"marker":"8)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":17,"xmlIndex":18,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[30],"approved_hash":"50a7b42db2bde6569bdb586cb46215ef86827b6a1f35d71248fdf2db6655e05a"},{"chunk_code":"HC1-Q9","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ד","chunk_title":"אכילת חלה בידי כהן בימינו","chunk_summary":"האם יש מקרה בו מותר לכהן לקבל בימינו חלה ולאכול אותה?","content_markdown":"9) האם יש מקרה בו מותר לכהן לקבל בימינו *חלה* ולאכול אותה?\n\nהשו\"ע (29) פסק שכהן שאיננו טמא בטומאה היוצאת מגופו מותר לקבל ולאכול *חלה* אבל רק בחו\"ל. הרמ\"א כתב שכאשר הוא עושה כן יש לברך ברכה מיוחדת, אבל כפי שהוזכר בתשובה הקודמת, המנהג בימינו הוא להפריש ולשרוף.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":20,"xmlIndex":38,"text":"האם יש מקרה בו מותר לכהן לקבל בימינו חלה ולאכול אותה?","spans":[{"text":"האם יש מקרה בו מותר לכהן לקבל בימינו "},{"text":"חלה","italic":true},{"text":" ולאכול אותה?"}],"marker":"9)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":21,"xmlIndex":40,"text":"השו\"ע (29) פסק שכהן שאיננו טמא בטומאה היוצאת מגופו מותר לקבל ולאכול חלה אבל רק בחו\"ל. הרמ\"א כתב שכאשר הוא עושה כן יש לברך ברכה מיוחדת, אבל כפי שהוזכר בתשובה הקודמת, המנהג בימינו הוא להפריש ולשרוף.","spans":[{"text":"השו\"ע (29) פסק שכהן שאיננו טמא בטומאה היוצאת מגופו מותר לקבל ולאכול ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" אבל רק בחו\"ל. הרמ\"א כתב שכאשר הוא עושה כן יש לברך ברכה מיוחדת, אבל כפי שהוזכר בתשובה הקודמת, המנהג בימינו הוא להפריש ולשרוף.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":18,"xmlIndex":19,"text":"האם יש מקרה בו מותר לכהן לקבל בימינו חלה ולאכול אותה? _________________________","spans":[{"text":"האם יש מקרה בו מותר לכהן לקבל בימינו "},{"text":"חלה","italic":true},{"text":" ולאכול אותה? _________________________"}],"marker":"9)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":19,"xmlIndex":20,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[29],"approved_hash":"9681587b88b2e4d7088b6c3f28929f6a8e479fd72620926247d0944860c80800"},{"chunk_code":"HC1-Q10","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"מה עושים עם הבצק שהופרש","chunk_summary":"אחרי שהבת שלך מפרישה חלה בפעם הראשונה, היא שואלת אותך, \"מה אני עושה עכשיו עם הבצק?\" מה התשובה שלך?","content_markdown":"10) אחרי שהבת שלך מפרישה *חלה* בפעם הראשונה, היא שואלת אותך, \"מה אני עושה עכשיו עם הבצק?\" מה התשובה שלך?\n\nהשו\"ע והרמ\"א פסקו שיש לשרוף את ה*חלה*. אם זה לא אפשרי, ה**גרע\"י** (35) פסק שיש להפריש פחות מכזית (מפני שחובת שריפת *חלה* שייכת רק אם יש ב*חלה* שיעור כזית ומעלה), לשים בשקית פלסטיק, ולזרוק לפח. ה**מנחת יצחק** ו**שש\"כ** כתבו שאם אין דרך לשרוף את ה*חלה* ניתן לזרוק אותה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":22,"xmlIndex":42,"text":"אחרי שהבת שלך מפרישה חלה בפעם הראשונה, היא שואלת אותך, \"מה אני עושה עכשיו עם הבצק?\" מה התשובה שלך?","spans":[{"text":"אחרי שהבת שלך מפרישה "},{"text":"חלה","italic":true},{"text":" בפעם הראשונה, היא שואלת אותך, \"מה אני עושה עכשיו עם הבצק?\" מה התשובה שלך?"}],"marker":"10)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":23,"xmlIndex":44,"text":"השו\"ע והרמ\"א פסקו שיש לשרוף את החלה. אם זה לא אפשרי, הגרע\"י (35) פסק שיש להפריש פחות מכזית (מפני שחובת שריפת חלה שייכת רק אם יש בחלה שיעור כזית ומעלה), לשים בשקית פלסטיק, ולזרוק לפח. המנחת יצחק ושש\"כ כתבו שאם אין דרך לשרוף את החלה ניתן לזרוק אותה.","spans":[{"text":"השו\"ע והרמ\"א פסקו שיש לשרוף את ה","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":". אם זה לא אפשרי, ה","color":"#C00000"},{"text":"גרע\"י","bold":true,"color":"#C00000"},{"text":" (35) פסק שיש להפריש פחות מכזית (מפני שחובת שריפת ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" שייכת רק אם יש ב","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" שיעור כזית ומעלה), לשים בשקית פלסטיק, ולזרוק לפח. ה","color":"#C00000"},{"text":"מנחת יצחק ","bold":true,"color":"#C00000"},{"text":"ו","color":"#C00000"},{"text":"שש\"כ","bold":true,"color":"#C00000"},{"text":" כתבו שאם אין דרך לשרוף את ה","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" ניתן לזרוק אותה.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":20,"xmlIndex":21,"text":"אחרי שהבת שלך מפרישה חלה בפעם הראשונה, היא שואלת אותך, \"מה אני עושה עכשיו עם הבצק?\" מה התשובה שלך? ________________________________________________","spans":[{"text":"אחרי שהבת שלך מפרישה "},{"text":"חלה","italic":true},{"text":" בפעם הראשונה, היא שואלת אותך, \"מה אני עושה עכשיו עם הבצק?\" מה התשובה שלך? ________________________________________________"}],"marker":"10)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":21,"xmlIndex":22,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[35],"approved_hash":"ce537a5d1bd3f45dbe1680dced43a15501d6308b5b31d6a88d7539de074aa659"},{"chunk_code":"HC1-Q11","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"נייר אלומיניום שנקרע בתנור","chunk_summary":"סיפור אמיתי: אתה עוטף את החלה בנייר אלומיניום ושורף אותה בתנור, אבל כשאתה מוציא אותה, אתה שם לב שהבצק תפח ונייר האלומיניום נקרע. האם מותר לאכול את המאכל האחר שאפית בתנור באותו זמן? ומה לגבי הרשת עליה החלה הייתה מונחת?","content_markdown":"11) סיפור אמיתי: אתה עוטף את ה*חלה* בנייר אלומיניום ושורף אותה בתנור, אבל כשאתה מוציא אותה, אתה שם לב שהבצק תפח ונייר האלומיניום נקרע. האם מותר לאכול את המאכל האחר שאפית בתנור באותו זמן? ומה לגבי הרשת עליה ה*חלה* הייתה מונחת?\n\nמותר לאכול את המאכל האחר שנאפה בתנור הואיל ואין בעיה של ריחא או זיעה. ונבאר: אין בעיה של ריחא הואיל ובדיעבד (כשהמאכלים כבר נאפו ביחד), לא חוששים לריחא (ראה שו\"ע יו\"ד סימן קח). כמו כן, אין בעיה של זיעה, הואיל והבצק איננו נוזלי ואינו פולט זיעה. על פי זה, **חיי הלוי** (33) פסק שהמאכלים האחרים בתנור מותרים. אולם, הרשת שבאה במגע ישיר עם ה*חלה* טעונה הכשרה. יש אחרונים, כגון **הפרשת חלה כהלכתה** (עמ' קה), החולקים על ר' משה וסוברים שגם לחם מוציא אדים ובמקרה שנקרע נייר האלומיניום כל האוכל שבתנור, כולל התנור עצמו, נאסר.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":24,"xmlIndex":46,"text":"סיפור אמיתי: אתה עוטף את החלה בנייר אלומיניום ושורף אותה בתנור, אבל כשאתה מוציא אותה, אתה שם לב שהבצק תפח ונייר האלומיניום נקרע. האם מותר לאכול את המאכל האחר שאפית בתנור באותו זמן? ומה לגבי הרשת עליה החלה הייתה מונחת?","spans":[{"text":"סיפור אמיתי: אתה עוטף את ה"},{"text":"חלה","italic":true},{"text":" בנייר אלומיניום ושורף אותה בתנור, אבל כשאתה מוציא אותה, אתה שם לב שהבצק תפח ונייר האלומיניום נקרע. האם מותר לאכול את המאכל האחר שאפית בתנור באותו זמן? ומה לגבי הרשת עליה ה"},{"text":"חלה","italic":true},{"text":" הייתה מונחת?"}],"marker":"11)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":25,"xmlIndex":48,"text":"מותר לאכול את המאכל האחר שנאפה בתנור הואיל ואין בעיה של ריחא או זיעה. ונבאר: אין בעיה של ריחא הואיל ובדיעבד (כשהמאכלים כבר נאפו ביחד), לא חוששים לריחא (ראה שו\"ע יו\"ד סימן קח). כמו כן, אין בעיה של זיעה, הואיל והבצק איננו נוזלי ואינו פולט זיעה. על פי זה, חיי הלוי (33) פסק שהמאכלים האחרים בתנור מותרים. אולם, הרשת שבאה במגע ישיר עם החלה טעונה הכשרה. יש אחרונים, כגון הפרשת חלה כהלכתה (עמ' קה), החולקים על ר' משה וסוברים שגם לחם מוציא אדים ובמקרה שנקרע נייר האלומיניום כל האוכל שבתנור, כולל התנור עצמו, נאסר.","spans":[{"text":"מותר לאכול את המאכל האחר שנאפה בתנור הואיל ואין בעיה של ריחא או זיעה. ונבאר: אין בעיה של ריחא הואיל ובדיעבד (כשהמאכלים כבר נאפו ביחד), לא חוששים לריחא (ראה שו\"ע יו\"ד סימן קח). כמו כן, אין בעיה של זיעה, הואיל והבצק איננו נוזלי ואינו פולט זיעה. על פי זה, ","color":"#C00000"},{"text":"חיי הלוי","bold":true,"color":"#C00000"},{"text":" (33) פסק שהמאכלים האחרים בתנור מותרים. אולם, הרשת שבאה במגע ישיר עם ה","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" טעונה הכשרה. יש אחרונים, כגון ","color":"#C00000"},{"text":"הפרשת חלה כהלכתה","bold":true,"color":"#C00000"},{"text":" (עמ' קה), החולקים על ר' משה וסוברים שגם לחם מוציא אדים ובמקרה שנקרע נייר האלומיניום כל האוכל שבתנור, כולל התנור עצמו, נאסר.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":22,"xmlIndex":23,"text":"סיפור אמיתי: אתה עוטף את החלה בנייר אלומיניום ושורף אותה בתנור, אבל כשאתה מוציא אותה, אתה שם לב שהבצק תפח ונייר האלומיניום נקרע. האם מותר לאכול את המאכל האחר שאפית בתנור באותו זמן? ומה לגבי הרשת עליה החלה הייתה מונחת? ________________________","spans":[{"text":"סיפור אמיתי: אתה עוטף את ה"},{"text":"חלה","italic":true},{"text":" בנייר אלומיניום ושורף אותה בתנור, אבל כשאתה מוציא אותה, אתה שם לב שהבצק תפח ונייר האלומיניום נקרע. האם מותר לאכול את המאכל האחר שאפית בתנור באותו זמן? ומה לגבי הרשת עליה ה"},{"text":"חלה","italic":true},{"text":" הייתה מונחת? ________________________"}],"marker":"11)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":23,"xmlIndex":24,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[33],"approved_hash":"82013d3f48ebf3c8bf4f7562bfa82074245e8286d288e1646bff1052ca6d5b71"},{"chunk_code":"HC1-Q12","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"חלה במדורת ביעור חמץ","chunk_summary":"אתה משליך את הפרשת החלה שלך לתוך המדורה של שריפת חמץ כשהחבר ה'פרומער' שלך צועק, \"הלו! אתה הורס לנו הכל! אנחנו כבר לא יכולים לשרוף את החמץ!\" על מה הוא מדבר?","content_markdown":"12) אתה משליך את הפרשת ה*חלה* שלך לתוך המדורה של שריפת חמץ כשהחבר ה'פרומער' שלך צועק, \"הלו! אתה הורס לנו הכל! אנחנו כבר לא יכולים לשרוף את החמץ!\" על מה הוא מדבר?\n\n**חלקת בנימין** (34) מעלה שאלה שאם אדם זורק *חלה* לשרפת חמץ, יהיה אסור לאחרים להשליך שם את החמץ מפני שבכך הם נהנים מתוספת האש שנוצרת משריפת ה*חלה*. הוא עונה שיש להתיר משני טעמים: 1) בדרך כלל האש גדולה וחמה מאוד גם בלי תוספת הבצק, ולכן אתה לא נהנה מתוספת הלהבות שיוצרת ה*חלה*. 2) אפילו אם אתה נהנה מתוספת האש שנגרמה על ידי שריפת ה*חלה*, הואיל ומצוות לאו ליהנות נתנו, שימוש באש לקיים מצוות ביעור חמץ לא נותן לך הנאה אסורה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":26,"xmlIndex":50,"text":"אתה משליך את הפרשת החלה שלך לתוך המדורה של שריפת חמץ כשהחבר ה'פרומער' שלך צועק, \"הלו! אתה הורס לנו הכל! אנחנו כבר לא יכולים לשרוף את החמץ!\" על מה הוא מדבר?","spans":[{"text":"אתה משליך את הפרשת ה"},{"text":"חלה","italic":true},{"text":" שלך לתוך המדורה של שריפת חמץ כשהחבר ה'פרומער' שלך צועק, \"הלו! אתה הורס לנו הכל! אנחנו כבר לא יכולים לשרוף את החמץ!\" על מה הוא מדבר?"}],"marker":"12)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":27,"xmlIndex":52,"text":"חלקת בנימין (34) מעלה שאלה שאם אדם זורק חלה לשרפת חמץ, יהיה אסור לאחרים להשליך שם את החמץ מפני שבכך הם נהנים מתוספת האש שנוצרת משריפת החלה. הוא עונה שיש להתיר משני טעמים: 1) בדרך כלל האש גדולה וחמה מאוד גם בלי תוספת הבצק, ולכן אתה לא נהנה מתוספת הלהבות שיוצרת החלה. 2) אפילו אם אתה נהנה מתוספת האש שנגרמה על ידי שריפת החלה, הואיל ומצוות לאו ליהנות נתנו, שימוש באש לקיים מצוות ביעור חמץ לא נותן לך הנאה אסורה.","spans":[{"text":"חלקת בנימין","bold":true,"color":"#C00000"},{"text":" (34) מעלה שאלה שאם אדם זורק ","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":" לשרפת חמץ, יהיה אסור לאחרים להשליך שם את החמץ מפני שבכך הם נהנים מתוספת האש שנוצרת משריפת ה","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":". הוא עונה שיש להתיר משני טעמים: 1) בדרך כלל האש גדולה וחמה מאוד גם בלי תוספת הבצק, ולכן אתה לא נהנה מתוספת הלהבות שיוצרת ה","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":". 2) אפילו אם אתה נהנה מתוספת האש שנגרמה על ידי שריפת ה","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":", הואיל ומצוות לאו ליהנות נתנו, שימוש באש לקיים מצוות ביעור חמץ לא נותן לך הנאה אסורה.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":24,"xmlIndex":25,"text":"אתה משליך את הפרשת החלה שלך לתוך המדורה של שריפת חמץ כשהחבר ה'פרומער' שלך צועק, \"הלו! אתה הורס לנו הכל! אנחנו כבר לא יכולים לשרוף את החמץ!\" על מה הוא מדבר? _________","spans":[{"text":"אתה משליך את הפרשת ה"},{"text":"חלה","italic":true},{"text":" שלך לתוך המדורה של שריפת חמץ כשהחבר ה'פרומער' שלך צועק, \"הלו! אתה הורס לנו הכל! אנחנו כבר לא יכולים לשרוף את החמץ!\" על מה הוא מדבר? _________"}],"marker":"12)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":25,"xmlIndex":26,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[34],"approved_hash":"af12a0099a6f9ee33094497973013a76bd9f7e8341399bcf5aa4445242a14701"},{"chunk_code":"HC1-Q13","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ה","chunk_title":"מזלג ששימש לשריפת חלה","chunk_summary":"אשתך מבקשת ממך להוציא את הפרשת החלה מהתנור, אז אתה תוחב בזה מזלג. אתה שומע את אשתך צועקת, \"אתה מטריף לי את הכלים!\" האם המזלג אכן לא כשר יותר? כיצד מכשירים אותו?","content_markdown":"13) אשתך מבקשת ממך להוציא את הפרשת ה*חלה* מהתנור, אז אתה תוחב בזה מזלג. אתה שומע את אשתך צועקת, \"אתה מטריף לי את הכלים!\" האם המזלג אכן לא כשר יותר? כיצד מכשירים אותו?\n\n**אמרי יעקב** (38) פסק שהמזלג טרף ומן הסתם טעון ליבון.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":28,"xmlIndex":54,"text":"אשתך מבקשת ממך להוציא את הפרשת החלה מהתנור, אז אתה תוחב בזה מזלג. אתה שומע את אשתך צועקת, \"אתה מטריף לי את הכלים!\" האם המזלג אכן לא כשר יותר? כיצד מכשירים אותו?","spans":[{"text":"אשתך מבקשת ממך להוציא את הפרשת ה"},{"text":"חלה","italic":true},{"text":" מהתנור, אז אתה תוחב בזה מזלג. אתה שומע את אשתך צועקת, \"אתה מטריף לי את הכלים!\" האם המזלג אכן לא כשר יותר? כיצד מכשירים אותו?"}],"marker":"13)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":29,"xmlIndex":56,"text":"אמרי יעקב (38) פסק שהמזלג טרף ומן הסתם טעון ליבון.","spans":[{"text":"אמרי יעקב","bold":true,"color":"#C00000"},{"text":" (38) פסק שהמזלג טרף ומן הסתם טעון ליבון.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":26,"xmlIndex":27,"text":"אשתך מבקשת ממך להוציא את הפרשת החלה מהתנור, אז אתה תוחב בזה מזלג. אתה שומע את אשתך צועקת, \"אתה מטריף לי את הכלים!\" האם המזלג אכן לא כשר יותר? כיצד מכשירים אותו? __","spans":[{"text":"אשתך מבקשת ממך להוציא את הפרשת ה"},{"text":"חלה","italic":true},{"text":" מהתנור, אז אתה תוחב בזה מזלג. אתה שומע את אשתך צועקת, \"אתה מטריף לי את הכלים!\" האם המזלג אכן לא כשר יותר? כיצד מכשירים אותו? __"}],"marker":"13)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":27,"xmlIndex":28,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[38],"approved_hash":"82e7182fc7c6f5912cf0edc2673e1bbbf1fedf328680baa1776a062b1ae4b18d"},{"chunk_code":"HC1-Q14","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ו","chunk_title":"גודל העיסה החייבת בחלה","chunk_summary":"איזה גודל של עיסה צריך כדי להתחייב בהפרשת חלה?","content_markdown":"14) איזה גודל של עיסה צריך כדי להתחייב בהפרשת *חלה*?\n\nה**גמרא עירובין** (41) מלמדת שעיסה צריכה להיות לכל הפחות 1/10 מאיפה כדי להתחייב ב*חלה*, שזה שווה ל-43.2 ביצים.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":30,"xmlIndex":58,"text":"איזה גודל של עיסה צריך כדי להתחייב בהפרשת חלה?","spans":[{"text":"איזה גודל של עיסה צריך כדי להתחייב בהפרשת "},{"text":"חלה","italic":true},{"text":"?"}],"marker":"14)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":31,"xmlIndex":60,"text":"הגמרא עירובין (41) מלמדת שעיסה צריכה להיות לכל הפחות 1/10 מאיפה כדי להתחייב בחלה, שזה שווה ל-43.2 ביצים.","spans":[{"text":"ה","color":"#C00000"},{"text":"גמרא עירובין","bold":true,"color":"#C00000"},{"text":" (41) מלמדת שעיסה צריכה להיות לכל הפחות 1/10 מאיפה כדי להתחייב ב","color":"#C00000"},{"text":"חלה","italic":true,"color":"#C00000"},{"text":", שזה שווה ל-43.2 ביצים.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":28,"xmlIndex":29,"text":"איזה גודל של עיסה צריך כדי להתחייב בהפרשת חלה? ______________________________","spans":[{"text":"איזה גודל של עיסה צריך כדי להתחייב בהפרשת "},{"text":"חלה","italic":true},{"text":"? ______________________________"}],"marker":"14)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":29,"xmlIndex":30,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[41],"approved_hash":"686bff3f355f0a2dd1815ac169e20ab4009569f213f7b61cb2f5b3f9cd2d3175"},{"chunk_code":"HC1-Q15","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ו","chunk_title":"שיעורי החזון איש","chunk_summary":"החזון איש הבטיח שלא יפלו טילים בבני-ברק. לפני כמה שנים נפל בבני-ברק רסיס של טיל. רצו מהר לר' חיים קנייבסקי ושאלו \"תראה נפל טיל! מה קרה להבטחת החזו\"א?\" ר' חיים הסתכל על זה ואמר, \"זה קטן מדי, זה לא שיעור חזון איש\". למה מידות החזו\"א גדולות כל כך?","content_markdown":"15) החזון איש הבטיח שלא יפלו טילים בבני-ברק. לפני כמה שנים נפל בבני-ברק רסיס של טיל. רצו מהר לר' חיים קנייבסקי ושאלו \"תראה נפל טיל! מה קרה להבטחת החזו\"א?\" ר' חיים הסתכל על זה ואמר, \"זה קטן מדי, זה לא שיעור חזון איש\". למה מידות החזו\"א גדולות כל כך?\n\nה**גמרא פסחים** (42) מלמדת שנפח של רביעית (1/4 מלוג) הוא רוחב 2 אצבעות על 2 אצבעות על 2 אצבעות ו7/10 אצבע, שזה שווה לנפח של **10.8** **אצבעות מרובעות** (2X2X2.7). על פי חישוב זה (כשרוחב אצבע הוא 2.5 ס\"מ), שיעור של 1/10 האיפה שווה ל-4.86 ליטר. אולם כאשר מודדים לפי נפח של ביצה ממוצעת (52 cc), נפח של 1/10 האיפה שווה ל-2.5 ליטר! לכן ה**צל\"ח** (44) וה**חזו\"א** (45) מסיקים ששיעור הביצים התקטן כמעט בחצי. אם הביצים של חז\"ל היה כפולים משיעורם כיום, אזי הנפח של 2 הגמרות הללו מקביל. הצל\"ח מסיק שהואיל וכזית הוא חצי גודל ביצה של חז\"ל, כזית כיום הוא שיעור של ביצה בת ימינו. אולם, ראה סיכום ליישוב לפי דעת ר' חיים נאה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":32,"xmlIndex":62,"text":"החזון איש הבטיח שלא יפלו טילים בבני-ברק. לפני כמה שנים נפל בבני-ברק רסיס של טיל. רצו מהר לר' חיים קנייבסקי ושאלו \"תראה נפל טיל! מה קרה להבטחת החזו\"א?\" ר' חיים הסתכל על זה ואמר, \"זה קטן מדי, זה לא שיעור חזון איש\". למה מידות החזו\"א גדולות כל כך?","spans":[{"text":"החזון איש הבטיח שלא יפלו טילים בבני-ברק. לפני כמה שנים נפל בבני-ברק רסיס של טיל. רצו מהר לר' חיים קנייבסקי ושאלו \"תראה נפל טיל! מה קרה להבטחת החזו\"א?\" ר' חיים הסתכל על זה ואמר, \"זה קטן מדי, זה לא שיעור חזון איש\". למה מידות החזו\"א גדולות כל כך?"}],"marker":"15)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":33,"xmlIndex":64,"text":"הגמרא פסחים (42) מלמדת שנפח של רביעית (1/4 מלוג) הוא רוחב 2 אצבעות על 2 אצבעות על 2 אצבעות ו7/10 אצבע, שזה שווה לנפח של 10.8 אצבעות מרובעות (2X2X2.7). על פי חישוב זה (כשרוחב אצבע הוא 2.5 ס\"מ), שיעור של 1/10 האיפה שווה ל-4.86 ליטר. אולם כאשר מודדים לפי נפח של ביצה ממוצעת (52 cc), נפח של 1/10 האיפה שווה ל-2.5 ליטר! לכן הצל\"ח (44) והחזו\"א (45) מסיקים ששיעור הביצים התקטן כמעט בחצי. אם הביצים של חז\"ל היה כפולים משיעורם כיום, אזי הנפח של 2 הגמרות הללו מקביל. הצל\"ח מסיק שהואיל וכזית הוא חצי גודל ביצה של חז\"ל, כזית כיום הוא שיעור של ביצה בת ימינו. אולם, ראה סיכום ליישוב לפי דעת ר' חיים נאה.","spans":[{"text":"ה","color":"#C00000"},{"text":"גמרא פסחים","bold":true,"color":"#C00000"},{"text":" (42) מלמדת שנפח של רביעית (1/4 מלוג) הוא רוחב 2 אצבעות על 2 אצבעות על 2 אצבעות ו7/10 אצבע, שזה שווה לנפח של ","color":"#C00000"},{"text":"10.8","bold":true,"color":"#C00000"},{"text":" ","color":"#C00000"},{"text":"אצבעות מרובעות","bold":true,"color":"#C00000"},{"text":" (2X2X2.7). על פי חישוב זה (כשרוחב אצבע הוא 2.5 ס\"מ), שיעור של 1/10 האיפה שווה ל-4.86 ליטר. אולם כאשר מודדים לפי נפח של ביצה ממוצעת (52 cc), נפח של 1/10 האיפה שווה ל-2.5 ליטר! לכן ה","color":"#C00000"},{"text":"צל\"ח","bold":true,"color":"#C00000"},{"text":" (44) וה","color":"#C00000"},{"text":"חזו\"א","bold":true,"color":"#C00000"},{"text":" (45) מסיקים ששיעור הביצים התקטן כמעט בחצי. אם הביצים של חז\"ל היה כפולים משיעורם כיום, אזי הנפח של 2 הגמרות הללו מקביל. הצל\"ח מסיק שהואיל וכזית הוא חצי גודל ביצה של חז\"ל, כזית כיום הוא שיעור של ביצה בת ימינו. אולם, ראה סיכום ליישוב לפי דעת ר' חיים נאה.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":30,"xmlIndex":31,"text":"החזון איש הבטיח שלא יפלו טילים בבני-ברק. לפני כמה שנים נפל בבני-ברק רסיס של טיל. רצו מהר לר' חיים קנייבסקי ושאלו \"תראה נפל טיל! מה קרה להבטחת החזו\"א?\" ר' חיים הסתכל על זה ואמר, \"זה קטן מדי, זה לא שיעור חזון איש\". למה מידות החזו\"א גדולות כל כך? __________________","spans":[{"text":"החזון איש הבטיח שלא יפלו טילים בבני-ברק. לפני כמה שנים נפל בבני-ברק רסיס של טיל. רצו מהר לר' חיים קנייבסקי ושאלו \"תראה נפל טיל! מה קרה להבטחת החזו\"א?\" ר' חיים הסתכל על זה ואמר, \"זה קטן מדי, זה לא שיעור חזון איש\". למה מידות החזו\"א גדולות כל כך? __________________"}],"marker":"15)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":31,"xmlIndex":32,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[42,44,45],"approved_hash":"ce8e609eca0b93378c68982c2f1b93778eb2144bd40696eba6ce2fc59d1eac08"},{"chunk_code":"HC1-Q16","source_type":"qa","language":"he","workbook_title":"הפרשת חלה - חלק א","section_title":"ו","chunk_title":"שיעור מצה בליל הסדר","chunk_summary":"זה ליל הסדר ואתה עומד לאכול מצה. הבן שלך שואל, \"האם אנו פוסקים כמו החזו\"א? כמה מצה עלי לאכול?\" מה אתה עונה?","content_markdown":"16) זה ליל הסדר ואתה עומד לאכול מצה. הבן שלך שואל, \"האם אנו פוסקים כמו החזו\"א? כמה מצה עלי לאכול?\" מה אתה עונה?\n\n**ביאור הלכה** (47) פסק שלגבי מצוות דאורייתא, יש להשתמש בשיעור של הצל\"ח. לכן, לכזית ראשון של מצה יש להשתמש בשיעור הגדול יותר, אבל לאכילת אפיקומן שזו מצווה דרבנן אין צרוך בשיעור הגדול. אמנם, מנהג ירושלים הוא להשתמש תמיד בשיעור ר' חיים נאה.","content_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":34,"xmlIndex":66,"text":"זה ליל הסדר ואתה עומד לאכול מצה. הבן שלך שואל, \"האם אנו פוסקים כמו החזו\"א? כמה מצה עלי לאכול?\" מה אתה עונה?","spans":[{"text":"זה ליל הסדר ואתה עומד לאכול מצה. הבן שלך שואל, \"האם אנו פוסקים כמו החזו\"א? כמה מצה עלי לאכול?\" מה אתה עונה?"}],"marker":"16)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"answer","paragraph":35,"xmlIndex":68,"text":"ביאור הלכה (47) פסק שלגבי מצוות דאורייתא, יש להשתמש בשיעור של הצל\"ח. לכן, לכזית ראשון של מצה יש להשתמש בשיעור הגדול יותר, אבל לאכילת אפיקומן שזו מצווה דרבנן אין צרוך בשיעור הגדול. אמנם, מנהג ירושלים הוא להשתמש תמיד בשיעור ר' חיים נאה.","spans":[{"text":"ביאור הלכה","bold":true,"color":"#C00000"},{"text":" (47) פסק שלגבי מצוות דאורייתא, יש להשתמש בשיעור של הצל\"ח. לכן, לכזית ראשון של מצה יש להשתמש בשיעור הגדול יותר, אבל לאכילת אפיקומן שזו מצווה דרבנן אין צרוך בשיעור הגדול. אמנם, מנהג ירושלים הוא להשתמש תמיד בשיעור ר' חיים נאה.","color":"#C00000"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"question_document":{"version":1,"language":"he","blocks":[{"kind":"question","paragraph":32,"xmlIndex":33,"text":"זה ליל הסדר ואתה עומד לאכול מצה. הבן שלך שואל, \"האם אנו פוסקים כמו החזו\"א? כמה מצה עלי לאכול?\" מה אתה עונה? ___________________________________________________","spans":[{"text":"זה ליל הסדר ואתה עומד לאכול מצה. הבן שלך שואל, \"האם אנו פוסקים כמו החזו\"א? כמה מצה עלי לאכול?\" מה אתה עונה? ___________________________________________________"}],"marker":"16)","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36,"hanging":18},{"kind":"paragraph","paragraph":33,"xmlIndex":34,"text":"____________________________________________________________________","spans":[{"text":"____________________________________________________________________"}],"marker":"","level":0,"indent":36,"firstLine":0,"leadingTabs":0,"alignment":"right","rtl":true,"footnoteIds":[],"defaultTabWidth":36}],"footnotes":[]},"source_file_name":"שות הלכות הפרשת חלה - חלק א.docx","source_numbers":[47],"approved_hash":"3ebcc8acd7037d8c3a649a59a7d2414066cc22ce8754153a813eb8a026b59fe9"}]$hebrew_payload$::jsonb;
  english_before text; english_after text;
begin
  if jsonb_array_length(payload)<>48 or exists(select 1 from jsonb_array_elements(payload) r
    where r->>'language'<>'he' or r->>'chunk_code' !~ '^HC1-([A-E][0-9]+|Q([1-9]|1[0-6]))$' or r->>'source_type' not in ('notes','qa')) then
    raise exception 'Invalid approved Hebrew import';
  end if;
  if (select count(distinct c.id) from jsonb_array_elements(payload) r join public.content_chunks c
    on c.chunk_code=r->>'chunk_code' and c.program_id='winter-5787' and c.workbook_title='Hafrashas Challah Part 1'
      and c.source_type::text=r->>'source_type' and c.language='en')<>48 then
    raise exception 'Approved English canonical chunks are missing or mismatched. Nothing was imported';
  end if;
  select md5(coalesce(jsonb_agg(to_jsonb(c) order by c.id)::text,'')) into english_before from public.content_chunks c;
  insert into public.content_chunk_translations(chunk_id,language,workbook_title,section_title,chunk_title,chunk_summary,
    content_markdown,content_document,question_document,source_file_name,source_numbers,approved_hash)
  select c.id,'he',r.workbook_title,r.section_title,r.chunk_title,r.chunk_summary,r.content_markdown,r.content_document,
    r.question_document,r.source_file_name,r.source_numbers,r.approved_hash
  from jsonb_to_recordset(payload) r(chunk_code text,source_type text,workbook_title text,section_title text,chunk_title text,
    chunk_summary text,content_markdown text,content_document jsonb,question_document jsonb,source_file_name text,source_numbers integer[],approved_hash text)
  join public.content_chunks c on c.chunk_code=r.chunk_code and c.program_id='winter-5787'
  on conflict(chunk_id,language) do update set workbook_title=excluded.workbook_title,section_title=excluded.section_title,
    chunk_title=excluded.chunk_title,chunk_summary=excluded.chunk_summary,content_markdown=excluded.content_markdown,
    content_document=excluded.content_document,question_document=excluded.question_document,source_file_name=excluded.source_file_name,
    source_numbers=excluded.source_numbers,approved_hash=excluded.approved_hash,updated_at=now()
  where public.content_chunk_translations.approved_hash is distinct from excluded.approved_hash;
  select md5(coalesce(jsonb_agg(to_jsonb(c) order by c.id)::text,'')) into english_after from public.content_chunks c;
  if english_before is distinct from english_after then raise exception 'English content changed unexpectedly. Import rolled back'; end if;
end;
$hebrew_import$;
commit;
